(141, 23, 75, NULL, 0, 0, 'cong-tac-cam-ung-cong-suat-lon-dieu-khien-tu-xa', 'Công tắc cảm ứng công suất lớn điều khiển từ xa', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">C&ocirc;ng tắc cảm ứng c&ocirc;ng suất lớn điều khiển từ xa</h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">C&ocirc;ng tắc cảm ứng c&ocirc;ng suất lớn điều khiển từ xa</h1>\n', 'ctcul_20150518055607.png.webp', 'resize_ctcul_20150518055607.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 12, 1, 1, '2015-05-18', '2015-05-18', NULL, '.webp', NULL, NULL),
(142, 23, 76, NULL, 0, 0, 'cong-tac-cam-ung-1-nut-thong-minh-elite', 'Công tắc cảm ứng 1 nút thông minh', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/cong-tac-cam-ung-1-nut-thong-minh-p-40\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Công tắc cảm ứng 1 nút thông minh\">C&ocirc;ng tắc cảm ứng 1 n&uacute;t th&ocirc;ng minh</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"margin: 0px; font-family: Tahoma, Roboto, sans-serif; line-height: 20px; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"margin: 0px 0px 0px 40px; font-family: inherit; font-weight: bold; line-height: 40px; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"margin: 0px; font-family: inherit; line-height: 20px; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"margin: 0px; font-family: inherit; line-height: 20px; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"margin: 0px; font-family: inherit; line-height: 20px; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"margin: 0px; font-family: inherit; line-height: 20px; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'elite 1_20150518060534.png.webp', 'resize_elite 1_20150518060534.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 0, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL),
(143, 23, 76, NULL, 0, 0, 'cong-tac-cam-ung-2-nut-thong-minh-elite', 'Công tắc cảm ứng 2 nút thông minh', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/cong-tac-cam-ung-2-nut-thong-minh-p-39\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Công tắc cảm ứng 2 nút thông minh\">C&ocirc;ng tắc cảm ứng 2 n&uacute;t th&ocirc;ng minh</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'e2_20150518062721.png.webp', 'resize_e2_20150518062721.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 2, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL),
(144, 23, 76, NULL, 0, 0, 'cong-tac-cam-ung-3-nut-thong-minh-elite', 'Công tắc cảm ứng 3 nút thông minh', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/cong-tac-cam-ung-3-nut-thong-minh-p-38\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Công tắc cảm ứng 3 nút thông minh\">C&ocirc;ng tắc cảm ứng 3 n&uacute;t th&ocirc;ng minh</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'e3_20150518062808.png.webp', 'resize_e3_20150518062808.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 3, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL);
INSERT INTO `toandanh_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `nid_weight`, `ctype`, `ccode`, `cproducts`, `eng_cproducts`, `ctag`, `nview`, `fprice`, `fprice_sale`, `nquantity`, `cdescription`, `eng_cdescription`, `cmodel`, `cpower`, `eng_cdetail`, `cdetail`, `cimage`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nnew`, `nkm`, `npb`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `clink`, `cproduct_fb`, `nid_sub_menu`, `clink_shoppe`) VALUES
(145, 23, 76, NULL, 0, 0, 'cong-tac-cam-ung-4-nut-thong-minh-elite', 'Công tắc cảm ứng 4 nút thông minh', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/cong-tac-cam-ung-4-nut-thong-minh-p-46\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Công tắc cảm ứng 4 nút thông minh\">C&ocirc;ng tắc cảm ứng 4 n&uacute;t th&ocirc;ng minh</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'e4_20150518062852.png.webp', 'resize_e4_20150518062852.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 0, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL),
(146, 23, 76, NULL, 0, 0, 'chiet-ap-cam-ung-thong-minh-elite', 'Chiết áp cảm ứng thông minh', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/chiet-ap-cam-ung-thong-minh-p-47\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Chiết áp cảm ứng thông minh\">Chiết &aacute;p cảm ứng th&ocirc;ng minh</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'e5_20150518062945.png.webp', 'resize_e5_20150518062945.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 4, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL),
(147, 23, 76, NULL, 0, 0, 'cong-tac-rem-cam-ung-thong-minh', 'Công tắc rèm cảm ứng thông minh', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/cong-tac-rem-cam-ung-thong-minh-p-48\" style=\"color: orange; text-decoration: none; outline: 0px;\" title=\"Công tắc rèm cảm ứng thông minh\">C&ocirc;ng tắc r&egrave;m cảm ứng th&ocirc;ng minh</a></h1>\n', '', NULL, '', '', '<p>&nbsp;</p>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<p>&nbsp;</p>\n', 'e6_20150518063058.png.webp', 'resize_e6_20150518063058.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 6, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL);
INSERT INTO `toandanh_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `nid_weight`, `ctype`, `ccode`, `cproducts`, `eng_cproducts`, `ctag`, `nview`, `fprice`, `fprice_sale`, `nquantity`, `cdescription`, `eng_cdescription`, `cmodel`, `cpower`, `eng_cdetail`, `cdetail`, `cimage`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nnew`, `nkm`, `npb`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `clink`, `cproduct_fb`, `nid_sub_menu`, `clink_shoppe`) VALUES
(148, 23, 76, NULL, 0, 0, 'cong-tac-cam-ung-cong-suat-lon-thong-minh-elite', 'Công tắc cảm ứng công suất lớn thông minh', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/cong-tac-cam-ung-cong-suat-lon-thong-minh-p-62\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Công tắc cảm ứng công suất lớn thông minh\">C&ocirc;ng tắc cảm ứng c&ocirc;ng suất lớn th&ocirc;ng minh</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'e7_20150518063205.png.webp', 'resize_e7_20150518063205.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 0, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL),
(149, 23, 76, NULL, 0, 0, 'o-cam-doi-hat-mang-tivi-dien-thoai-elite', 'Ổ cắm đôi, hạt mạng, tivi, điện thoại', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/o-cam-doi-hat-mang-tivi-dien-thoai-p-63\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Ổ cắm đôi, hạt mạng, tivi, điện thoại\">Ổ cắm đ&ocirc;i, hạt mạng, tivi, điện thoại</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'e8_20150518063253.png.webp', 'resize_e8_20150518063253.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 13, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL),
(150, 23, 76, NULL, 0, 0, 'dieu-khien-tu-xa-thong-minh-elite', 'Điều khiển từ xa thông minh', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/dieu-khien-tu-xa-thong-minh-p-49\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Điều khiển từ xa thông minh\">Điều khiển từ xa th&ocirc;ng minh</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'e9_20150518063334.png.webp', 'resize_e9_20150518063334.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 11, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL);
INSERT INTO `toandanh_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `nid_weight`, `ctype`, `ccode`, `cproducts`, `eng_cproducts`, `ctag`, `nview`, `fprice`, `fprice_sale`, `nquantity`, `cdescription`, `eng_cdescription`, `cmodel`, `cpower`, `eng_cdetail`, `cdetail`, `cimage`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nnew`, `nkm`, `npb`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `clink`, `cproduct_fb`, `nid_sub_menu`, `clink_shoppe`) VALUES
(151, 23, 76, NULL, 0, 0, 'bo-dieu-khien-trung-tam-elite', 'Bộ điều khiển trung tâm', '', '', NULL, 0, 0, NULL, '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\"><a href=\"https://www.lumi.vn/bo-dieu-khien-trung-tam-p-51\" style=\"color: rgb(0, 0, 0); text-decoration: none;\" title=\"Bộ điều khiển trung tâm\">Bộ điều khiển trung t&acirc;m</a></h1>\n', '', NULL, '', '', '<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n\n<h3 style=\"line-height: 20px; margin: 0px; font-family: Tahoma, Roboto, sans-serif; color: rgb(47, 48, 49); text-rendering: optimizelegibility; font-size: 24.5px; text-align: justify;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">L&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ người Việt,&nbsp;<strong>thiết bị điện th&ocirc;ng minh</strong>&nbsp;Lumi được s&aacute;ng tạo dựa tr&ecirc;n cảm hứng thiết kế theo phong c&aacute;ch Italy cổ điển, sự sang trọng v&agrave; t&iacute;nh thuần khiết của k&iacute;nh kết hợp với v&ograve;ng s&aacute;ng ở trung t&acirc;m mang đến vẻ đẹp tỏa s&aacute;ng cho mỗi ng&ocirc;i nh&agrave; Việt. H&atilde;y chạm nhẹ, cảm nhận sự l&ocirc;i cuốn kỳ diệu v&agrave; trải nghiệm những cảm x&uacute;c mới lạ về một kh&ocirc;ng gian sống tiện nghi, hiện đại<br />\n<br />\nTiện &iacute;ch hơn bạn c&oacute; thể điều khiển c&aacute;c thiết bị điện th&ocirc;ng minh&nbsp;trong nh&agrave; th&ocirc;ng qua điều khiển từ xa. Với giao diện đơn giản, th&acirc;n thiện, dễ d&agrave;ng sử dụng, chỉ cần chiếc điều khiển từ xa tr&ecirc;n tay, ng&ocirc;i nh&agrave; thực sự l&agrave; cả một thế giới tiện nghi theo &yacute; muốn của bạn. Giờ đ&acirc;y, bạn c&oacute; thể điều khiển: bật tắt hệ thống đ&egrave;n chiếu s&aacute;ng, đ&oacute;ng mở r&egrave;m cửa, tăng giảm tốc độ quạt trần, bật tắt b&igrave;nh n&oacute;ng lạnh &ndash; điều h&ograve;a&hellip; m&agrave; kh&ocirc;ng cần phải di chuyển đến tận nơi.<br />\n<br />\nHơn thế, cũng bằng chiếc điều khiển từ xa, bạn c&oacute; thể c&agrave;i đặt ngữ cảnh điều khiển nhiều thiết bị c&ugrave;ng l&uacute;c. V&iacute; dụ, với ngữ cảnh &ldquo;tiếp kh&aacute;ch&rdquo; tại ph&iacute;m 1 tr&ecirc;n remote, khi bạn bấm ph&iacute;m 1: đ&egrave;m ch&ugrave;m s&aacute;ng l&ecirc;n, r&egrave;m tự động mở ra, điều h&ograve;a bật l&ecirc;n, d&agrave;n &acirc;m thanh bật bản nhạc du dương&hellip; Những vị kh&aacute;ch sẽ trầm trồ, th&iacute;ch th&uacute; với những hiệu ứng biến h&oacute;a bất ngờ từ mỗi căn ph&ograve;ng m&agrave; bạn tự thiết lập, v&agrave; hẳn sẽ th&aacute;n phục sự tinh tế, thời thượng của gia chủ. C&ograve;n g&igrave; tuyệt vời hơn khi giờ đ&acirc;y, chỉ cần 1 ph&iacute;m bấm tr&ecirc;n điều khiển tất cả c&aacute;c thiết bị sẽ tự hoạt động theo &yacute; muốn của bạn.<br />\n<strong>C&ocirc;ng tắc chạm cảm ứng Lumi</strong>&nbsp;ho&agrave;n to&agrave;n tương th&iacute;ch với c&aacute;c đế &acirc;m tường sẵn c&oacute; tr&ecirc;n thị trường, dễ d&agrave;ng thi c&ocirc;ng lắp đặt, ph&ugrave; hợp với điều kiện hạ tầng điện v&agrave; thời tiết nồm ẩm ở nước ta.&nbsp;<br />\n<br />\nGiải ph&aacute;p&nbsp;<em>thiết bị điện th&ocirc;ng minh</em>&nbsp;của Lumi&nbsp;đang dần trở th&agrave;nh xu thế tất yếu trong thiết kế nội thất hiện đại. H&atilde;y c&ugrave;ng Lumi n&acirc;ng tầm cuộc sống của bạn. H&atilde;y li&ecirc;n hệ ngay với Lumi Việt Nam để nhận được những lời tư vấn tốt nhất về lắp đặt v&agrave; triển khai giải ph&aacute;p&nbsp;<em>nh&agrave; th&ocirc;ng minh</em>.</span></span></h3>\n\n<p style=\"line-height: 20.7999992370605px;\"><span style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">&nbsp;</span></p>\n\n<div class=\"row\" style=\"margin-left: -30px; color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\"><img alt=\"LumiHandy - goi thiet bi dien thong minh Lumi Viet Nam\" src=\"https://www.lumi.vn/public/userfiles/images/Goi-handy-thiet-bi-dien-thong-minh.jpg\" style=\"height: auto; vertical-align: middle; border: 0px; max-width: 100%;\" /></div>\n\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h2 style=\"font-weight: bold; line-height: 40px; margin: 0px 0px 0px 40px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 18px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>T&iacute;nh năng nổi bật nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</strong></span></span></h2>\n\n<div style=\"margin-left: 40px;\"><strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 10px;\">An to&agrave;n tuyệt đối</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Mặt k&iacute;nh gia cường d&agrave;y 4mm tuyệt đối an to&agrave;n với trẻ nhỏ hoặc khi tay bị ướt.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Sang trọng - Tinh tế</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Thiết kế tối giản, hiện đại kết hợp với vẻ thuần khiết của k&iacute;nh v&agrave; &aacute;nh s&aacute;ng.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển 4 chế độ: Light, Scene, Dimmer, Curtains​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">Điều khiển đ&egrave;n (light), bật/tắt c&ugrave;ng l&uacute;c nhiều thiết bị (Scene), tăng/giảm&nbsp;độ s&aacute;ng (Dimmer), điều khiển r&egrave;m (Curtains)</span></font><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&agrave;i đặt ngữ cảnh kh&ocirc;ng giới hạn​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Điều khiển c&ugrave;ng l&uacute;c nhiều thiết bị theo kịch bản t&ugrave;y &yacute;.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Điều khiển thiết bị qua điều khiển từ xa​</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Kh&ocirc;ng cần đến tận nơi, chỉ với chiếc điều khiển từ xa.​</span></span></div>\n\n<div style=\"line-height: 10px; margin-left: 40px;\"><font face=\"arial, helvetica, sans-serif\"><span style=\"font-size: 14px;\">​</span></font><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">C&ocirc;ng nghệ cảm ứng điện dung</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Xoay nhẹ tay để bật/ tắt hoặc điều chỉnh độ s&aacute;ng đ&egrave;n​.</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Dễ d&agrave;ng thi c&ocirc;ng lắp đặt</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Th&iacute;ch hợp với tất cả c&aacute;c loại đế &acirc;m tường c&oacute; sẵn tr&ecirc;n thị trường, kh&ocirc;ng phải đi lại d&acirc;y.​</span></span><br />\n<br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Độ bền cao</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Số lần bật tắt l&ecirc;n đến hơn 100.000 lần, tuổi thọ sử dụng từ 10 - 20 năm.​<br />\n​</span></span><br />\n<strong style=\"font-family: arial, helvetica, sans-serif; font-size: 14px; line-height: 20px;\">Made in Vietnam</strong></div>\n\n<div style=\"line-height: 15px; margin-left: 40px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Sản phẩm l&agrave; th&agrave;nh quả kết tinh từ b&agrave;n tay, khối &oacute;c v&agrave; tr&iacute; tuệ Việt.​</span></span></div>\n</div>\n</div>\n\n<div style=\"color: rgb(47, 48, 49); font-family: Tahoma, Roboto, sans-serif; font-size: 12px; line-height: 20px; text-align: justify; clear: both;\">\n<div>&nbsp;</div>\n\n<div>&nbsp;</div>\n\n<div><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​</span></strong></span></div>\n\n<h2 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 31.5px;\"><span style=\"font-size: 16px;\"><strong><span style=\"font-family: arial, helvetica, sans-serif;\">​<span style=\"font-size: 18px;\">Chi tiết sản phẩm nh&agrave; th&ocirc;ng minh d&ograve;ng Handy</span></span></strong></span></h2>\n\n<div class=\"row\" style=\"margin-left: -30px;\">\n<div class=\"span6\" style=\"float: left; min-height: 1px; margin-left: 30px; width: 485px;\">\n<h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thiết bị điện th&ocirc;ng minh&nbsp;Lumi</strong>&nbsp;c&oacute; c&ocirc;ng tắc&nbsp;sử dụng c&ocirc;ng nghệ cảm ứng điện dung để điều khiển bật tắt c&aacute;c thiết bị điện trong gia đ&igrave;nh. Với bề mặt k&iacute;nh gia cường chống xước, chống va đập, kết hợp với v&ograve;ng tr&ograve;n s&aacute;ng LED trung t&acirc;m kh&ocirc;ng chỉ mang đến sự an to&agrave;n tuyệt đối m&agrave; c&ograve;n tạo n&ecirc;n sự sang trọng, tinh tế, hiện đại cho mỗi ng&ocirc;i nh&agrave; Việt. C&ocirc;ng tắc cảm ứng Lumi c&oacute; khả năng điều khiển c&aacute;c thiết bị như: hệ thống đ&egrave;n, quạt trần, b&igrave;nh n&oacute;ng lạnh, điều h&ograve;a&hellip;<br />\n<br />\n<strong>Remote</strong>&nbsp;l&agrave; thiết bị điều khiển từ xa th&ocirc;ng minh duy nhất tại Việt Nam ho&agrave;n to&agrave;n sử dụng c&aacute;c ph&iacute;m cảm ứng. Với khả năng tạo lập ngữ cảnh phối hợp điều khiển c&aacute;c thiết bị kh&ocirc;ng giới hạn, bạn c&oacute; thể dễ d&agrave;ng điều khiển c&aacute;c thiết bị trong nh&agrave; như đ&egrave;n ph&ograve;ng, đ&egrave;n ch&ugrave;m, r&egrave;m cửa... chỉ cần một chiếc Remote duy nhất. Pin sạc Li-Po với dung lượng 1100mAh, bạn ho&agrave;n to&agrave;n kh&ocirc;ng c&acirc;n phải bận t&acirc;m tới việc thay thế pin cho thiết bị. Giờ đ&acirc;y, ở bất kỳ đ&acirc;u trong ph&ograve;ng, bạn cũng c&oacute; thể bật &ndash; tắt c&aacute;c thiết bị m&agrave; kh&ocirc;ng cần phải đến tận nơi.<br />\n&nbsp;<br />\n<span style=\"font-size: 18px;\"><strong>Ch&iacute;nh s&aacute;ch bảo h&agrave;nh v&agrave; b&aacute;n h&agrave;ng:</strong></span></span></span></h3>\n\n<ul style=\"padding-right: 0px; padding-left: 0px; margin: 0px 0px 10px 25px; list-style: circle;\">\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Tất cả c&aacute;c sản phẩm Lumi đều được bảo h&agrave;nh&nbsp;<strong>24 th&aacute;ng.</strong></span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <h3 style=\"line-height: 20px; margin: 0px; font-family: inherit; color: inherit; text-rendering: optimizelegibility; font-size: 24.5px;\"><span style=\"font-size: 14px;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Cam kết 1 đổi 1</strong>&nbsp;trong suốt thời gian bảo h&agrave;nh nếu sản phẩm ph&aacute;t sinh bất kỳ lỗi kỹ thuật n&agrave;o từ nh&agrave; sản xuất.</span></span></h3>\n </li>\n <li style=\"padding: 0px 0px 11px 25px; text-align: justify;\">\n <div>&nbsp;</div>\n </li>\n</ul>\n</div>\n</div>\n</div>\n\n<h1 style=\"margin: 0px; font-family: Roboto, sans-serif; line-height: normal; color: rgb(54, 157, 85); text-rendering: optimizelegibility; font-size: 25px;\">&nbsp;</h1>\n', 'e12_20150518063429.png.webp', 'resize_e12_20150518063429.png.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 11, 1, 1, '2015-05-23', '2015-05-23', NULL, '.webp', NULL, NULL),
