(185, 20, 74, NULL, 0, 0, 'mcb', 'MCB', '', '', NULL, 0, 0, NULL, '<h1 style=\"color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; line-height: 22px; padding: 3px; margin: 0px 0px 3px; vertical-align: middle;\"><span id=\"ctl00_ContentPlaceHolder1_Label18\" style=\"color: rgb(51, 51, 51); font-size: medium; font-weight: bold;\">MCB iK60N &amp; iC60N</span></h1>\n\n<p><span id=\"ctl00_ContentPlaceHolder1_Label20\" style=\"font-family: Arial, Helvetica, sans-serif; font-size: small; line-height: 22px; text-align: justify; color: rgb(102, 102, 102);\">- MCB loại 1P, 2P, 3P, 4P c&oacute; d&ograve;ng điện định mức từ 0-63A.<br />\n- D&ugrave;ng kiểm so&aacute;t, bảo vệ qu&aacute; tải v&agrave; ngắn mạch.<br />\n- D&ugrave;ng trong mạng lưới d&acirc;n dụng, văn ph&ograve;ng v.v&hellip;<br />\n- Ti&ecirc;u chuẩn IEC 898 (iK60N)<br />\n- Ti&ecirc;u chuẩn IEC 898,IEC 947-2 (iC60)<br />\n- Điện &aacute;p thử nghiệm xung (Uimp): 4kV (iK60N), 6kV (iC60N)...<br />\n- Đường cong đặc trưng loại C ngo&agrave;i ra c&ograve;n c&oacute; đường cong loại B,D.&nbsp;</span></p>\n', '', NULL, '', '', '<h1 style=\"color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; line-height: 22px; padding: 3px; margin: 0px 0px 3px; vertical-align: middle;\"><img alt=\"\" src=\"/fileman/Uploads/mcb-ik60n-ic60nIC60N20150423082036.jpg\" style=\"width: 99px; height: 117px;\" /><img alt=\"\" src=\"/fileman/Uploads/mcb-ic60h-ic60lIC60H20150420165453.jpg\" style=\"width: 94px; height: 127px;\" /><img alt=\"\" src=\"/fileman/Uploads/mcb-easy-9image20150420163013.jpg\" style=\"width: 150px; height: 153px;\" /></h1>\n\n<h1 style=\"color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; line-height: 22px; padding: 3px; margin: 0px 0px 3px; vertical-align: middle;\"><span id=\"ctl00_ContentPlaceHolder1_Label18\" style=\"color: rgb(51, 51, 51); font-size: medium; font-weight: bold;\">MCB&nbsp;</span></h1>\n\n<p><span id=\"ctl00_ContentPlaceHolder1_Label20\" style=\"font-family: Arial, Helvetica, sans-serif; font-size: small; line-height: 22px; text-align: justify; color: rgb(102, 102, 102);\">- MCB loại 1P, 2P, 3P, 4P c&oacute; d&ograve;ng điện định mức từ 0-100A.<br />\n- D&ugrave;ng kiểm so&aacute;t, bảo vệ qu&aacute; tải v&agrave; ngắn mạch.<br />\n- D&ugrave;ng trong mạng lưới d&acirc;n dụng, văn ph&ograve;ng v.v&hellip;<br />\n- Ti&ecirc;u chuẩn IEC 898 (iK60N)<br />\n- Ti&ecirc;u chuẩn IEC 898,IEC 947-2 (iC60)<br />\n- Điện &aacute;p thử nghiệm xung (Uimp): 4kV (iK60N), 6kV (iC60N)...<br />\n- Đường cong đặc trưng loại C ngo&agrave;i ra c&ograve;n c&oacute; đường cong loại B,D.&nbsp;</span></p>\n', 'mcb-easy_20210406043529.jpg.webp', 'resize_mcb-easy_20210406043529.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 8, 748, 1, '2021-04-06', '2021-04-06', '', '.webp', NULL, NULL),
(186, 20, 74, NULL, 0, 0, 'rccb-rcbo', 'RCCB, RCBO', '', '', NULL, 0, 0, NULL, '<p>RCCB, RCBO cầu dao chống d&ograve;ng r&ograve;</p>\n', '', NULL, '', '', '<h1 style=\"color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; line-height: 22px; padding: 3px; margin: 0px 0px 3px; vertical-align: middle;\"><img alt=\"\" src=\"/fileman/Uploads/rccb-residual-current-circuit-breakerUse-web20150421162600.jpg\" style=\"width: 211px; height: 236px;\" /><img alt=\"\" src=\"/fileman/Uploads/rcbo-residual-circuit-breaker-overcurrentUse20150505151305.jpg\" style=\"width: 211px; height: 251px;\" /></h1>\n\n<h1 style=\"color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; line-height: 22px; padding: 3px; margin: 0px 0px 3px; vertical-align: middle;\"><span id=\"ctl00_ContentPlaceHolder1_Label18\" style=\"color: rgb(51, 51, 51); font-size: medium; font-weight: bold;\">RCCB - Residual Current Circuit Breaker</span></h1>\n\n<p><span id=\"ctl00_ContentPlaceHolder1_Label20\" style=\"font-family: Arial, Helvetica, sans-serif; font-size: small; line-height: 22px; text-align: justify; color: rgb(102, 102, 102);\">- &nbsp;RCCB cầu dao chống d&ograve;ng r&ograve; loại 2P,4P.<br />\n- D&ugrave;ng c&aacute;ch ly, đ&oacute;ng ngắt, chống d&ograve;ng r&ograve;.<br />\n- Ph&ugrave; hợp với ti&ecirc;u chuẩn IEC 61008-1.</span></p>\n\n<h1 style=\"color: rgb(0, 0, 0); font-family: Arial, Helvetica, sans-serif; line-height: 22px; padding: 3px; margin: 0px 0px 3px; vertical-align: middle;\"><span id=\"ctl00_ContentPlaceHolder1_Label18\" style=\"color: rgb(51, 51, 51); font-size: medium; font-weight: bold;\">RCBO - Residual Circuit Breaker Overcurrent</span></h1>\n\n<p><span id=\"ctl00_ContentPlaceHolder1_Label20\" style=\"font-family: Arial, Helvetica, sans-serif; font-size: small; line-height: 22px; text-align: justify; color: rgb(102, 102, 102);\">- Cầu dao bải vệ được t&iacute;ch hợp chống d&ograve;ng r&ograve; (RCBO).<br />\n-&nbsp;Bảo vệ qu&aacute; tải v&agrave; chống d&ograve;ng r&ograve;.<br />\n-&nbsp;Ph&ugrave; hợp với ti&ecirc;u chuẩn IEC 61009-1, 898.</span></p>\n', 'rccb_20210406043542.jpg.webp', 'resize_rccb_20210406043542.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 9, 748, 1, '2021-04-06', '2021-04-06', '', '.webp', NULL, NULL),
