(191, 24, 91, NULL, 0, 0, 'day-dong-ben-tiep-dia-soi-ep-cose', 'Dây đồng bện tiếp địa (Sợi ép cose)', '', 'dây đồng bện', NULL, 0, 0, NULL, '<p><strong>D&acirc;y đồng bện</strong> tiếp địa hay&nbsp;c&ograve;n được gọi l&agrave; sợi &eacute;p cose (copper-clad steel, viết tắt l&agrave; CCS), l&agrave; một loại d&acirc;y được sử dụng trong c&aacute;c ứng dụng điện. N&oacute; được tạo th&agrave;nh bằng c&aacute;ch bện một l&otilde;i bằng th&eacute;p được mạ lớp đồng.</p>\n', '', NULL, '', '', '<p><strong>D&acirc;y đồng bện</strong> tiếp địa hay&nbsp;c&ograve;n được gọi l&agrave; sợi &eacute;p cose (copper-clad steel, viết tắt l&agrave; CCS), l&agrave; một loại d&acirc;y được sử dụng trong c&aacute;c ứng dụng điện. N&oacute; được tạo th&agrave;nh bằng c&aacute;ch bện một l&otilde;i bằng th&eacute;p được mạ lớp đồng.</p>\n\n<p><strong>D&acirc;y đồng bện</strong> tiếp địa (sợi &eacute;p cose)&nbsp;l&agrave; sự kết hợp c&aacute;c thuộc t&iacute;nh của th&eacute;p v&agrave; đồng để tạo ra một vật liệu c&oacute; hiệu suất tiếp địa tốt. Với l&otilde;i bằng th&eacute;p, n&oacute; c&oacute; khả năng chịu tải cao, độ cứng v&agrave; độ bền cơ học tốt. Lớp phủ đồng b&ecirc;n ngo&agrave;i cung cấp khả năng dẫn điện tốt, gi&uacute;p d&acirc;y truyền tải t&iacute;n hiệu tiếp địa một c&aacute;ch hiệu quả.</p>\n\n<p>C&aacute;c ứng dụng của <strong>d&acirc;y đồng bện</strong> tiếp địa (sợi &eacute;p cose) bao gồm:</p>\n\n<p>- Hệ thống tiếp địa: D&acirc;y n&agrave;y thường được sử dụng để tạo mạng lưới tiếp địa trong hệ thống điện, nhằm cung cấp đường dẫn d&ograve;ng tiếp địa cho c&aacute;c thiết bị v&agrave; hệ thống.</p>\n\n<p>- Hệ thống chống s&eacute;t: <strong>D&acirc;y đồng bện</strong> tiếp địa c&oacute; thể được sử dụng trong c&aacute;c hệ thống chống s&eacute;t để đảm bảo đường tiếp địa hiệu quả v&agrave; giảm thiểu t&aacute;c động của s&eacute;t đ&aacute;nh.</p>\n\n<p>- C&aacute;c ứng dụng c&ocirc;ng nghiệp: <strong>D&acirc;y đồng bện</strong> tiếp địa (sợi &eacute;p cose) cũng c&oacute; thể được sử dụng trong c&aacute;c ứng dụng c&ocirc;ng nghiệp như hệ thống đường ray, hệ thống xử l&yacute; dữ liệu, hệ thống viễn th&ocirc;ng, v&agrave; nhiều ứng dụng kh&aacute;c.</p>\n\n<p><strong>D&acirc;y đồng bện </strong>tiếp địa (sợi &eacute;p cose) được lựa chọn t&ugrave;y thuộc v&agrave;o y&ecirc;u cầu v&agrave; ứng dụng cụ thể của từng hệ thống điện.</p>\n\n<p>Mặt kh&aacute;c, ch&uacute;ng t&ocirc;i c&ograve;n cung cấp <strong>d&acirc;y đồng bện</strong> tiếp địa theo m&eacute;t hoặc&nbsp;gia c&ocirc;ng sợi &eacute;p cose&nbsp;theo y&ecirc;u cầu kh&aacute;ch h&agrave;ng.</p>\n\n<p>Qu&yacute; kh&aacute;ch h&agrave;ng c&oacute; nhu cầu về sản phẩm <strong>d&acirc;y đồng bện</strong> tiếp địa xin vui l&ograve;ng li&ecirc;n hệ với c&ocirc;ng ty ch&uacute;ng t&ocirc;i để c&oacute; được sự tư vấn v&agrave; gi&aacute; cả, dịch vụ tốt nhất.</p>\n\n<div class=\"row list-product\">\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/1.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/2.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/3.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/4.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/5.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/6.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/7.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/8.png\" /></div>\n</div>\n', 'Untitled-1_20230710114904.png.webp', 'resize_Untitled-1_20230710114904.png.webp', 0, 'Dây đồng bện tiếp địa hay còn được gọi là sợi ép cose (copper-clad steel, viết tắt là CCS), là một loại dây được sử dụng trong các ứng dụng điện. Nó được tạo thành bằng cách bện một lõi bằng thép được mạ lớp đồng.', NULL, 1, 0, 0, NULL, 0, 1, 748, 1, '2024-05-24', '2024-05-24', '', 'day_dong_ben_tiep_dia_20230707033212.jpg.webp', 0, ''),
(200, 24, 94, NULL, 0, 0, 'flexible-connector-busbar-mem', 'Flexible Connector- Busbar mềm', '', '', NULL, 0, 0, NULL, '<p>&quot;Flexible Connector&quot; hoặc &quot;Busbar mềm&quot; c&ograve;n được gọi l&agrave; Thanh đồng mềm thường l&agrave; một loại kết nối dẻo v&agrave; dễ uốn, được sử dụng để kết nối giữa c&aacute;c phần tử trong hệ thống điện v&agrave; điện tử. Đ&acirc;y thường l&agrave; c&aacute;c dải mảnh đồng mềm hoặc hợp kim đồng mềm, gi&uacute;p dễ d&agrave;ng điều chỉnh vị tr&iacute; hoặc h&igrave;nh dạng để ph&ugrave; hợp với y&ecirc;u cầu cụ thể của hệ thống.</p>\n', '', NULL, '', '', '<p>&quot;<strong>Flexible Connector</strong>&quot; hoặc &quot;<strong>Busbar mềm</strong>&quot; c&ograve;n được gọi l&agrave; <strong>Thanh đồng mềm</strong> thường l&agrave; một loại kết nối dẻo v&agrave; dễ uốn, được sử dụng để kết nối giữa c&aacute;c phần tử trong hệ thống điện v&agrave; điện tử. Đ&acirc;y thường l&agrave; c&aacute;c dải mảnh đồng mềm hoặc hợp kim đồng mềm, gi&uacute;p dễ d&agrave;ng điều chỉnh vị tr&iacute; hoặc h&igrave;nh dạng để ph&ugrave; hợp với y&ecirc;u cầu cụ thể của hệ thống.</p>\n\n<p>C&aacute;c ứng dụng phổ biến của <strong>Flexible Connector - Busbar mềm</strong> bao gồm trong c&aacute;c hệ thống ph&acirc;n phối điện, tủ điện, v&agrave; c&aacute;c ứng dụng c&ocirc;ng nghiệp kh&aacute;c, n&oacute; được sử dụng để kết nối giữa c&aacute;c th&agrave;nh phần điện trong c&aacute;c ứng dụng c&ocirc;ng nghiệp v&agrave; năng lượng. Những đặc điểm linh hoạt n&agrave;y gi&uacute;p giảm thiểu &aacute;p lực cơ học v&agrave; đồng thời tối ưu h&oacute;a hiệu suất kết nối điện.</p>\n\n<p>Busbar mềm thường được sử dụng trong c&aacute;c m&ocirc;i trường cần độ linh hoạt cao v&agrave; sự dễ d&agrave;ng trong việc thay đổi cấu h&igrave;nh điện. Điều n&agrave;y c&oacute; thể bao gồm c&aacute;c hệ thống năng lượng t&aacute;i tạo, hệ thống tủ điện ph&acirc;n phối, v&agrave; c&aacute;c ứng dụng c&ocirc;ng nghiệp kh&aacute;c.</p>\n\n<p>Một số ứng dụng phổ biến của <strong>Flexible Connector - Busbar mềm</strong> bao gồm trong hệ thống ph&acirc;n phối điện, c&aacute;c thiết bị năng lượng t&aacute;i tạo, v&agrave; c&aacute;c ứng dụng c&ocirc;ng nghiệp kh&aacute;c nơi t&iacute;nh linh hoạt v&agrave; khả năng chịu đựng cao l&agrave; quan trọng.</p>\n\n<p>B&ecirc;n cạnh đ&oacute;, ch&uacute;ng t&ocirc;i c&ograve;n nhận:</p>\n\n<p>- Cung cấp d&acirc;y đồng bện c&ocirc;ng suất lớn d&ugrave;ng kết nối Busway với m&aacute;y biến &aacute;p (Flexible)</p>\n\n<p><span style=\"line-height: 20.7999992370605px;\">- Cung cấp d&acirc;y đồng bện c&ocirc;ng suất lớn chịu được độ rung lớn.</span></p>\n\n<p>- D&acirc;y đồng bện&nbsp;Kết nối Busway với trạm biến &aacute;p</p>\n\n<p><span style=\"line-height: 20.7999992370605px;\">- Gia c&ocirc;ng theo y&ecirc;u cầu của kh&aacute;c h&agrave;ng</span></p>\n\n<div class=\"row list-product\">\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/15.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/16.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/17.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/18.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/19.png\" /></div>\n\n<div class=\"col-md-3\"><img alt=\"\" src=\"/fileman/Uploads/day_dong_ben/20.png\" /></div>\n</div>\n', '20_20240529030339.png.webp', 'resize_20_20240529030339.png.webp', 0, '\"Flexible Connector\" hoặc \"Busbar mềm\" còn được gọi là Thanh đồng mềm thường là một loại kết nối dẻo và dễ uốn, được sử dụng để kết nối giữa các phần tử trong hệ thống điện và điện tử. Đây thường là các dải mảnh đồng mềm hoặc hợp kim đồng mềm, giúp dễ dàng điều chỉnh vị trí hoặc hình dạng để phù hợp với yêu cầu cụ thể của hệ thống.', NULL, 1, 0, 0, NULL, 0, 1, 748, 1, '2024-05-29', '2024-05-29', '', 'busbar-mem_20240306095129.jpg.webp', 0, ''),
(203, 26, 100, NULL, 0, 0, 'eaton-5sc-ups', 'Eaton 5SC UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 5SC UPS cung cấp bảo vệ đ&aacute;ng tin cậy v&agrave; gi&aacute; cả phải chăng với đầu ra s&oacute;ng h&igrave;nh sin tinh khiết cho c&aacute;c m&aacute;y chủ doanh nghiệp nhỏ, thiết bị lưu trữ v&agrave; mạng. Giao diện LCD cung cấp trạng th&aacute;i r&otilde; r&agrave;ng của c&aacute;c tham số ch&iacute;nh v&agrave; cho ph&eacute;p cấu h&igrave;nh cho điện &aacute;p đầu ra, cảnh b&aacute;o &acirc;m thanh v&agrave; độ nhạy đầu v&agrave;o nguồn. Bằng c&aacute;ch sử dụng phần mềm Tr&igrave;nh quản l&yacute; năng lượng th&ocirc;ng minh Eaton với 5SC, bạn sẽ c&oacute; được th&ocirc;ng tin cập nhật từng ph&uacute;t về trạng th&aacute;i nguồn điện trong mạng của m&igrave;nh</p>\n\n<p>&nbsp;</p>\n', 'Eaton-5SC_20190412101941.jpg.webp', 'resize_Eaton-5SC_20190412101941.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 2, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(204, 26, 100, NULL, 0, 0, 'eaton-3s-ups', 'Eaton 3S UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 3S cung cấp sao lưu pin cao cấp v&agrave; bảo vệ đột biến cho tối đa 10 thiết bị gia đ&igrave;nh v&agrave; văn ph&ograve;ng. Chức năng EcoControl cung cấp tiết kiệm năng lượng lớn hơn tới 30 phần trăm so với c&aacute;c bản sao lưu pin th&ocirc;ng thường v&agrave; khả năng tương th&iacute;ch plug-and-play cho ph&eacute;p t&iacute;ch hợp tự động. 3S mỏng nằm gọn g&agrave;ng dưới b&agrave;n l&agrave;m việc, trong trung t&acirc;m giải tr&iacute; hoặc tr&ecirc;n tường.</p>\n', 'Eaton-3S-UPS_20190412102102.jpg.webp', 'resize_Eaton-3S-UPS_20190412102102.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 3, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(205, 26, 100, NULL, 0, 0, 'eaton-9px-ups', 'Eaton 9PX UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Cung cấp năng lượng dự ph&ograve;ng cao cấp, chuyển đổi k&eacute;p v&agrave; thời gian sử dụng pin c&oacute; thể mở rộng cho m&aacute;y chủ, mạng thoại / dữ liệu v&agrave; hệ thống lưu trữ, Eaton 9PX UPS l&agrave; giải ph&aacute;p l&yacute; tưởng cho cả lắp đặt gi&aacute; đỡ v&agrave; độc lập. Một UPS đủ ti&ecirc;u chuẩn ENERGY STAR, giao diện LCD đồ họa của 9PX v&agrave; phần mềm quản l&yacute; năng lượng mục ti&ecirc;u mạnh mẽ gi&uacute;p quản l&yacute; UPS của bạn dễ d&agrave;ng - ngay cả trong m&ocirc;i trường ảo h&oacute;a</p>\n\n<p>&nbsp;</p>\n', 'eaton-9PX-ups_20190412102229.jpg.webp', 'resize_eaton-9PX-ups_20190412102229.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 4, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(202, 26, 100, NULL, 0, 0, 'eaton-9sx-ups', 'Eaton 9SX UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>UPS mạng Eaton 9SX tự h&agrave;o c&oacute; m&agrave;n h&igrave;nh LCD dễ đọc, cấu tr&uacute;c li&ecirc;n kết chuyển đổi k&eacute;p v&agrave; đường v&ograve;ng tĩnh b&ecirc;n trong, tất cả ở dạng UPS th&aacute;p tiện lợi với tổng chi ph&iacute; sở hữu thấp. Tương th&iacute;ch với thẻ kết nối mạng của Eaton v&agrave; phần mềm Quản l&yacute; năng lượng th&ocirc;ng minh (IPM), UPS n&agrave;y l&agrave; một phần quan trọng của bất kỳ m&ocirc;i trường CNTT vật l&yacute; hoặc ảo h&oacute;a n&agrave;o.</p>\n', '9SX3000_L_20190412101038.jpg.webp', 'resize_9SX3000_L_20190412101038.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 1, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(206, 26, 100, NULL, 0, 0, 'eaton-5s-ups', 'Eaton 5S UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Bộ lưu điện Eaton 5S nhỏ gọn, nhỏ gọn mang lại nguồn điện dự ph&ograve;ng cho m&aacute;y t&iacute;nh để b&agrave;n v&agrave; m&aacute;y trạm. Khả năng điều khiển sinh th&aacute;i của UPS nhỏ n&agrave;y cho ph&eacute;p bạn tiết kiệm tới 30% mức ti&ecirc;u thụ năng lượng. Bạn cũng c&oacute; thể tăng cường bảo vệ nguồn điện v&agrave; bảo vệ dữ liệu của bạn khi bạn gh&eacute;p nối n&oacute; với phần mềm Eaton UPS Companion. 5S hiển thị th&ocirc;ng tin quan trọng của UPS về thời gian hết pin v&agrave; theo d&otilde;i ngừng hoạt động th&ocirc;ng qua giao diện LCD th&acirc;n thiện với người d&ugrave;ng.</p>\n', 'Eaton-5S-UPS_FM_20190412102420.jpg.webp', 'resize_Eaton-5S-UPS_FM_20190412102420.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 5, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(207, 26, 100, NULL, 0, 0, 'eaton-9130-ups', 'Eaton 9130 UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Bộ lưu điện Eaton 9130 đ&atilde; hết tuổi thọ</p>\n\n<p>&nbsp;</p>\n', 'Eaton-9130-UPS_20190412102526.jpg.webp', 'resize_Eaton-9130-UPS_20190412102526.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 6, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(208, 26, 100, NULL, 0, 0, 'eaton-5p-ups', 'Eaton 5P UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 5P UPS cung cấp năng lượng dự ph&ograve;ng đ&aacute;ng tin cậy trong th&aacute;p v&agrave; c&aacute;c yếu tố h&igrave;nh thức rackmount kh&aacute;c nhau cho c&aacute;c ứng dụng CNTT d&agrave;nh cho doanh nghiệp v&agrave; ph&acirc;n t&aacute;n. L&agrave; c&ocirc;ng ty đầu ti&ecirc;n trong ng&agrave;nh tu&acirc;n thủ ti&ecirc;u chuẩn an ninh mạng UL 2900-2-2, Thẻ mạng Gigabit t&ugrave;y chọn Eaton, cung cấp khả năng gi&aacute;m s&aacute;t v&agrave; quản l&yacute; từ xa cho 5P. Khi được gh&eacute;p nối với phần mềm Eaton Intelligence Power Manager (IPM), bạn c&oacute; thể quản l&yacute; liền mạch cơ sở c&agrave;i đặt thiết bị được kết nối của m&igrave;nh, ngay cả trong m&ocirc;i trường ảo h&oacute;a. Chọn c&aacute;c mẫu 5P cũng c&oacute; sẵn với pin lithium-ion c&oacute; tuổi thọ cao, gi&uacute;p giảm bảo tr&igrave; trong suốt thời gian sử dụng của hệ thống khi so s&aacute;nh với c&aacute;c phi&ecirc;n bản axit ch&igrave;</p>\n\n<p>&nbsp;</p>\n', 'Eaton-5P-UPS_FM_20190412102641.jpg.webp', 'resize_Eaton-5P-UPS_FM_20190412102641.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 7, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(209, 26, 100, NULL, 0, 0, 'eaton-9170-ups', 'Eaton 9170+ UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>UPS mạng Eaton 9170+ cung cấp năng lượng dự ph&ograve;ng trực tuyến cao cấp v&agrave; thời gian chạy pin c&oacute; thể mở rộng cho c&aacute;c trang trại m&aacute;y chủ, mạng, viễn th&ocirc;ng, nh&agrave; cung cấp dịch vụ internet v&agrave; c&aacute;c ứng dụng quan trọng kh&aacute;c. Tận dụng thiết kế m&ocirc;-đun, 9170+ UPS cung cấp dự ph&ograve;ng N + X để loại bỏ điểm lỗi đơn cấp hệ thống. UPS mạng n&agrave;y th&iacute;ch nghi với việc thay đổi nhanh ch&oacute;ng m&ocirc;i trường CNTT với c&aacute;c m&ocirc;-đun pin v&agrave; năng lượng c&oacute; thể mở rộng.</p>\n', 'eaton-9170plus-ups_20190412102757.jpg.webp', 'resize_eaton-9170plus-ups_20190412102757.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 8, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL);
INSERT INTO `toandanh_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `nid_weight`, `ctype`, `ccode`, `cproducts`, `eng_cproducts`, `ctag`, `nview`, `fprice`, `fprice_sale`, `nquantity`, `cdescription`, `eng_cdescription`, `cmodel`, `cpower`, `eng_cdetail`, `cdetail`, `cimage`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nnew`, `nkm`, `npb`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `clink`, `cproduct_fb`, `nid_sub_menu`, `clink_shoppe`) VALUES
(210, 26, 100, NULL, 0, 0, 'eaton-5px-ups', 'Eaton 5PX UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Kết hợp khả năng thời gian chạy mở rộng v&agrave; hiệu quả vượt trội, Eaton 5PX UPS l&agrave; một giải ph&aacute;p sao lưu cấp doanh nghiệp mạnh mẽ. C&aacute;c ph&acirc;n đoạn ổ cắm được quản l&yacute; của 5PX cho ph&eacute;p bạn theo d&otilde;i mức ti&ecirc;u thụ năng lượng xuống mức ổ cắm tr&ecirc;n m&agrave;n h&igrave;nh LCD trực quan của n&oacute;, trong khi c&aacute;c g&oacute;i sẵn s&agrave;ng ảo h&oacute;a thuận tiện v&agrave; phần mềm Quản l&yacute; nguồn th&ocirc;ng minh cho ph&eacute;p quản l&yacute; liền mạch trong m&ocirc;i trường ảo h&oacute;a</p>\n\n<p>&nbsp;</p>\n', 'Eatons-5PX-UPS_FM_20190412102908.jpg.webp', 'resize_Eatons-5PX-UPS_FM_20190412102908.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 9, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(211, 26, 100, NULL, 0, 0, 'eaton-9pxm-ups', 'Eaton 9PXM UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 9PXM UPS l&agrave; một UPS m&ocirc;-đun c&oacute; thể mở rộng, kết hợp mức độ tin cậy cao nhất với chi ph&iacute; sở hữu thấp nhất. Th&ocirc;ng qua c&aacute;c m&ocirc;-đun năng lượng cắm v&agrave; chạy 4 kVA, 9PXM cung cấp mức độ dự ph&ograve;ng N + X c&oacute; thể mở rộng. 9PXM ph&ugrave; hợp với c&aacute;c vỏ th&aacute;p t&aacute;m hoặc mười hai khe dễ d&agrave;ng chuyển đổi th&agrave;nh c&aacute;c giải ph&aacute;p rackmount 14U v&agrave; 21U</p>\n\n<p>&nbsp;</p>\n', '9PXM_8and12slot_L_20190412103016.jpg.webp', 'resize_9PXM_8and12slot_L_20190412103016.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 10, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(212, 26, 100, NULL, 0, 0, 'eaton-9355-ups', 'Eaton 9355 UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 9355 UPS (trước đ&acirc;y l&agrave; Powerware 9355 UPS) cung cấp năng lượng dự ph&ograve;ng chuyển đổi k&eacute;p cao cấp v&agrave; thời gian sử dụng pin c&oacute; thể mở rộng cho cơ sở hạ tầng CNTT v&agrave; kỹ thuật điện trong c&aacute;c ứng dụng c&ocirc;ng ty, y tế, ng&acirc;n h&agrave;ng v&agrave; c&ocirc;ng nghiệp. Đ&oacute;ng g&oacute;i thời gian chạy pin tối đa v&agrave;o một dấu ch&acirc;n rất nhỏ, 9355 UPS l&agrave; một giải ph&aacute;p bảo vệ nguồn ba pha ho&agrave;n chỉnh. 9355 c&oacute; thể được trang bị một m&ocirc;-đun ph&acirc;n phối điện t&iacute;ch hợp, c&oacute; thể t&ugrave;y chỉnh bao gồm một c&ocirc;ng tắc bỏ qua bảo tr&igrave;</p>\n\n<p>&nbsp;</p>\n', 'eaton-9355-ups_20190412103117.jpg.webp', 'resize_eaton-9355-ups_20190412103117.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 11, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(213, 26, 100, NULL, 0, 0, 'eaton-emergency-lighting-ups', 'Eaton Emergency Lighting UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>C&aacute;c hệ thống chiếu s&aacute;ng khẩn cấp ph&ugrave; hợp v&agrave; hiệu quả l&agrave; rất quan trọng để tạo điều kiện thuận lợi cho người đi ra trong trường hợp khẩn cấp, chẳng hạn như hỏa hoạn t&ograve;a nh&agrave; hoặc t&igrave;nh huống nguy hiểm kh&aacute;c. Ngo&agrave;i việc ưu ti&ecirc;n an to&agrave;n, cần c&oacute; đ&egrave;n chiếu s&aacute;ng khẩn cấp th&iacute;ch hợp bằng c&aacute;c m&atilde; x&acirc;y dựng như NFPA 101, Bộ luật an to&agrave;n cuộc sống. Tin tưởng v&agrave;o c&aacute;c bộ lưu điện khẩn cấp Eaton nhiệt (10-200 kVA) để giữ an to&agrave;n cho người cư ngụ v&agrave; c&aacute;c cấu tr&uacute;c thương mại của bạn theo m&atilde;. C&aacute;c UPS chiếu s&aacute;ng khẩn cấp của ch&uacute;ng t&ocirc;i được thử nghiệm v&agrave; chứng nhận UL 924, cung cấp c&aacute;c t&ugrave;y chọn c&ocirc;ng suất cao nhất v&agrave; c&ocirc;ng suất nhỏ nhất trong ng&agrave;nh cho c&aacute;c ứng dụng chiếu s&aacute;ng khẩn cấp.</p>\n', 'eaton-ups-emergency-lighting_20190412103210.jpg.webp', 'resize_eaton-ups-emergency-lighting_20190412103210.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 12, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(214, 26, 100, NULL, 0, 0, 'eaton-9355-marine', 'Eaton 9355 Marine', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>C&ocirc;ng nghệ chuyển đổi trực tuyến k&eacute;p với xếp hạng c&ocirc;ng suất 8-40 kVA, loại DNV được ph&ecirc; duyệt, loại BV được ph&ecirc; duyệt v&agrave; thiết kế ABS được đ&aacute;nh gi&aacute; l&ecirc;n đến 15 kVA, đầu v&agrave;o v&agrave; đầu ra ba pha, in ch&acirc;n nhỏ, khả năng song song Hot Sync được cấp bằng s&aacute;ng chế l&ecirc;n đến bốn hệ thống dự ph&ograve;ng , C&ocirc;ng nghệ ABM gi&uacute;p k&eacute;o d&agrave;i tuổi thọ pin, t&ugrave;y chọn li&ecirc;n lạc rộng</p>\n\n<p>&nbsp;</p>\n', 'eaton-9355-marine-ups_20190412103337.jpg.webp', 'resize_eaton-9355-marine-ups_20190412103337.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 13, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(215, 26, 100, NULL, 0, 0, 'eaton-ferrups-ups', 'Eaton FERRUPS UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton FERRUPS cung cấp năng lượng dự ph&ograve;ng, pin dự ph&ograve;ng đ&atilde; được chứng minh v&agrave; thời gian chạy c&oacute; thể mở rộng cho c&aacute;c trung t&acirc;m 911, lắp đặt qu&acirc;n sự to&agrave;n cầu, t&agrave;u biển v&agrave; c&aacute;c ứng dụng quan trọng kh&aacute;c. Cấu h&igrave;nh cao với một loạt c&aacute;c điện &aacute;p, tần số, thời gian chạy, d&acirc;y nguồn v&agrave; ổ cắm, Eaton FERRUPS li&ecirc;n tục điều chỉnh điện &aacute;p v&agrave; loại bỏ c&aacute;c d&ograve;ng s&oacute;ng h&agrave;i c&oacute; hại</p>\n\n<p>&nbsp;</p>\n', 'Eaton-Ferrups-L_20190412103443.jpg.webp', 'resize_Eaton-Ferrups-L_20190412103443.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 14, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(216, 26, 100, NULL, 0, 0, 'eaton-9155-ups', 'Eaton 9155 UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 9155 UPS (trước đ&acirc;y l&agrave; Powerware 9155 UPS) cung cấp năng lượng dự ph&ograve;ng trực tuyến cao cấp v&agrave; thời gian sử dụng pin c&oacute; thể mở rộng cho cơ sở hạ tầng CNTT v&agrave; kỹ thuật điện trong c&aacute;c ứng dụng doanh nghiệp, y tế, ng&acirc;n h&agrave;ng v&agrave; c&ocirc;ng nghiệp. Đ&oacute;ng g&oacute;i thời gian chạy pin tối đa v&agrave;o một dấu ch&acirc;n rất nhỏ, 9155 UPS l&agrave; một giải ph&aacute;p bảo vệ nguồn ho&agrave;n chỉnh. 9155 c&oacute; thể được trang bị một m&ocirc;-đun ph&acirc;n phối điện t&iacute;ch hợp, c&oacute; thể t&ugrave;y chỉnh bao gồm một c&ocirc;ng tắc bỏ qua bảo tr&igrave;.</p>\n', 'eaton-9155-ups_20190412103532.jpg.webp', 'resize_eaton-9155-ups_20190412103532.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 15, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(217, 26, 100, NULL, 0, 0, 'eaton-bladeups', 'Eaton BladeUPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton BladeUPS l&agrave; một hệ thống UPS c&oacute; thể mở rộng v&agrave; m&ocirc; đun được thiết kế cho c&aacute;c m&ocirc;i trường điện to&aacute;n mật độ cao, bao gồm c&aacute;c trung t&acirc;m dữ liệu lớn. Xua tan một phần ba sức n&oacute;ng của c&aacute;c hệ thống UPS m&ocirc;-đun truyền thống, cấu h&igrave;nh mạnh mẽ n&agrave;y cung cấp khả năng bảo vệ năng lượng cho c&aacute;c ứng dụng quan trọng của bạn cần</p>\n\n<p>&nbsp;</p>\n', 'eaton-blade-ups_20190412103626.jpg.webp', 'resize_eaton-blade-ups_20190412103626.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 16, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(218, 26, 100, NULL, 0, 0, 'eaton-9155-marine-ups', 'Eaton 9155 Marine UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 9155 Marine UPS l&agrave; loại DNV-GL được ph&ecirc; duyệt, loại BV được ph&ecirc; duyệt v&agrave; thiết kế ABS được đ&aacute;nh gi&aacute; (tối đa 15 kVA). Với thiết kế nhỏ gọn v&agrave; pin b&ecirc;n trong, Eaton 9155 Marine UPS ph&ugrave; hợp l&yacute; tưởng với c&aacute;c ứng dụng đ&ograve;i hỏi mật độ năng lượng cao v&agrave; dấu ch&acirc;n nhỏ</p>\n\n<p>&nbsp;</p>\n', 'eaton-9155-marine-ups_20190412103820.jpg.webp', 'resize_eaton-9155-marine-ups_20190412103820.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 17, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(219, 26, 100, NULL, 0, 0, 'eaton-9phd-marine-ups', 'Eaton 9PHD Marine UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 9PHD Marine UPS l&agrave; một giải ph&aacute;p UPS hiện đại, đ&aacute;ng tin cậy v&agrave; hiệu quả, c&oacute; thể được cấu h&igrave;nh cho một loạt c&aacute;c ứng dụng h&agrave;ng hải v&agrave; ngo&agrave;i khơi. N&oacute; mang lại những lợi &iacute;ch của c&ocirc;ng nghệ UPS dựa tr&ecirc;n IGBT hiện đại, m&ocirc;-đun cho m&ocirc;i trường t&agrave;u thủy, cung cấp Tổng chi ph&iacute; sở hữu thấp nhất trong phạm vi quyền lực của n&oacute;</p>\n\n<p>&nbsp;</p>\n', 'eaton-9phd-marine_20190412103947.jpg.webp', 'resize_eaton-9phd-marine_20190412103947.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 18, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(220, 26, 100, NULL, 0, 0, 'power-xpert-9395-ups-family', 'Power Xpert 9395 UPS family', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>C&aacute;c UPS Power Xpert 9395 cung cấp hiệu quả h&agrave;ng đầu trong ng&agrave;nh v&agrave; thời gian sử dụng pin c&oacute; thể mở rộng trong một dấu ch&acirc;n nhỏ. C&aacute;c trung t&acirc;m dữ liệu lớn, ứng dụng chăm s&oacute;c sức khỏe, trung t&acirc;m dữ liệu nhiều kh&aacute;ch thu&ecirc;, c&ocirc;ng nghiệp nhẹ v&agrave; c&aacute;c hệ thống quan trọng kh&aacute;c c&oacute; thể giảm tổng chi ph&iacute; sở hữu. Theo d&otilde;i v&agrave; quản l&yacute; UPS 9395 của bạn với m&agrave;n h&igrave;nh cảm ứng LCD m&agrave;u</p>\n\n<p>&nbsp;</p>\n', '9395_20190412104049.jpg.webp', 'resize_9395_20190412104049.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 19, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(221, 26, 100, NULL, 0, 0, 'eaton-93pm-ups', 'Eaton 93PM UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 93PM UPS kết hợp hiệu quả chưa từng c&oacute;, độ tin cậy v&agrave; khả năng mở rộng theo chiều dọc hoặc ngang với thiết kế bắt mắt. Một thiết bị linh hoạt, tiết kiệm kh&ocirc;ng gian, dễ d&agrave;ng triển khai như quản l&yacute;, đ&oacute; l&agrave; một giải ph&aacute;p kh&ocirc;ng gian ba m&agrave;u trắng hoặc x&aacute;m ho&agrave;n hảo cho trung t&acirc;m dữ liệu ng&agrave;y nay</p>\n\n<p>&nbsp;</p>\n', 'eaton-93pm-ups-primary_20190412104156.jpg.webp', 'resize_eaton-93pm-ups-primary_20190412104156.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 20, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(222, 26, 100, NULL, 0, 0, 'eaton-93e-ups', 'Eaton 93E UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Eaton 93E UPS được thiết kế để gi&uacute;p c&aacute;c nh&agrave; quản l&yacute; CNTT giải quyết c&aacute;c th&aacute;ch thức lớn nhất trong trung t&acirc;m dữ liệu của họ: chi ph&iacute; năng lượng, quản l&yacute; từ xa &amp; kh&ocirc;ng gian. Nhỏ hơn tới 35% v&agrave; hiệu quả hơn 7% so với c&aacute;c đơn vị cạnh tranh, 93E cung cấp giải ph&aacute;p tiết kiệm năng lượng, tất cả trong một trong cơ thể của một UPS nhỏ gọn</p>\n\n<p>&nbsp;</p>\n', 'eaton-93e-ups_20190412104306.jpg.webp', 'resize_eaton-93e-ups_20190412104306.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 21, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(223, 26, 100, NULL, 0, 0, 'eaton-9390-ups', 'Eaton 9390 UPS', '', '', NULL, 0, 0, NULL, '', '', NULL, '', '', '<p>Bộ lưu điện Eaton 9390 tiết kiệm năng lượng (trước đ&acirc;y l&agrave; Powerware 9390 UPS) cung cấp năng lượng dự ph&ograve;ng v&agrave; thời gian sử dụng pin c&oacute; thể mở rộng trong một dấu ch&acirc;n nhỏ cho c&aacute;c trung t&acirc;m dữ liệu cỡ trung b&igrave;nh, thiết bị y tế v&agrave; c&aacute;c hệ thống quan trọng kh&aacute;c. Với Hệ thống tiết kiệm năng lượng đột ph&aacute;, 9390 hoạt động với hiệu suất 99% của UPS v&agrave; c&oacute; thể tự trả sau ba đến năm năm m&agrave; kh&ocirc;ng l&agrave;m giảm độ tin cậy. Cũng được bao gồm trong d&ograve;ng sản phẩm, Eaton 9390IT UPS thể hiện hiệu quả vượt trội v&agrave; c&aacute;c t&ugrave;y chọn ph&acirc;n phối linh hoạt trước đ&acirc;y kh&ocirc;ng c&oacute; trong c&aacute;c UPS 40 kVA đến 160 kVA</p>\n\n<p>&nbsp;</p>\n', 'eaton-9390-ups_20190412104417.jpg.webp', 'resize_eaton-9390-ups_20190412104417.jpg.webp', 0, '', NULL, 1, 0, 0, NULL, 0, 22, 1, 1, '2019-04-12', '2019-04-12', NULL, '.webp', NULL, NULL),
(233, 1, 102, NULL, 0, 0, 'may-khoan-da-nang-4-dau-m12-fddxkit-0x-2505', 'Máy khoan đa năng 4 đầu M12 FDDXKIT-0X (2505)', '', '', NULL, 7440000, 6580000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 FDDXKIT-0X</p>\n\n<p><strong>H&atilde;ng sản xuất:</strong>&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại:</strong>&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&aacute;y khoan đa năng 4 trong 1, nhỏ gọn, hiệu suất cao v&agrave; c&oacute; t&iacute;nh linh hoạt cao</li>\n	<li>Hệ thống đầu kẹp c&oacute; thể th&aacute;o rời với 4 đầu kh&aacute;c nhau d&ugrave;ng trong nhiều ứng dụng</li>\n	<li>Đầu nối lắp mũi v&iacute;t 1/4&Prime; ph&iacute;a sau bộ phận nối đầu kẹp, sẽ giảm chiều d&agrave;i mũi khoan xuống 130mm khi cần</li>\n	<li>Tay cầm thẳng để tiếp cận v&agrave; điều khiển vượt trội</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; cung cấp m&ocirc; men xoắn l&ecirc;n tới 34 Nm</li>\n	<li>Thanh giữ bằng nam ch&acirc;m để th&aacute;o lắp mũi khoan một c&aacute;ch dễ d&agrave;ng</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade; mang đến khả năng chống qu&aacute; tải kỹ thuật số ti&ecirc;n tiến cho c&ocirc;ng cụ v&agrave; pin, đồng thời n&acirc;ng cao hiệu suất của c&ocirc;ng cụ khi thực hiện c&ocirc;ng việc</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION được đ&oacute;ng g&oacute;i chắc chắn v&agrave; hiệu suất bền bỉ gi&uacute;p thời gian hoạt động l&acirc;u hơn v&agrave; ho&agrave;n th&agrave;nh khối lượng c&ocirc;ng việc nhiều hơn trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>Hệ thống pin linh hoạt: tương th&iacute;ch với tất cả c&aacute;c pin MILWAUKEE&trade; M12&trade;</li>\n</ul>\n', '1_20230704032635.jpg.webp', 'resize_1_20230704032635.jpg.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 1, NULL),
(234, 1, 102, NULL, 0, 0, 'may-khoan-dong-luc-m12-fpd-0c-2504', 'Máy khoan động lực M12 FPD-0C (2504)', '', '', NULL, 4200000, 3680000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm:</strong>&nbsp;M12 FPD-0C</p>\n\n<p><strong>H&atilde;ng sản xuất:</strong>&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại:</strong>&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&aacute;y khoan động lực 12 V hiệu quả nhất với sức mạnh c&oacute; thể thực hiện h&agrave;ng loạt ứng dụng</li>\n	<li>Trọng lượng nhẹ nhất so với c&aacute;c sản phẩm c&ugrave;ng loại mang lại t&iacute;nh di động khi đeo c&ocirc;ng cụ v&agrave; giảm mệt mỏi trong cả ng&agrave;y l&agrave;m việc</li>\n	<li>Nhỏ gọn nhất so với c&aacute;c sản phẩm c&ugrave;ng loại cho ph&eacute;p tiếp cận dễ d&agrave;ng hơn trong những kh&ocirc;ng gian chật hẹp</li>\n	<li>Đầu m&aacute;y khoan ho&agrave;n to&agrave;n bằng kim loại 13 mm gi&uacute;p giữ mũi khoan v&agrave; kẹp chặt hết cỡ</li>\n	<li>Ly hợp E mang đến độ lặp lại nhất qu&aacute;n trong c&aacute;c ứng dụng vặn v&iacute;t</li>\n	<li>Tốc độ quay 1700 v&ograve;ng/ph&uacute;t gi&uacute;p khoan nhanh hơn</li>\n	<li>Lực siết tối đa 44 Nm</li>\n</ul>\n', '1_20230704033536.webp', 'resize_1_20230704033536.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 1, NULL),
(235, 1, 102, NULL, 0, 0, 'may-khoan-goc-vuong-c12-rad-0b-2415', 'Máy khoan góc vuông C12 RAD-0B (2415)', '', '', NULL, 2880000, 2680000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm:</strong>&nbsp;C12 RAD-0B</p>\n\n<p><strong>H&atilde;ng sản xuất:</strong>&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại:</strong>&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>C&ocirc;ng nghệ pin REDLITHIUM&trade;-ION: kết cấu chắc chắn, c&aacute;c linh kiện điện tử v&agrave; hiệu suất vượt trội gi&uacute;p l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>C&ocirc;ng tắc b&oacute;p: Mang lại sự tiện lợi v&agrave; thoải m&aacute;i cho d&ugrave; c&ocirc;ng việc y&ecirc;u cầu điều g&igrave;</li>\n	<li>Ly hợp điện tử cải tiến: Cung cấp lực siết l&ecirc;n tới 12 Nm với 11 c&agrave;i đặt cộng với chế độ khoan để c&oacute; thể kiểm so&aacute;t tối ưu trong c&aacute;c ứng dụng vặn/siết</li>\n	<li>Đầu m&aacute;y khoan kẹp10 mm: Cho ph&eacute;p thay đổi đầu mũi khoan nhanh ch&oacute;ng v&agrave; dễ d&agrave;ng cũng như kẹp chặt hết cỡ</li>\n	<li>Đ&egrave;n LED t&iacute;ch hợp: Rọi s&aacute;ng bề mặt l&agrave;m việc v&agrave; cho thấy vị tr&iacute; ly hợp</li>\n</ul>\n', '1_20230704033728.webp', 'resize_1_20230704033728.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 1, NULL),
(236, 1, 102, NULL, 0, 0, 'may-siet-bu-long-goc-m12-fir12-0-2558', 'Máy siết bu lông góc M12 FIR12-0 (2558)', '', '', NULL, 5040000, 4680000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm:</strong>&nbsp;M12 FIR12-0</p>\n\n<p><strong>H&atilde;ng sản xuất:</strong>&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại:</strong>&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>C&oacute; hiệu suất như m&aacute;y siết bu l&ocirc;ng g&oacute;c d&ugrave;ng điện kh&iacute; n&eacute;n với lực siết tối đa l&ecirc;n tới 81 Nm</li>\n	<li>Thiết kế phần đầu nhỏ cho ph&eacute;p người d&ugrave;ng tiếp cận dễ d&agrave;ng hơn trong những kh&ocirc;ng gian chật hẹp</li>\n	<li>Mang lại tốc độ v&ograve;ng quay 175 v&ograve;ng/ph&uacute;t gi&uacute;p n&acirc;ng cao hiệu suất</li>\n	<li>Với C&ocirc;ng nghệ FUEL&trade; độc quyền, thiết kế chắc chắn v&agrave; phần đầu kẹp bằng th&eacute;p đ&uacute;c gi&uacute;p m&aacute;y M12 FIR12 c&oacute; độ bền lớn hơn cho người d&ugrave;ng chuy&ecirc;n nghiệp</li>\n	<li>M&aacute;y siết bu l&ocirc;ng g&oacute;c kh&ocirc;ng chổi than đầu ti&ecirc;n tr&ecirc;n thị trường, m&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; c&oacute; tuổi thọ d&agrave;i hơn gấp 2 lần</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade; ngăn ngừa hỏng h&oacute;c c&ocirc;ng cụ cũng như pin do qu&aacute; tải hoặc qu&aacute; nhiệt</li>\n	<li>Pin REDLITHIUM&trade;-ION tăng thời gian vận h&agrave;nh l&acirc;u hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của pin</li>\n	<li>C&ocirc;ng tắc t&ugrave;y biến tốc độ bằng kim loại gi&uacute;p kiểm so&aacute;t c&ocirc;ng cụ tối ưu</li>\n	<li>Lớp cao su đ&uacute;c chắc chắn cao cấp chống chịu được c&aacute;c vật liệu ăn m&ograve;n v&agrave; mang lại sự thoải m&aacute;i hơn khi sử dụng</li>\n	<li>Đ&egrave;n LED chiếu s&aacute;ng khu vực l&agrave;m việc &amp; đồng hồ đo nhi&ecirc;n liệu hiển thị thời gian vận h&agrave;nh c&ograve;n lại</li>\n	<li>Giải ph&aacute;p nhỏ gọn v&agrave; thuận tiện với chiều d&agrave;i 31,8 cm v&agrave; trọng lượng 1,4 kg khi lắp pin</li>\n</ul>\n', '1_20230704033921.webp', 'resize_1_20230704033921.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 1, NULL),
(237, 1, 102, NULL, 0, 0, 'may-siet-bu-long-goc-m12-fir14-0-2556', 'Máy siết bu lông góc M12 FIR14-0 (2556)', '', '', NULL, 4560000, 3800000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm:</strong>&nbsp;M12 FIR14-0</p>\n\n<p><strong>H&atilde;ng sản xuất:</strong>&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại:</strong>&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Lực siết tối đa l&ecirc;n tới 54 Nm</li>\n	<li>Thiết kế phần đầu nhỏ cho ph&eacute;p người d&ugrave;ng tiếp cận dễ d&agrave;ng hơn trong những kh&ocirc;ng gian chật hẹp</li>\n	<li>Mang lại tốc độ quay 250 v&ograve;ng/ph&uacute;t gi&uacute;p n&acirc;ng cao hiệu suất</li>\n	<li>Với c&ocirc;ng nghệ FUEL độc quyền, thiết kế chắc chắn với phần đầu được bọc vỏ kẹp bằng th&eacute;p đ&uacute;c gi&uacute;p m&aacute;y M12 FIR14 c&oacute; thể chống chịu được t&igrave;nh trạng ăn m&ograve;n v&agrave; rơi vỡ trong c&ocirc;ng việc h&agrave;ng ng&agrave;y tại c&ocirc;ng trường, gi&uacute;p tăng tuổi thọ của m&aacute;y</li>\n	<li>M&aacute;y siết bu l&ocirc;ng g&oacute;c kh&ocirc;ng chổi than đầu ti&ecirc;n tr&ecirc;n thị trường, m&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; c&oacute; tuổi thọ d&agrave;i hơn gấp 2 lần</li>\n	<li>Hệ thống bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; gi&uacute;p bảo vệ m&aacute;y v&agrave; pin khỏi hỏng h&oacute;c do qu&aacute; tải hoặc qu&aacute; nhiệt</li>\n	<li>Pin REDLITHIUM&trade;-ION c&oacute; khả năng l&agrave;m việc l&acirc;u hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của pin</li>\n	<li>C&ocirc;ng tắc t&ugrave;y biến tốc độ bằng kim loại gi&uacute;p kiểm so&aacute;t c&ocirc;ng cụ tối ưu</li>\n	<li>Lớp cao su đ&uacute;c chắc chắn cao cấp chống chịu được c&aacute;c vật liệu ăn m&ograve;n v&agrave; mang lại sự thoải m&aacute;i hơn khi sử dụng</li>\n	<li>Đ&egrave;n LED chiếu s&aacute;ng khu vực l&agrave;m việc &amp; đồng hồ đo nhi&ecirc;n liệu hiển thị thời gian vận h&agrave;nh c&ograve;n lại</li>\n	<li>Giải ph&aacute;p nhỏ gọn v&agrave; thuận tiện với chiều d&agrave;i 284 mm v&agrave; trọng lượng 1 kg khi lắp pin (pin kh&ocirc;ng đi k&egrave;m)</li>\n	<li>Một phần của Hệ thống sản phẩm M12 bao gồm hơn 80 dụng cụ</li>\n</ul>\n', '1_20230704034103.webp', 'resize_1_20230704034103.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 1, NULL),
(238, 1, 102, NULL, 0, 0, 'may-siet-bu-long-goc-m12-fir38-0-2557', 'Máy siết bu lông góc M12 FIR38-0 (2557)', '', '', NULL, 4680000, 3900000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm:</strong>&nbsp;M12 FIR38-0</p>\n\n<p><strong>H&atilde;ng sản xuất:</strong>&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại:</strong>&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>C&oacute; hiệu suất như m&aacute;y siết bu l&ocirc;ng g&oacute;c d&ugrave;ng điện kh&iacute; n&eacute;n với lực siết tối đa l&ecirc;n tới 75 Nm</li>\n	<li>Thiết kế phần đầu nhỏ gọn cho ph&eacute;p người d&ugrave;ng tiếp cận dễ d&agrave;ng hơn trong những kh&ocirc;ng gian chật hẹp</li>\n	<li>Mang lại tốc độ quay 200 v&ograve;ng/ph&uacute;t gi&uacute;p n&acirc;ng cao hiệu suất</li>\n	<li>Với c&ocirc;ng nghệ FUEL độc quyền, m&aacute;y M12 FIR38 được bọc vỏ kẹp bằng th&eacute;p đ&uacute;c gi&uacute;p m&aacute;y c&oacute; thể chống chịu được t&igrave;nh trạng ăn m&ograve;n v&agrave; rơi vỡ trong c&ocirc;ng việc h&agrave;ng ng&agrave;y tại c&ocirc;ng trường, gi&uacute;p tăng tuổi thọ của m&aacute;y</li>\n	<li>M&aacute;y siết bu l&ocirc;ng g&oacute;c kh&ocirc;ng chổi than đầu ti&ecirc;n tr&ecirc;n thị trường, m&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; c&oacute; tuổi thọ d&agrave;i hơn gấp 2 lần</li>\n	<li>Hệ thống bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; bảo vệ m&aacute;y v&agrave; pin khỏi hỏng h&oacute;c do qu&aacute; tải hoặc qu&aacute; nhiệt</li>\n	<li>Pin REDLITHIUM&trade;-ION c&oacute; khả năng l&agrave;m việc l&acirc;u hơn hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của pin</li>\n	<li>C&ocirc;ng tắc t&ugrave;y biến tốc độ bằng kim loại gi&uacute;p kiểm so&aacute;t c&ocirc;ng cụ tối ưu</li>\n	<li>Đ&egrave;n LED chiếu s&aacute;ng khu vực l&agrave;m việc &amp; đồng hồ đo nhi&ecirc;n liệu hiển thị thời gian vận h&agrave;nh c&ograve;n lại</li>\n	<li>Giải ph&aacute;p nhỏ gọn v&agrave; thuận tiện với chiều d&agrave;i 30 cm v&agrave; trọng lượng 1,3 kg khi lắp pin (pin kh&ocirc;ng đi k&egrave;m)</li>\n	<li>Một phần của Hệ thống sản phẩm M12 bao gồm hơn 80 dụng cụ</li>\n</ul>\n', '1_20230704034301.webp', 'resize_1_20230704034301.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 1, NULL),
(239, 1, 102, NULL, 0, 0, 'may-siet-bu-long-goc-m12-fraiwf12-0b-2565', 'Máy siết bu lông góc M12 FRAIWF12-0B (2565)', '', '', NULL, 5040000, 4680000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 FRAIWF12-0B</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Động cơ kh&ocirc;ng chổi than POWERSTATE&trade; tạo ra m&ocirc;-men xoắn cực đại l&ecirc;n đến 300Nm, sản phẩm l&agrave; m&aacute;y siết bu l&ocirc;ng g&oacute;c kh&ocirc;ng d&acirc;y mạnh mẽ nhất tr&ecirc;n thị trường</li>\n	<li>Thiết kế tiết diện đầu 71mm cho ph&eacute;p tiếp cận nhiều hơn trong kh&ocirc;ng gian chật hẹp</li>\n	<li>Chế độ tự dừng gi&uacute;p ngăn siết qu&aacute; mức v&agrave; tăng năng suất bằng c&aacute;ch &aacute;p dụng m&ocirc;-men xoắn kh&ocirc;ng qu&aacute; 20Nm</li>\n	<li>Chế độ th&aacute;o bu l&ocirc;ng cho khả năng kiểm so&aacute;t nhiều hơn v&igrave; tốc độ giảm đi đ&aacute;ng kể khi bu l&ocirc;ng được nới lỏng</li>\n	<li>Chiều d&agrave;i th&acirc;n 361mm cho ph&eacute;p tiếp cận những kh&ocirc;ng gian chật hẹp hơn</li>\n	<li>Hệ thống quản l&yacute; bo mạch th&ocirc;ng minh điện tử REDLINK PLUS&trade; đảm bảo hiệu suất tối đa v&agrave; bảo vệ khỏi qu&aacute; tải, qu&aacute; nhiệt v&agrave; xả hết pin</li>\n	<li>Đ&egrave;n LED chiếu s&aacute;ng khu vực l&agrave;m việc</li>\n	<li>Vỏ cao su non cao cấp chịu được ăn m&ograve;n v&agrave; tăng sự thoải m&aacute;i khi sử dụng</li>\n	<li>Hoạt động trong m&ocirc;i trường l&ecirc;n đến 69kV</li>\n	<li>Tương th&iacute;ch với tất cả c&aacute;c loại pin v&agrave; bộ sạc M12&trade;</li>\n</ul>\n', '1_20230704034421.webp', 'resize_1_20230704034421.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 1, NULL),
(240, 1, 102, NULL, 0, 0, 'may-siet-bu-long-m12-fiwf12-0c-2555', 'Máy siết bu lông M12 FIWF12-0C (2555)', '', '', NULL, 4800000, 4460000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm:</strong>&nbsp;M12 FIWF12-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Nhỏ gọn nhất. Tiếp cận dễ d&agrave;ng nhất trong những kh&ocirc;ng gian chật hẹp nhờ chiều d&agrave;i 124,5 mm</li>\n	<li>Cung cấp lực th&aacute;o mở ốc l&ecirc;n đến 339 Nm</li>\n	<li>Điều khiển lực siết 4 chế độ</li>\n	<li>Chế độ tự động ngắt gi&uacute;p giảm t&igrave;nh trạng vặn qu&aacute; mức v&agrave; tăng năng suất</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; mạnh mẽ hơn, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn v&agrave; tuổi thọ d&agrave;i hơn</li>\n	<li>Hệ thống bo mạch điện tử REDLINK PLUS&trade; đảm bảo tương th&iacute;ch giữa pin v&agrave; m&aacute;y, đảm bảo hiệu suất, sự bảo vệ v&agrave; hiệu năng tối ưu</li>\n	<li>Pin REDLITHIUM&trade;-ION c&oacute; thể l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của pin</li>\n</ul>\n', '1_20230704034637.webp', 'resize_1_20230704034637.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-05', '2023-07-05', '', NULL, NULL, NULL),
(241, 1, 102, NULL, 0, 0, 'may-van-vit-m12-fid-0c-2553', 'Máy vặn vít M12 FID-0C (2553)', '', '', NULL, 3840000, 3360000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 FID-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; cung cấp lực siết 147 Nm mang lại tốc độ vặn nhanh hơn</li>\n	<li>Hệ thống bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; bảo vệ m&aacute;y v&agrave; pin khỏi qu&aacute; tải hoặc qu&aacute; nhiệt</li>\n	<li>Pin REDLITHIUM&trade;-ION gi&uacute;p tăng thời gian l&agrave;m việc sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của pin</li>\n	<li>4 chế độ điều khiển mang lại nhiều khả năng kiểm so&aacute;t tốc độ v&agrave; c&ocirc;ng suất đầu ra hơn</li>\n</ul>\n', '1_20230704034744.webp', 'resize_1_20230704034744.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 1, NULL),
(242, 1, 102, NULL, 0, 0, 'may-van-vit-thuy-luc-m12-fqid-0c-2551', 'Máy vặn vít thủy lực M12 FQID-0C (2551)', '', '', NULL, 5760000, 5350000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 FQID-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&aacute;y vặn v&iacute;t thủy lực M12 FUEL&trade; l&agrave; m&aacute;y vặn v&iacute;t 12V chống ồn tốt nhất của Milwaukee&trade;, mang lại &acirc;m thanh &ecirc;m &aacute;i với độ ồn chỉ 76 dB(A) khi d&ugrave;ng vặn siết tr&ecirc;n gỗ</li>\n	<li>Hệ thống truyền động thủy lực FLUID-DRIVE&trade; l&agrave;m giảm sự tiếp x&uacute;c giữa kim loại với kim loại trong c&ocirc;ng cụ, gi&uacute;p vận h&agrave;nh &ecirc;m &aacute;i hơn, hoạt động trơn tru hơn v&agrave; tăng độ bền so với m&aacute;y vặn v&iacute;t ti&ecirc;u chuẩn</li>\n	<li>Milwaukee&trade; DRIVE CONTROL&trade; cho ph&eacute;p người d&ugrave;ng chuyển sang 4 c&agrave;i đặt tốc độ v&agrave; lực siết kh&aacute;c nhau để tăng tối đa sự linh hoạt</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; cho tốc độ quay l&ecirc;n tới 0 - 3.200 v&ograve;ng/ph&uacute;t với c&ocirc;ng suất nguồn kh&ocirc;ng đổi để vặn v&iacute;t nhanh hơn</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade; mang đến khả năng chống qu&aacute; tải kỹ thuật số ti&ecirc;n tiến nhất cho c&ocirc;ng cụ v&agrave; pin, đồng thời n&acirc;ng cao hiệu suất của c&ocirc;ng cụ khi l&agrave;m việc</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION được đ&oacute;ng g&oacute;i chắc chắn, c&oacute; linh kiện điện tử v&agrave; hiệu suất bền bỉ gi&uacute;p k&eacute;o d&agrave;i thời gian vận h&agrave;nh v&agrave; l&agrave;m được nhiều việc hơn trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>Trụ g&aacute; lục gi&aacute;c 1/4&Prime; gi&uacute;p thay đầu mũi khoan nhanh ch&oacute;ng v&agrave; dễ d&agrave;ng</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả c&aacute;c pin Milwaukee&trade; M12&trade;</li>\n</ul>\n', '1_20230704034857.webp', 'resize_1_20230704034857.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 1, NULL),
(243, 1, 102, NULL, 0, 0, 'may-khoan-bua-m12-ch-0c-2416', 'Máy khoan búa M12 CH-0C (2416)', '', '', NULL, 5760000, 5450000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 CH-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan b&uacute;a v&agrave; đục M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade;: Cung cấp hiệu suất tối ưu v&agrave; chống qu&aacute; tải bằng việc kết nối, kiểm so&aacute;t to&agrave;n bộ hệ thống hoạt động giữa m&aacute;y, pin v&agrave; sạc</li>\n	<li>Pin REDLITHIUM&trade;-ION: Kết cấu chắc chắn, hiệu quả l&agrave;m việc cao hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin.</li>\n	<li>Khả năng khoan b&ecirc; t&ocirc;ng tối đa l&ecirc;n tới 13 mm</li>\n	<li>M&ocirc; tơ 12 volt mạnh mẽ: Mang lại hiệu suất vượt trội nhờ c&oacute; tốc độ quay 0-900 v&ograve;ng/ph&uacute;t 0-6.575 v&ograve;ng/ph&uacute;t</li>\n	<li>Thiết kế gọn nhẹ: Cho ph&eacute;p bạn l&agrave;m việc thoải m&aacute;i trong những kh&ocirc;ng gian chật hẹp hay hoạt động cả ng&agrave;y</li>\n	<li>2 chế độ hoạt động: Chọn khoan động lực c&oacute; b&uacute;a hoặc khoan thường để c&oacute; được độ linh hoạt tối đa</li>\n	<li>Đ&egrave;n LED: Chiếu s&aacute;ng bề mặt l&agrave;m việc</li>\n</ul>\n', '1_20230704035451.webp', 'resize_1_20230704035451.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 2, NULL),
(244, 1, 102, NULL, 0, 0, 'dung-cu-xoay-da-nang-c12-rt-0-2460', 'Dụng cụ xoay đa năng C12 RT-0 (2460)', '', '', NULL, 2760000, 2570000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;C12 RT-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ 12 volt mạnh mẽ: C&oacute; tốc độ quay 5.000-32.000 v&ograve;ng/ph&uacute;t mang lại tốc độ v&agrave; hiệu suất vượt trội khi thực hiện c&ocirc;ng việc</li>\n	<li>Thiết kế độc đ&aacute;o của MILWAUKEE&trade;: Cổng xả theo kiểu m&aacute;y m&agrave;i v&agrave; bộ bảo vệ ổ trục trước</li>\n	<li>Điều chỉnh tốc độ t&ugrave;y &yacute;: Cung cấp chức năng điều tiết dầu</li>\n	<li>Trục g&aacute;: Ph&ugrave; hợp với tất cả c&aacute;c đầu gắn 0,8 mm - 3,2 mm cho h&agrave;ng ngh&igrave;n ứng dụng</li>\n	<li>Thiết kế gọn nhẹ: Cho ph&eacute;p bạn l&agrave;m việc thoải m&aacute;i trong những kh&ocirc;ng gian chật hẹp v&agrave; cả ng&agrave;y</li>\n</ul>\n', '1_20230704035620.webp', 'resize_1_20230704035620.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 3, NULL),
(245, 1, 102, NULL, 0, 0, 'may-cat-da-nang-c12-mt-0b-2426', 'Máy cắt đa năng C12 MT-0B (2426)', '', '', NULL, 3000000, 2790000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;C12 MT-0B</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ mạnh mẽ: C&oacute; tốc độ kh&ocirc;ng tải 5.000 đến 20.000 v&ograve;ng/ph&uacute;t</li>\n	<li>C&ocirc;ng nghệ pin REDLITHIUM&trade;-ION: Kết cấu chắc chắn, bo mạch điện tử v&agrave; hiệu suất vượt trội gi&uacute;p l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>Điều chỉnh tốc độ t&ugrave;y &yacute;: 12 chế độ c&agrave;i đặt cho ph&eacute;p người d&ugrave;ng điều chỉnh tốc độ ph&ugrave; hợp với ứng dụng</li>\n	<li>Đồng hồ đo nhi&ecirc;n liệu t&iacute;ch hợp: Hiển thị thời gian vận h&agrave;nh c&ograve;n lại</li>\n</ul>\n', '1_20230704035725.webp', 'resize_1_20230704035725.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 3, NULL),
(246, 1, 102, NULL, 0, 0, 'may-cat-m12-fcot-0x-2522', 'Máy cắt M12 FCOT-0X (2522)', '', '', NULL, 4800000, 4460000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 FCOT-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Cắt nhanh v&agrave; ch&iacute;nh x&aacute;c với tốc độ quay l&ecirc;n tới 20.000 v&ograve;ng/ph&uacute;t</li>\n	<li>Thiết kế tiện dụng được tối ưu h&oacute;a để kiểm so&aacute;t tốt nhất v&agrave; sử dụng bằng một tay. Chỉ nặng 1,1 kg v&agrave; d&agrave;i 226 mm</li>\n	<li>Khả năng cắt nhiều vật liệu nhờ c&oacute; nhiều loại lưỡi dao (b&aacute;nh cắt kim loại, lưỡi m&agrave;i cacbua v&agrave; lưỡi kim cương)</li>\n	<li>Một c&ocirc;ng cụ c&oacute; thể giải quyết c&aacute;c vấn đề như cắt th&eacute;p, th&eacute;p kh&ocirc;ng gỉ, vật liệu kh&ocirc;ng chứa sắt, v&aacute;ch thạch cao, xi măng sợi, nhựa v&agrave; gốm sứ</li>\n	<li>V&agrave;nh chắn bảo vệ đĩa cắt dễ điều chỉnh v&agrave; hướng xoay lưỡi c&oacute; thể lựa chọn tiến/l&ugrave;i duy nhất để bảo vệ người d&ugrave;ng khỏi c&aacute;c mảnh vụn ở c&aacute;c vị tr&iacute; cắt kh&aacute;c nhau</li>\n	<li>Đế chứa bụi th&aacute;o nhanh với khả năng điều chỉnh độ s&acirc;u v&agrave; cổng h&uacute;t bụi t&ugrave;y chọn</li>\n	<li>MILWAUKEE&trade; được thiết kế v&agrave; t&iacute;ch hợp m&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; mang lại c&ocirc;ng suất mạnh mẽ hơn ở k&iacute;ch thước nhỏ gọn hơn</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade; mang đến khả năng chống qu&aacute; tải kỹ thuật số ti&ecirc;n tiến cho c&ocirc;ng cụ v&agrave; pin, đồng thời n&acirc;ng cao hiệu suất của c&ocirc;ng cụ khi thực hiện c&ocirc;ng việc</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION được đ&oacute;ng g&oacute;i chắc chắn, c&oacute; linh kiện điện tử v&agrave; hiệu suất bền bỉ gi&uacute;p k&eacute;o d&agrave;i thời gian vận h&agrave;nh v&agrave; l&agrave;m được nhiều việc hơn trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>T&iacute;nh năng theo d&otilde;i từng pin gi&uacute;p tối ưu h&oacute;a thời gian h&agrave;nh c&ocirc;ng cụ v&agrave; đảm bảo độ bền bộ pin l&acirc;u d&agrave;i</li>\n	<li>Lưỡi dao 76 mm mang lại độ s&acirc;u cắt 16,3 mm</li>\n	<li>Đồng hồ đo nhi&ecirc;n liệu hiển thị mức sạc c&ograve;n lại</li>\n	<li>Đ&egrave;n LED s&aacute;ng gi&uacute;p rọi s&aacute;ng kh&ocirc;ng gian l&agrave;m việc</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả c&aacute;c pin MILWAUKEE&trade; M12&trade;</li>\n</ul>\n', '1_20230704035847.webp', 'resize_1_20230704035847.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 3, NULL),
(247, 1, 102, NULL, 0, 0, 'may-cat-rung-m12-fmt-0x-2526', 'Máy cắt rung M12 FMT-0X (2526)', '', '', NULL, 5040000, 4800000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 FMT-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; mang lại tốc độ cắt nhanh đối với c&aacute;c vật liệu th&ocirc;ng thường m&agrave; kh&ocirc;ng l&agrave;m chậm hoặc kẹt trong c&aacute;c loại gỗ cứng</li>\n	<li>C&oacute; thể điều chỉnh 10.000 đến 20.000 opm cho ph&eacute;p người d&ugrave;ng c&oacute; được đường cắt ho&agrave;n hảo bất kể vật liệu</li>\n	<li>Giảm rung, tăng năng suất th&ocirc;ng qua hiệu suất v&agrave; an to&agrave;n</li>\n	<li>G&oacute;c dao động tr&aacute;i/phải 1,95&deg; cho ph&eacute;p cắt nhanh hơn</li>\n	<li>Hệ thống quản l&yacute; bo mạch th&ocirc;ng minh điện tử REDLINK PLUS&trade; mang đến khả năng chống qu&aacute; tải kỹ thuật số ti&ecirc;n tiến cho c&ocirc;ng cụ v&agrave; pin, đồng thời n&acirc;ng cao hiệu suất của c&ocirc;ng cụ khi thực hiện c&ocirc;ng việc</li>\n	<li>Thay lưỡi dao kh&ocirc;ng cần c&ocirc;ng cụ hỗ trợ nhờ thiết kế thay lưỡi dao phổ biến, đầu nối đi k&egrave;m để ph&ugrave; hợp với tất cả c&aacute;c loại lưỡi của đối thủ cạnh tranh ch&iacute;nh</li>\n	<li>Đ&egrave;n l&agrave;m việc LED chiếu s&aacute;ng đường cắt trong điều kiện &aacute;nh s&aacute;ng yếu</li>\n	<li>Được cung cấp với đầu nối, lưỡi cắt ch&igrave;m, g&aacute; đ&aacute;nh b&oacute;ng v&agrave; 5 g&aacute; đ&aacute;nh b&oacute;ng để sử dụng khi đ&aacute;nh b&oacute;ng</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION được đ&oacute;ng g&oacute;i chắc chắn, c&oacute; linh kiện điện tử v&agrave; hiệu suất bền bỉ gi&uacute;p k&eacute;o d&agrave;i thời gian vận h&agrave;nh v&agrave; l&agrave;m được nhiều việc hơn trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>Hoạt động với tất cả pin MILWAUKEE&reg; M12&trade;</li>\n</ul>\n', '1_20230704040005.webp', 'resize_1_20230704040005.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 3, NULL),
(248, 1, 102, NULL, 0, 0, 'may-cua-kiem-m12-chz-0-2420', 'Máy cưa kiếm M12 CHZ-0 (2420)', '', '', NULL, 3960000, 3680000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 CHZ-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Thiết kế cầm bằng một tay</li>\n	<li>Mang lại khả năng kiểm so&aacute;t v&agrave; độ linh hoạt vượt trội so với cưa kiếm th&ocirc;ng thường</li>\n	<li>K&iacute;ch thước nhỏ gọn</li>\n	<li>Cho ph&eacute;p cắt trong những kh&ocirc;ng gian chật hẹp v&agrave; trọng lượng nhẹ gi&uacute;p thực hiện c&aacute;c c&ocirc;ng việc tr&ecirc;n cao dễ d&agrave;ng hơn</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;</li>\n	<li>Cung cấp c&ocirc;ng suất ổn định gi&uacute;p cắt nhanh hơn v&agrave; giảm nhiệt lượng trong thời gian d&agrave;i sử dụng</li>\n	<li>Bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade;</li>\n	<li>Cung cấp hiệu suất tối ưu v&agrave; chống qu&aacute; tải bằng việc kết nối, kiểm so&aacute;t to&agrave;n bộ hệ thống hoạt động giữa m&aacute;y, pin v&agrave; sạc</li>\n	<li>Pin REDLITHIUM&trade;-ION</li>\n	<li>Kết cấu chắc chắn, hiệu quả l&agrave;m việc cao hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin.</li>\n</ul>\n', '1_20230704040117.webp', 'resize_1_20230704040117.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 3, NULL),
(249, 1, 103, NULL, 0, 0, 'may-cua-soc-m18-fjs-0x-2737', 'Máy cưa sọc M18 FJS-0X (2737)', '', '', NULL, 6960000, 6460000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FJS-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '', '1_20230704040228.webp', 'resize_1_20230704040228.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(250, 1, 102, NULL, 0, 0, 'may-cua-xich-m12-fhs-0x-2527', 'Máy cưa xích M12 FHS-0X (2527)', '', '', NULL, 6000000, 5670000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 FHS-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Động cơ kh&ocirc;ng chổi than POWERSTATE&trade; tạo ra sức mạnh để cắt tr&ecirc;n c&aacute;c vật liệu kh&oacute;</li>\n	<li>Bộ căng x&iacute;ch ra v&agrave;o dễ d&agrave;ng gi&uacute;p điều chỉnh căng x&iacute;ch nhanh ch&oacute;ng</li>\n	<li>Ngăn chứa dầu mờ cho ph&eacute;p hiển thị r&otilde; mức dầu</li>\n	<li>C&ograve; thay đổi tốc độ tăng khả năng kiểm so&aacute;t của người d&ugrave;ng</li>\n	<li>M&aacute;y khi lắp pin c&oacute; trọng lượng nhỏ hơn 2,3kg</li>\n	<li>X&iacute;ch cưa loại ti&ecirc;u chuẩn gi&uacute;p giảm độ rung v&agrave; cho đường cắt mịn</li>\n	<li>Bơm dầu tự động để b&ocirc;i trơn x&iacute;ch hợp l&yacute; v&agrave; tăng năng suất</li>\n	<li>Đinh nghiền kim loại cho ph&eacute;p tăng đ&ograve;n bẩy trong c&aacute;c ứng dụng</li>\n	<li>Khe c&agrave;i ch&igrave;a vặn t&iacute;ch hợp tr&ecirc;n th&acirc;n m&aacute;y gọn g&agrave;ng</li>\n</ul>\n', '1_20230704040337.webp', 'resize_1_20230704040337.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 3, NULL),
(251, 1, 102, NULL, 0, 0, 'may-danh-bong-m12-bps-0-2438', 'Máy đánh bóng M12 BPS-0 (2438)', '', '', NULL, 2640000, 2450000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 BPS-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>C&ocirc;ng tắc t&ugrave;y biến tốc độ</li>\n	<li>G&oacute;i phụ kiện 5 chiếc:</li>\n	<li>(1) miếng đ&aacute;nh b&oacute;ng 3&quot;</li>\n	<li>(1) miếng ch&agrave; nh&aacute;m 2&quot;</li>\n	<li>(1) đệm gỗ</li>\n	<li>(1) miếng đệm m&uacute;t v&agrave;ng</li>\n	<li>(1) miếng đệm m&uacute;t trắng</li>\n	<li>Thay phụ kiện kh&ocirc;ng cần c&ocirc;ng cụ hỗ trợ</li>\n	<li>Tay cầm b&ecirc;n</li>\n</ul>\n', '1_20230704040441.webp', 'resize_1_20230704040441.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 3, NULL),
(252, 1, 103, NULL, 0, 0, 'may-mai-goc-m18-flag230xpdb-0c-2785', 'Máy mài góc M18 FLAG230XPDB-0C (2785)', '', '', NULL, 10200000, 9180000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FLAG230XPDB-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Được chế tạo cho M&aacute;y m&agrave;i g&oacute;c lớn M18 FUEL&trade; để mang lại sức mạnh v&agrave; hiệu suất như một chiếc M&aacute;y m&agrave;i g&oacute;c lớn d&ugrave;ng điện 15A</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION HIGH OUTPUT&trade; HD12.0: Mạnh mẽ hơn 50% v&agrave; vận h&agrave;nh m&aacute;t hơn 50% so với bộ pin REDLITHIUM&trade;-ION HD ti&ecirc;u chuẩn. Sự đ&oacute;ng g&oacute;i chắc chắn mang lại khả năng bảo vệ tốt nhất trong ng&agrave;nh trước những điều kiện l&agrave;m việc tại c&ocirc;ng trường</li>\n	<li>Ho&agrave;n to&agrave;n kh&ocirc;ng cần d&ugrave;ng dụng cụ hỗ trợ: Thay đổi phụ kiện v&agrave; điều chỉnh thanh bảo vệ m&agrave; kh&ocirc;ng cần cờ l&ecirc; gi&uacute;p n&acirc;ng cao hiệu suất</li>\n	<li>Hệ thống truyền động &amp; vỏ kim loại mang lại độ bền trứ danh</li>\n	<li>Tương th&iacute;ch với tất cả c&aacute;c pin M18&trade;</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade;: Đảm bảo hiệu suất tối ưu v&agrave; chống qu&aacute; tải để ngăn ngừa hỏng h&oacute;c c&ocirc;ng cụ cũng như pin trong c&aacute;c ứng dụng nặng trong khi vẫn duy tr&igrave; được khả năng tương th&iacute;ch tr&ecirc;n to&agrave;n hệ thống M18&trade;</li>\n	<li>Hiệu suất như m&aacute;y d&ugrave;ng điện: M&aacute;y m&agrave;i g&oacute;c lớn 18V đầu ti&ecirc;n tr&ecirc;n thế giới</li>\n	<li>Thiết kế tiện dụng, ti&ecirc;n tiến để tăng t&iacute;nh di động v&agrave; năng suất</li>\n	<li>C&ograve; k&iacute;ch hoạt k&eacute;p: gi&uacute;p tr&aacute;nh t&igrave;nh trạng k&iacute;ch hoạt c&ograve; do v&ocirc; t&igrave;nh</li>\n</ul>\n', '1_20230704040542.webp', 'resize_1_20230704040542.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(253, 1, 102, NULL, 0, 0, 'mat-hut-bui-kho-uot-m12-fvcl-0-0960', 'Mát hút bụi khô ướt M12 FVCL-0 (0960)', '', '', NULL, 6600000, 6130000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 FVCL-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M12 FVCL : M&aacute;y h&uacute;t bụi kh&ocirc;ng d&acirc;y 12V hiệu suất cao nhất</li>\n	<li>Hiệu suất đ&aacute;p ứng tất cả c&aacute;c c&ocirc;ng việc dọn dẹp nhanh ch&oacute;ng v&agrave; theo định hướng dịch vụ</li>\n	<li>Hiệu suất tương đương 18V tr&ecirc;n hệ thống M12</li>\n	<li>M&aacute;y h&uacute;t bụi 12V nhỏ gọn nhất</li>\n	<li>Thiết kế nhỏ gọn lưu trữ gọn g&agrave;ng trong xe tải hoặc xe đẩy với thiết kế c&oacute; thể xếp chồng l&ecirc;n nhau</li>\n	<li>Khay sắp xếp b&ecirc;n trong ngăn nắp v&agrave; k&iacute;n</li>\n	<li>T&iacute;nh năng treo cho ph&eacute;p gắn v&agrave;o tường hoặc vật cố định, tiết kiệm kh&ocirc;ng gian kệ v&agrave; dễ tiếp cận hơn</li>\n	<li>&Ecirc;m hơn l&ecirc;n đến 2X so với m&aacute;y h&uacute;t bụi kh&ocirc;/ướt ở c&ocirc;ng trường truyền thống</li>\n	<li>Hoạt động &ecirc;m hơn để sử dụng ở kh&ocirc;ng gian c&oacute; người l&agrave;m việc</li>\n	<li>Độ ồn chỉ 87 dB(A) khi hoạt động b&igrave;nh thường, m&aacute;y h&uacute;t bụi n&agrave;y &ecirc;m hơn đ&aacute;ng kể so với c&aacute;c đối thủ cạnh tranh kh&aacute;c trong c&ugrave;ng chủng loại</li>\n</ul>\n', '1_20230704040703.webp', 'resize_1_20230704040703.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 9, NULL);
INSERT INTO `toandanh_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `nid_weight`, `ctype`, `ccode`, `cproducts`, `eng_cproducts`, `ctag`, `nview`, `fprice`, `fprice_sale`, `nquantity`, `cdescription`, `eng_cdescription`, `cmodel`, `cpower`, `eng_cdetail`, `cdetail`, `cimage`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nnew`, `nkm`, `npb`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `clink`, `cproduct_fb`, `nid_sub_menu`, `clink_shoppe`) VALUES
(254, 1, 102, NULL, 0, 0, 'may-ban-dinh-rut-m12-bprt-0c-2550', 'Máy bắn đinh rút M12 BPRT-0C (2550)', '', '', NULL, 6000000, 5570000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 BPRT-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>R&uacute;t được tới 250 đinh t&aacute;n th&eacute;p kh&ocirc;ng gỉ 4,8 mm trong mỗi lần sạc (pin 1,5 Ah)</li>\n	<li>R&uacute;t được tới 450 đinh t&aacute;n th&eacute;p kh&ocirc;ng gỉ 3,2 mm trong mỗi lần sạc (pin 1,5 Ah)</li>\n	<li>Một trong số hơn 90 giải ph&aacute;p trong hệ thống sản phẩm M12&trade;</li>\n	<li>R&uacute;t c&aacute;c đinh t&aacute;n k&iacute;ch thước 2,4 / 3,2 / 4,0 / 4,8 mm</li>\n	<li>Khả năng r&uacute;t c&aacute;c loại đinh: Nh&ocirc;m, th&eacute;p, th&eacute;p kh&ocirc;ng gỉ</li>\n	<li>Độ sọc 20,32 mm</li>\n	<li>Lực r&uacute;t 9000 N</li>\n	<li>C&ocirc;ng cụ giữ đinh t&aacute;n theo mọi hướng</li>\n	<li>Thiết kế tiện dụng gi&uacute;p giảm sức lực</li>\n</ul>\n', '1_20230704040814.webp', 'resize_1_20230704040814.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 9, NULL),
(255, 1, 102, NULL, 0, 0, 'may-bom-hoi-m12-bi-0-2475', 'Máy bơm hơi M12 BI-0 (2475)', '', '', NULL, 3000000, 2790000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 BI-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&aacute;y bơm hơi d&ugrave;ng pin nhanh nhất: Bơm căng lốp &ocirc; t&ocirc; chỉ chưa đầy 1 ph&uacute;t. (28 - 35 PSI)</li>\n	<li>Bơm lốp xe hơi, xe tải LT v&agrave; lốp của c&aacute;c thiết bị nhỏ gọn</li>\n	<li>Bo mạch điện tử th&ocirc;ng minh REDLINK&trade;: C&ocirc;ng nghệ tự động ngắt TrueFill&trade; tăng độ ch&iacute;nh x&aacute;c, bảo vệ khỏi nhiệt độ qu&aacute; cao v&agrave; lốp qu&aacute; căng</li>\n	<li>Bơm v&agrave; m&ocirc; tơ hiệu suất cao mang lại khả năng bơm với &aacute;p suất l&ecirc;n tới120 PSI</li>\n	<li>Đồng hồ đo kỹ thuật số c&oacute; đ&egrave;n chiếu s&aacute;ng với chỉ số &aacute;p suất mục ti&ecirc;u v&agrave; hiện tại</li>\n	<li>Bơm căng lốp xe tải LT chỉ trong chưa đầy 4 ph&uacute;t (30-45 psi)</li>\n	<li>Nhỏ gọn, di động v&agrave; dễ d&agrave;ng cất giữ trong bất kỳ chiếc xe hơi hoặc xe tải n&agrave;o</li>\n	<li>Chống chịu thời tiết v&agrave; va đập với lồng được gia cố</li>\n	<li>Ch&acirc;n chống rung gi&uacute;p c&ocirc;ng cụ kh&ocirc;ng di chuyển trong khi vận h&agrave;nh</li>\n</ul>\n', '1_20230704041138.webp', 'resize_1_20230704041138.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 9, NULL),
(256, 1, 102, NULL, 0, 0, 'may-bom-keo-m12-pcg-310c-0-2441', 'Máy bơm keo M12 PCG/310C-0 (2441)', '', '', NULL, 4200000, 3910000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 PCG/310C-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>C&ocirc;ng nghệ d&ograve;ng chảy li&ecirc;n tục - C&aacute;c hạt đồng đều dẫn đến th&aacute;o lắp nhanh hơn, sạch hơn</li>\n	<li>C&ocirc;ng tắc t&ugrave;y biến tốc độ v&agrave; điều chỉnh tốc độ - Ho&agrave;n th&agrave;nh qu&aacute; tr&igrave;nh kiểm so&aacute;t tỷ lệ bơm</li>\n	<li>Gọn nhẹ</li>\n	<li>T&iacute;nh năng Chống nhỏ giọt &euro;&ldquo; tự động đảo ngược p&iacute;t-t&ocirc;ng l&agrave;m giảm &aacute;p suất từ ống</li>\n	<li>Lực đẩy 1780 N &euro;&ldquo; dễ d&agrave;ng sử dụng với bất kỳ loại keo/h&oacute;a chất x&acirc;y dựng n&agrave;o</li>\n</ul>\n', '1_20230704041308.webp', 'resize_1_20230704041308.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 9, NULL),
(257, 1, 102, NULL, 0, 0, 'may-han-nhiet-milwaukee-m12-si-0-2488', 'Máy hàn nhiệt MILWAUKEE M12 SI-0 (2488)', '', '', NULL, 2400000, 2240000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 SI-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Thời gian l&agrave;m n&oacute;ng nhanh: sẵn s&agrave;ng trong chưa đầy 30 gi&acirc;y</li>\n	<li>3 vị tr&iacute; đầu kh&oacute;a để l&agrave;m việc theo nhiều g&oacute;c độ - 0&deg;, 45&deg;, 90&deg;</li>\n	<li>Thay mũi h&agrave;n kh&ocirc;ng cần c&ocirc;ng cụ hỗ trợ</li>\n	<li>Đ&egrave;n LED b&aacute;o hiệu 2 m&agrave;u: nhấp nh&aacute;y m&agrave;u xanh lục khi m&aacute;y đang l&agrave;m n&oacute;ng, thuần m&agrave;u xanh lục khi m&aacute;y sẵn s&agrave;ng hoạt động v&agrave; thuần m&agrave;u đỏ khi m&aacute;y đ&atilde; tắt nhưng mũi khoan vẫn c&ograve;n n&oacute;ng cho đến khi đ&egrave;n LED tắt đi</li>\n	<li>Theo d&otilde;i nhiệt độ để duy tr&igrave; độ n&oacute;ng trong suốt c&aacute;c ứng dụng cường độ cao</li>\n	<li>Đ&egrave;n LED s&aacute;ng để tăng độ r&otilde; n&eacute;t khi ứng dụng trong thao t&aacute;c h&agrave;n</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả c&aacute;c pin MILWAUKEE&trade; M12&trade;</li>\n</ul>\n', '1_20230704041526.webp', 'resize_1_20230704041526.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 9, NULL),
(258, 1, 102, NULL, 0, 0, 'may-thong-tac-hoi-m12-dcag-0c-2572', 'Máy thông tắc hơi M12 DCAG-0C (2572)', '', '', NULL, 10200000, 9920000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 DCAG-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Th&ocirc;ng c&aacute;c nắp che ống tho&aacute;t &amp; ống chữ U bằng kh&iacute; mạnh</li>\n	<li>Tiếp cận c&aacute;c chỗ tắc c&aacute;ch 10,6 m ngay lập tức</li>\n	<li>Loại bỏ mỡ &amp; b&ugrave;n khỏi th&agrave;nh ống</li>\n	<li>&Aacute;p suất l&ecirc;n tới 50 PSI để tiếp cận c&aacute;c chỗ tắc ở cuối đường ống</li>\n	<li>C&oacute; khả năng loại bỏ c&aacute;c chỗ tắc qua c&aacute;c lỗ th&ocirc;ng hơi</li>\n	<li>Điều chỉnh &aacute;p suất t&ugrave;y &yacute; để chọn PSI ph&ugrave; hợp cho phụ t&ugrave;ng ống c&oacute; &aacute;p v&agrave; đường ống tho&aacute;t cũ hơn</li>\n	<li>C&aacute;c phụ kiện được tối ưu h&oacute;a cho bồn rửa, nh&agrave; vệ sinh, ống tho&aacute;t s&agrave;n</li>\n	<li>Hơn 25 chu kỳ &aacute;p suất chỉ trong một lần sạc</li>\n	<li>Phụ kiện c&oacute; thể thay thế được tối ưu h&oacute;a cho c&aacute;c nắp bịt tr&ecirc;n ống 25 - 100 mm, n&uacute;t xả nước vĩnh viễn v&agrave; nh&agrave; vệ sinh</li>\n	<li>Đầu nối lệch 15 độ để tiếp cận ống tho&aacute;t ph&iacute;a dưới v&ograve;i cố định</li>\n</ul>\n', '1_20230704041636.webp', 'resize_1_20230704041636.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 9, NULL),
(259, 1, 102, NULL, 0, 0, 'may-tra-mo-m12-gg-0-2446', 'Máy tra mỡ M12 GG-0 (2446)', '', '', NULL, 4560000, 4230000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12 GG-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M12</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ 12V mạnh mẽ: Mang lại &aacute;p suất vận h&agrave;nh tr&ecirc;n 562 bar</li>\n	<li>C&ocirc;ng nghệ pin REDLITHIUM&trade;-ION: c&aacute;c linh kiện điện tử li&ecirc;n kết chặt chẽ v&agrave; hiệu suất vượt trội gi&uacute;p l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>Thời gian vận h&agrave;nh tốt nhất: Sử dụng tới 7 hộp mỡ trong mỗi lần sạc</li>\n	<li>Hộp đựng ống t&iacute;ch hợp: Tăng th&ecirc;m sự thuận tiện</li>\n	<li>Van xả kh&iacute;: Cơ chế mồi cho d&ograve;ng chảy nhanh</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả c&aacute;c pin MILWAUKEE&trade; M12&trade;</li>\n</ul>\n', '1_20230704041734.webp', 'resize_1_20230704041734.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 9, NULL),
(260, 1, 102, NULL, 0, 0, 'luoi-cat-da-nang-4932464716-dung-cho-may-m12-fcot', 'Lưỡi cắt đa năng 4932464716 (dùng cho máy M12 FCOT)', '', '', NULL, 360000, 300000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;4932464716</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Đĩa cắt</p>\n', '', NULL, NULL, '', '', '1_20230704042205.webp', 'resize_1_20230704042205.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 4, NULL),
(261, 1, 102, NULL, 0, 0, 'luoi-cat-kim-loai-4932464717-dung-cho-may-m12-fcot', 'Lưỡi cắt kim loại 4932464717 (dùng cho máy M12 FCOT)', '', '', NULL, 360000, 300000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;4932464717</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Đĩa cắt</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Th&iacute;ch hợp cho th&eacute;p chịu axit, th&eacute;p cứng, th&eacute;p hợp kim cao, th&eacute;p nhẹ v&agrave; th&eacute;p c&ocirc;ng cụ. Kh&ocirc;ng ph&ugrave; hợp với th&eacute;p kh&ocirc;ng gỉ</li>\n	<li>Để sử dụng với dụng cụ cắt Milwaukee M12 FUEL &trade; (M12 FCOT) v&agrave; c&aacute;c c&ocirc;ng cụ cắt kh&aacute;c với trục quay 3/8 inch</li>\n	<li>Bao gồm 5 đĩa cắt kim loại</li>\n	<li>Tối đa 20.100 v&ograve;ng/ph&uacute;t</li>\n</ul>\n', '1_20230704042328.webp', 'resize_1_20230704042328.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 4, NULL),
(262, 1, 102, NULL, 0, 0, 'pin-12v-2-0ah-48-11-2420', 'Pin 12V 2.0Ah (48-11-2420)', '', '', NULL, 660000, 640000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12B2</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Pin M12</p>\n', '', NULL, NULL, '', '', '1_20230704042436.webp', 'resize_1_20230704042436.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 4, NULL),
(263, 1, 102, NULL, 0, 0, 'pin-12v-4-0ah-48-11-2440', 'Pin 12V 4.0Ah (48-11-2440)', '', '', NULL, 1188000, 1050000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M12B4</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Pin M12</p>\n', '', NULL, NULL, '', '', '1_20230704042544.webp', 'resize_1_20230704042544.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 4, NULL),
