(273, 1, 103, NULL, 0, 0, 'luoi-cat-kim-loai-34t-149mm-48-40-4080', 'Lưỡi cắt kim loại 34T 149mm (48-40-4080)', '', '', NULL, 1320000, 1290000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;48-40-4080</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Đĩa cắt</p>\n', '', NULL, NULL, '', '', '1_20230704044501.jpg.webp', 'resize_1_20230704044501.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 8, NULL),
(274, 1, 103, NULL, 0, 0, 'luoi-cat-kim-loai-50t-137mm-48-40-4075', 'Lưỡi cắt kim loại 50T 137mm (48-40-4075)', '', '', NULL, 1320000, 1290000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;48-40-4075</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Đĩa cắt</p>\n', '', NULL, NULL, '', '', '1_20230704044606.webp', 'resize_1_20230704044606.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 8, NULL),
(275, 1, 103, NULL, 0, 0, 'may-ban-dinh-m18-fn18gs-0x0-2746', 'Máy bắn đinh M18 FN18GS-0X0 (2746)', '', '', NULL, 12600000, 12250000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FN18GS-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Mạnh mẽ nhất trong ph&acirc;n kh&uacute;c, cho ph&eacute;p bắn đinh li&ecirc;n tục v&agrave;o bề mặt gỗ cứng</li>\n	<li>C&ocirc;ng nghệ bắn đinh ti&ecirc;n tiến loại bỏ hiện tượng kẹt đinh v&agrave; thời gian l&atilde;ng ph&iacute; khi gỡ đinh</li>\n	<li>Kh&ocirc;ng cần b&igrave;nh n&eacute;n kh&iacute; v&agrave; kh&ocirc;ng cần vệ sinh, được thiết kế để đem lại độ bền v&agrave; độ tin cậy cho những người d&ugrave;ng kh&oacute; t&iacute;nh nhất với rất &iacute;t c&ocirc;ng sức bảo dưỡng</li>\n	<li>Lỗ đinh nhỏ hơn, k&iacute;ch cỡ đầu đinh ch&iacute;nh x&aacute;c gi&uacute;p để lại bề mặt ho&agrave;n thiện gọn g&agrave;ng hơn</li>\n	<li>C&aacute;c đầu t&igrave; c&oacute; nhiều h&igrave;nh dạng được t&iacute;ch hợp sẵn tr&ecirc;n th&acirc;n m&aacute;y cho ph&eacute;p người d&ugrave;ng c&oacute; được kết quả tốt nhất cho d&ugrave; sử dụng v&agrave;o việc g&igrave;</li>\n	<li>Mũi bắn đinh nhỏ để bắn đinh v&agrave;o những g&oacute;c nhọn</li>\n	<li>Điều chỉnh độ s&acirc;u dễ d&agrave;ng v&agrave; nhanh ch&oacute;ng, tự do để bắn đinh li&ecirc;n tục</li>\n	<li>T&iacute;nh năng Dry Fire cho ph&eacute;p dừng bắn đinh khi kh&ocirc;ng c&ograve;n đinh n&agrave;o ở băng đinh</li>\n	<li>Bắn tới 1200 đinh một lần sạc chạy bằng bộ pin REDLITHIUM&trade;-ION 2,0 Ah để đạt năng suất tối đa</li>\n	<li>Tiếp cận vị tr&iacute; bắn nhanh v&agrave; dễ d&agrave;ng loại bỏ đinh bị kẹt</li>\n	<li>Đ&egrave;n l&agrave;m việc LED rọi s&aacute;ng bề mặt gỗ để biết được ch&iacute;nh x&aacute;c hơn vị tr&iacute; đinh</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả c&aacute;c pin MILWAUKEE&trade; M18&trade;</li>\n</ul>\n', '1_20230704044741.jpg.webp', 'resize_1_20230704044741.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 10, NULL),
(276, 1, 103, NULL, 0, 0, 'may-bat-vit-m18-fid2-0x-2853', 'Máy bắt vít M18 FID2-0X (2853)', '', '', NULL, 5400000, 4730000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FID2-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; c&oacute; tốc độ vặn nhanh hơn 30% gi&uacute;p n&acirc;ng cao hiệu suất</li>\n	<li>Th&ecirc;m tới 25% lực siết tối đa l&ecirc;n tới 226 Nm để ho&agrave;n th&agrave;nh c&aacute;c ứng dụng đ&ograve;i hỏi khắt khe hơn</li>\n	<li>4 chế độ DRIVE CONTROL&trade; mang lại nhiều khả năng kiểm so&aacute;t tốc độ v&agrave; c&ocirc;ng suất hơn</li>\n	<li>Đầu lục gi&aacute;c th&aacute;o lắp nhanh gi&uacute;p thay đầu mũi v&iacute;t dễ d&agrave;ng hơn</li>\n	<li>Lớp vỏ cao su đ&uacute;c chắc chắn cao cấp chống chịu được c&aacute;c vật liệu ăn m&ograve;n v&agrave; mang lại sự thoải m&aacute;i hơn khi sử dụng</li>\n	<li>Tương th&iacute;ch với tất cả c&aacute;c c&ocirc;ng cụ &amp; pin M18&trade;</li>\n	<li>M&aacute;y vặn v&iacute;t nhỏ gọn nhất với chiều d&agrave;i 4,59&quot; cho ph&eacute;p tiếp cận dễ d&agrave;ng hơn trong những kh&ocirc;ng gian chật hẹp</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION: Gi&uacute;p l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin so với pin của đối thủ cạnh tranh</li>\n	<li>Chế độ v&iacute;t tự khoan gi&uacute;p lắp đặt nhanh hơn nhờ giảm t&igrave;nh trạng trờn ren ốc v&iacute;t</li>\n	<li>Đ&egrave;n LED rọi s&aacute;ng khu vực l&agrave;m việc</li>\n	<li>Đi k&egrave;m M&oacute;c treo thắt lưng v&agrave; Đầu giữ mũi ch&igrave;a vặn</li>\n</ul>\n', '1_20230704044853.webp', 'resize_1_20230704044853.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 5, NULL),
(277, 1, 103, NULL, 0, 0, 'may-cat-be-tong-m18-fcos230-0g0-2786', 'Máy cắt bê tông M18 FCOS230-0G0 (2786)', '', '', NULL, 15600000, 15160000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FCOS230-0G0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;</li>\n	<li>Hệ thống quản l&yacute; bo mạch th&ocirc;ng minh điện tử REDLINK PLUS&trade;</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION HIGH OUTPUT&trade;</li>\n	<li>Đủ mạnh mẽ để cắt b&ecirc; t&ocirc;ng cốt th&eacute;p</li>\n	<li>Nhẹ hơn m&aacute;y kh&iacute; n&eacute;n</li>\n	<li>Loại bỏ rắc rối của m&aacute;y kh&iacute; n&eacute;n</li>\n	<li>T&iacute;nh năng dừng nhanh RAPIDSTOP</li>\n	<li>Đ&egrave;n b&aacute;o hoạt động</li>\n	<li>Bộ phận bảo vệ c&oacute; thể điều chỉnh ho&agrave;n to&agrave;n</li>\n	<li>C&ograve; k&iacute;ch hoạt k&eacute;p: ngăn m&aacute;y khởi động ngẫu nhi&ecirc;n</li>\n	<li>Kết nối nước b&ecirc;n trong: Kết nối nhanh</li>\n	<li>Thiết kế ti&ecirc;n tiến để tăng t&iacute;nh di động v&agrave; năng suất</li>\n	<li>Tương th&iacute;ch với tất cả c&aacute;c loại pin M18&trade;</li>\n</ul>\n', '1_20230704045008.jpg.webp', 'resize_1_20230704045008.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 7, NULL),
(278, 1, 103, NULL, 0, 0, 'may-cat-da-nang-m18-fms254-0-2734', 'Máy cắt đa năng M18 FMS254-0 (2734)', '', '', NULL, 21600000, 20990000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FMS254-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '', '1_20230704045150.webp', 'resize_1_20230704045150.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(279, 1, 103, NULL, 0, 0, 'may-cat-kim-loai-m18-bms20-0-2636', 'Máy cắt kim loại M18 BMS20-0 (2636)', '', '', NULL, 7200000, 6360000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 BMS20-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '', '1_20230704045310.webp', 'resize_1_20230704045310.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(280, 1, 103, NULL, 0, 0, 'may-cat-kim-loai-m18-fmcs-0x-2782', 'Máy cắt kim loại M18 FMCS-0X (2782)', '', '', NULL, 7200000, 6680000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FMCS-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; của MILWAUKEE&trade; mạnh mẽ hơn, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn v&agrave; tuổi thọ d&agrave;i hơn.</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION của MILWAUKEE&trade; l&agrave; bộ pin bền nhất tr&ecirc;n thị trường, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn, mạnh mẽ hơn v&agrave; tuổi thọ pin cao hơn.</li>\n	<li>Hệ thống th&ocirc;ng minh điện tử REDLINK PLUS&trade; hỗ trợ kết nối n&acirc;ng cao giữa pin v&agrave; c&ocirc;ng cụ, mang lại hiệu suất, sự bảo vệ v&agrave; hiệu năng chưa từng c&oacute;.</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than c&oacute; tốc độ quay 3.900 v&ograve;ng/ph&uacute;t gi&uacute;p cắt nhanh hơn m&aacute;y cắt kim loại th&ocirc;ng thường</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than kh&ocirc;ng c&oacute; bộ phận đeo gi&uacute;p k&eacute;o d&agrave;i tuổi thọ tối đa cho c&ocirc;ng cụ</li>\n	<li>Pin M18&trade; REDLITHIUM&trade;-ION để thực hiện tới 370 lần cắt trong 3/4&quot; EMT cho cả ng&agrave;y l&agrave;m việc</li>\n	<li>M&oacute;c treo đi k&egrave;m cho ph&eacute;p treo c&ocirc;ng cụ tr&ecirc;n thang v&agrave; c&aacute;c vật liệu x&acirc;y dựng th&ocirc;ng dụng để giảm hỏng h&oacute;c do rơi</li>\n</ul>\n', '1_20230704045535.png.webp', 'resize_1_20230704045535.png.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 7, NULL),
(281, 1, 103, NULL, 0, 0, 'may-cat-rung-m18-fmt-0x0-2836', 'Máy cắt rung M18 FMT-0X0 (2836)', '', '', NULL, 5760000, 5350000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FMT-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; mang lại tốc độ cắt nhanh đối với c&aacute;c vật liệu th&ocirc;ng thường m&agrave; kh&ocirc;ng l&agrave;m chậm hoặc kẹt trong c&aacute;c loại gỗ cứng</li>\n	<li>C&oacute; thể điều chỉnh 10.000 đến 20.000 opm cho ph&eacute;p người d&ugrave;ng c&oacute; được đường cắt ho&agrave;n hảo bất kể vật liệu</li>\n	<li>Khả năng bảo vệ qu&aacute; tải v&agrave; ổn định tốc độ thiết bị điện tử tốc độ trong c&ocirc;ng cụ của REDLINK&trade; mang lại độ bền v&agrave; hiệu suất tốt nhất</li>\n	<li>G&oacute;c dao động tr&aacute;i/phải 2,1&deg; cho ph&eacute;p cắt nhanh hơn</li>\n	<li>Khả năng cắt nhiều loại vật liệu từ nhẹ (v&aacute;ch thạch cao, gỗ mềm) đến nặng (Gỗ sồi, Gỗ đ&oacute;ng đinh)</li>\n	<li>N&uacute;m quay 10 chế độ c&agrave;i đặt c&oacute; thể thay đổi nhanh cho ph&eacute;p người d&ugrave;ng khớp tốc độ với ứng dụng</li>\n	<li>T&iacute;nh năng tự động tải tự động tăng tốc khi nằm trong vật liệu để gi&uacute;p bắt đầu cắt ch&iacute;nh x&aacute;c hơn</li>\n	<li>Đ&egrave;n LED 180 độ gi&uacute;p nh&igrave;n r&otilde; hơn</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION được đ&oacute;ng g&oacute;i chắc chắn, c&oacute; linh kiện điện tử v&agrave; hiệu suất bền bỉ gi&uacute;p k&eacute;o d&agrave;i thời gian vận h&agrave;nh v&agrave; l&agrave;m được nhiều việc hơn trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>Hoạt động với tất cả pin MILWAUKEE&reg; M18&trade;</li>\n</ul>\n', '1_20230704045658.webp', 'resize_1_20230704045658.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(282, 1, 103, NULL, 0, 0, 'may-cat-thanh-ren-m18-bltrc-0c-2872', 'Máy cắt thanh ren M18 BLTRC-0C (2872)', '', '', NULL, 13200000, 12830000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 BLTRC-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M18</p>\n', '', NULL, NULL, '', '', '1_20230704051438.jpg.webp', 'resize_1_20230704051438.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 7, NULL),
(283, 1, 103, NULL, 0, 0, 'may-cha-nham-m18-bos125-0x0-2684', 'Máy chà nhám M18 BOS125-0X0 (2684)', '', '', NULL, 3840000, 3570000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;Li&ecirc;n hệ đặt h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 BOS125-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Tối đa 24.000 OPM</li>\n	<li>Loại bỏ nhiều vật liệu thừa hơn trong mỗi lần sạc</li>\n	<li>Kiểm so&aacute;t tốc độ t&ugrave;y &yacute;</li>\n	<li>Miếng ch&agrave; nh&aacute;m 125 mm</li>\n	<li>Tốc độ t&ugrave;y biến từ 14.000-24.000 OPM</li>\n	<li>Đường k&iacute;nh quỹ đạo 2,4 mm</li>\n	<li>Bao gồm đầu nối ống đa dụng</li>\n	<li>Hộp chứa bụi c&oacute; bộ lọc</li>\n	<li>Một phần của Hệ thống M18 c&oacute; hơn 150 sản phẩm</li>\n</ul>\n', '1_20230704051548.webp', 'resize_1_20230704051548.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(284, 1, 103, NULL, 0, 0, 'may-cua-dia-m18-ccs66-0-2731', 'Máy cưa đĩa M18 CCS66-0 (2731)', '', '', NULL, 7440000, 6910000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 CCS66-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Tăng tốc độ cắt v&agrave; c&ocirc;ng suất trong c&aacute;c ứng dụng kh&oacute; thực hiện</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade;: Cung cấp hiệu suất tối ưu v&agrave; chống qu&aacute; tải bằng c&aacute;ch sử dụng to&agrave;n bộ kết nối hệ thống giữa c&ocirc;ng cụ, pin v&agrave; sạc</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION: Được đ&oacute;ng g&oacute;i chắc chắn, l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin.</li>\n	<li>Độ s&acirc;u cắt 66 mm ph&ugrave; hợp với nhiều ứng dụng hơn</li>\n	<li>M&oacute;c treo t&iacute;ch hợp để dễ d&agrave;ng cất giữ sau mỗi lần sử dụng</li>\n	<li>Đ&egrave;n LED gi&uacute;p dễ nh&igrave;n r&otilde; đường cắt trong c&aacute;c trường hợp &aacute;nh s&aacute;ng yếu</li>\n</ul>\n', '1_20230704051641.webp', 'resize_1_20230704051641.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(285, 1, 103, NULL, 0, 0, 'may-cua-kiem-m18-fhz-0-2719', 'Máy cưa kiếm M18 FHZ-0 (2719)', '', '', NULL, 4800000, 4460000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FHZ-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Cắt nhanh hơn so với c&aacute;c m&aacute;y cưa kiếm cầm một tay kh&aacute;c tr&ecirc;n thị trường</li>\n	<li>Giảm độ rung gi&uacute;p khởi động cưa &ecirc;m hơn v&agrave; c&oacute; thể điều khiển dễ d&agrave;ng bằng một tay</li>\n	<li>Thiết kế gọn nhẹ cho ph&eacute;p dễ d&agrave;ng hoạt động trong những kh&ocirc;ng gian chật hẹp hoặc c&aacute;c ứng dụng tr&ecirc;n cao</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Tăng tốc độ cắt v&agrave; c&ocirc;ng suất trong c&aacute;c ứng dụng kh&oacute; thực hiện nhất</li>\n	<li>C&ocirc;ng nghệ pin REDLITHIUM&trade;-ION: Kết cấu tối ưu, bọ mạch điện tử th&ocirc;ng minh v&agrave; khả năng hoạt động vượt trội gi&uacute;p m&aacute;y l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của pin so với bất kỳ loại pin n&agrave;o tr&ecirc;n thị trường.</li>\n	<li>Thiết kế cầm bằng một tay mang lại khả năng kiểm so&aacute;t v&agrave; độ linh hoạt vượt trội so với c&aacute;c loại cưa kiếm kh&aacute;c</li>\n	<li>Độ sọc 22 mm gi&uacute;p cắt được nhiều vật liệu hơn với mỗi h&agrave;nh tr&igrave;nh cắt</li>\n	<li>Đế xoay gi&uacute;p tiếp x&uacute;c li&ecirc;n tục với chi tiết gia c&ocirc;ng khiến c&aacute;c vết cắt mượt m&agrave; hơn với độ x&ocirc; v&agrave; độ rung &iacute;t hơn</li>\n	<li>Hệ thống bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; kết hợp với M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; gi&uacute;p tăng tuổi thọ của m&aacute;y gấp 3 lần cho c&ocirc;ng cụ so với c&aacute;c m&aacute;y cưa kh&aacute;c tr&ecirc;n thị trường</li>\n	<li>Bộ pin M18&trade; REDLITHIUM&trade;-ION tương th&iacute;ch với hơn 125 sản phẩm c&ugrave;ng hệ thống M18</li>\n</ul>\n', '1_20230704051755.webp', 'resize_1_20230704051755.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(286, 1, 103, NULL, 0, 0, 'may-cua-kiem-m18-fsx-0c-2722', 'Máy cưa kiếm M18 FSX-0C (2722)', '', '', NULL, 8400000, 7800000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FSX-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Gi&uacute;p m&aacute;y cưa kiếm M18 FSX c&oacute; khả năng l&agrave;m việc v&agrave; hiệu suất tương đương m&aacute;y cưa kiếm d&ugrave;ng điện 15A</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION HIGH OUTPUT&trade; HD12.0: Mạnh mẽ hơn 50% v&agrave; vận h&agrave;nh m&aacute;t hơn 50% so với bộ pin REDLITHIUM&trade;-ION HD ti&ecirc;u chuẩn. Kết cấu chắc chắn mang lại khả năng bảo vệ tốt nhất trước những điều kiện l&agrave;m việc tại c&ocirc;ng trường</li>\n	<li>C&ocirc;ng tắc t&ugrave;y biến tốc độ v&agrave; n&uacute;t điều chỉnh 5 tốc độ mang lại khả năng kiểm so&aacute;t tốc độ tối ưu</li>\n	<li>Đ&egrave;n LED tăng độ ch&iacute;nh x&aacute;c v&agrave; r&otilde; n&eacute;t</li>\n	<li>Kẹp lưỡi QUIK-LOK&reg; gi&uacute;p thay lưỡi dao dễ d&agrave;ng m&agrave; kh&ocirc;ng cần c&ocirc;ng cụ hỗ trợ</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade;: Đảm bảo hiệu suất tối ưu v&agrave; chống qu&aacute; tải để ngăn ngừa hỏng h&oacute;c giữa m&aacute;y v&agrave; pin khi thực hiện c&aacute;c ứng dụng nặng trong khi vẫn duy tr&igrave; được khả năng tương th&iacute;ch tr&ecirc;n to&agrave;n hệ thống M18&trade;</li>\n	<li>Độ sọc 32 mm gi&uacute;p cắt được nhiều vật liệu hơn với mỗi h&agrave;nh tr&igrave;nh</li>\n	<li>M&oacute;c treo t&iacute;ch hợp thuận tiện cất giữ sau mỗi lần cắt</li>\n	<li>Đế c&oacute; thể điều chỉnh gi&uacute;p k&eacute;o d&agrave;i tuổi thọ của lưỡi dao</li>\n	<li>Tương th&iacute;ch với tất cả c&aacute;c Pin M18&trade;</li>\n</ul>\n', '1_20230704051856.webp', 'resize_1_20230704051856.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(287, 1, 103, NULL, 0, 0, 'may-cua-kiem-m18-fsz-0x0-bare', 'Máy cưa kiếm M18 FSZ-0X0 (bare)', '', '', NULL, 6600000, 6130000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FSZ-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; cho tuổi thọ động cơ d&agrave;i hơn v&agrave; cắt nhanh hơn</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade; mang đến khả năng chống qu&aacute; tải kỹ thuật số ti&ecirc;n tiến cho c&ocirc;ng cụ v&agrave; pin, đồng thời n&acirc;ng cao hiệu suất của c&ocirc;ng cụ khi thực hiện c&ocirc;ng việc</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION chắc chắn, kiểm so&aacute;t điện tử v&agrave; hiệu suất bền bỉ gi&uacute;p k&eacute;o d&agrave;i thời gian vận h&agrave;nh v&agrave; l&agrave;m được nhiều việc hơn trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>Gi&aacute;m s&aacute;t từng vi&ecirc;n pin tối ưu h&oacute;a thời gian chạy của c&ocirc;ng cụ v&agrave; đảm bảo độ bền l&acirc;u d&agrave;i của pin</li>\n	<li>Bộ ly hợp bảo vệ b&aacute;nh răng đ&atilde; được cấp bằng s&aacute;ng chế - k&eacute;o d&agrave;i tuổi thọ của b&aacute;nh răng v&agrave; động cơ bằng c&aacute;ch hấp thụ lực t&aacute;c động cao do kh&oacute;a lưỡi đột ngột</li>\n	<li>Kẹp lưỡi FIXTEC&trade; để thay lưỡi nhanh ch&oacute;ng v&agrave; dễ d&agrave;ng m&agrave; kh&ocirc;ng cần ch&igrave;a kh&oacute;a</li>\n	<li>Đế t&igrave; c&oacute; thể điều chỉnh để sử dụng tối ưu c&aacute;c lưỡi cưa</li>\n	<li>T&iacute;ch hợp đ&egrave;n đo nhi&ecirc;n liệu &amp; đ&egrave;n LED</li>\n	<li>M&oacute;c treo kim loại bền để quản l&yacute; kh&ocirc;ng gian l&agrave;m việc v&agrave; an to&agrave;n</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả pin Milwaukee&trade; M18&trade;</li>\n</ul>\n', '1_20230704052130.webp', 'resize_1_20230704052130.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(288, 1, 103, NULL, 0, 0, 'may-cua-vong-m18-cbs125-0-2729', 'Máy cưa vòng M18 CBS125-0 (2729)', '', '', NULL, 9480000, 8800000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 CBS125-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Gi&uacute;p tăng tốc độ cắt v&agrave; c&ocirc;ng suất để thực hiện c&aacute;c ứng dụng kh&oacute; khăn nhất</li>\n	<li>C&ocirc;ng nghệ c&ocirc;ng suất kh&ocirc;ng đổi CPT&trade;: Duy tr&igrave; tốc độ cắt trong c&aacute;c ứng dụng kh&oacute; thực hiện nhất để c&oacute; hiệu suất tối ưu</li>\n	<li>Hơn 90% chi tiết cấu tạo giống M&aacute;y cưa v&ograve;ng d&ugrave;ng điện của MILWAUKEE</li>\n	<li>Jobsite Armor Technology&trade;: C&ocirc;ng nghệ bảo vệ an to&agrave;n gi&uacute;p c&ocirc;ng cụ tr&aacute;nh khỏi những va đập hoặc mảnh vụn vỡ của vật liệu trong qu&aacute; tr&igrave;nh thi c&ocirc;ng</li>\n	<li>Bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade;: Cung cấp hiệu suất tối ưu v&agrave; chống qu&aacute; tải bằng việc kết nối, kiểm so&aacute;t to&agrave;n bộ hệ thống hoạt động giữa m&aacute;y, pin v&agrave; sạc</li>\n	<li>Hệ thống truyền động trực tiếp ho&agrave;n to&agrave;n bằng kim loại: Mang lại tuổi thọ tối đa cho c&ocirc;ng cụ nhờ hệ thống truyền động trực tiếp ho&agrave;n to&agrave;n bằng kim loại, giảm thiểu quy tr&igrave;nh bảo tr&igrave; hơn so với hệ thống truyền động bằng x&iacute;ch</li>\n	<li>Pin REDLITHIUM&trade;-ION: Kết cấu chắc chắn, hiệu quả l&agrave;m việc cao hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin.</li>\n	<li>M&aacute; phanh mở/kh&oacute;a lưỡi dễ d&agrave;ng, kh&ocirc;ng cần dụng cụ kh&aacute;c</li>\n	<li>Khả năng cắt lớn nhất tr&ecirc;n thị trường: C&oacute; thể linh hoạt cắt tới 125 mm x 125 mm vật liệu trong một lần v&agrave; đế c&oacute; thể điều chỉnh cho ph&eacute;p xoay c&ocirc;ng cụ &iacute;t hơn khi cắt vật liệu tr&ecirc;n 125 mm</li>\n	<li>Đ&egrave;n LED: Chiếu s&aacute;ng bề mặt cắt để c&oacute; được độ ch&iacute;nh x&aacute;c v&agrave; hiệu suất cao hơn</li>\n</ul>\n', '1_20230704052544.webp', 'resize_1_20230704052544.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-05', '2023-07-05', '', NULL, NULL, NULL),
(289, 1, 103, NULL, 0, 0, 'may-cua-vong-m18-fbs85-0c0-2829', 'Máy cưa vòng M18 FBS85-0C0 (2829)', '', '', NULL, 7920000, 7350000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FBS85-0C0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Động cơ kh&ocirc;ng chổi than POWERSTATE&trade; mang lại tốc độ cắt nhanh nhất so với c&aacute;c m&aacute;y cưa v&ograve;ng kh&aacute;c</li>\n	<li>C&ocirc;ng suất lớn nhất so với sản phẩm c&ugrave;ng loại: C&oacute; thể linh hoạt cắt vật liệu l&ecirc;n đến 85mm x 85mm trong một lần cắt</li>\n	<li>Thiết kế si&ecirc;u nhẹ để tăng độ c&acirc;n bằng</li>\n	<li>CPT Constant Power Technology&trade;: duy tr&igrave; tốc độ cắt tr&ecirc;n những bề mặt cắt phức tạp nhất để đạt hiệu suất tối ưu</li>\n	<li>Jobsite Armor Technology&trade;: vật liệu composite độc quyền v&agrave; c&aacute;c tấm chắn lưỡi cắt cung cấp khả năng bảo vệ bền bỉ l&acirc;u d&agrave;i</li>\n	<li>N&uacute;t k&iacute;ch hoạt tốc độ t&ugrave;y chỉnh: Cung cấp khả năng kiểm so&aacute;t tốc độ tối đa</li>\n	<li>Đ&egrave;n LED: chiếu s&aacute;ng bề mặt l&agrave;m việc để tăng độ ch&iacute;nh x&aacute;c v&agrave; năng suất</li>\n	<li>REDLINK PLUS&trade; Intelligence: hệ thống điện tử th&ocirc;ng minh kh&ocirc;ng d&acirc;y ti&ecirc;n tiến nhất, cung cấp hiệu suất tối ưu v&agrave; chống qu&aacute; tải bằng c&aacute;ch sử dụng khả năng giao tiếp to&agrave;n hệ thống giữa c&ocirc;ng cụ, pin v&agrave; bộ sạc</li>\n	<li>Truyền động trực tiếp bằng kim loại ho&agrave;n to&agrave;n: mang lại tuổi thọ dụng cụ tối đa cho tất cả hệ thống b&aacute;nh răng truyền động trực tiếp bằng kim loại, đồng thời y&ecirc;u cầu bảo dưỡng &iacute;t hơn so với truyền động x&iacute;ch</li>\n	<li>Ch&acirc;n đế t&igrave; khi cắt c&oacute; thể điều chỉnh linh hoạt: N&uacute;t bấm để mở/ đ&oacute;ng ch&acirc;n đế t&igrave; chỉ trong v&agrave;i gi&acirc;y</li>\n	<li>Ho&agrave;n to&agrave;n tương th&iacute;ch với hệ thống M18&trade;, với hơn 200 c&ocirc;ng cụ</li>\n</ul>\n', '1_20230704052711.jpg.webp', 'resize_1_20230704052711.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-05', '2023-07-05', '', '.webp', NULL, NULL),
(290, 1, 103, NULL, 0, 0, 'may-cua-xich-m18-fchs-0g0-2727', 'Máy cưa xích M18 FCHS-0G0 (2727)', '', '', NULL, 10800000, 10700000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FCHS-0G0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '', '1_20230704052824.webp', 'resize_1_20230704052824.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(291, 1, 103, NULL, 0, 0, 'may-hut-bui-cam-tay-m18-fcvl-0-0940', 'Máy hút bụi cầm tay M18 FCVL-0 (0940)', '', '', NULL, 10200000, 9920000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FCVL-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M18</p>\n', '', NULL, NULL, '', '', '1_20230704052927.webp', 'resize_1_20230704052927.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 10, NULL),
(292, 1, 103, NULL, 0, 0, 'may-hut-bui-da-nang-m18-cv-0-0882', 'Máy hút bụi đa năng M18 CV-0 (0882)', '', '', NULL, 3600000, 3400000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 CV-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M18</p>\n', '', NULL, NULL, '', '', '1_20230704053038.webp', 'resize_1_20230704053038.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 10, NULL),
(293, 1, 103, NULL, 0, 0, 'may-hut-bui-kho-uot-m18-vc-2-0-0880', 'Máy hút bụi khô, ướt M18 VC-2-0 (0880)', '', '', NULL, 3960000, 3680000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 VC-2-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>C&ocirc;ng suất h&uacute;t mạnh cho c&aacute;c ứng dụng ướt v&agrave; kh&ocirc;</li>\n	<li>Hơn 30 ph&uacute;t sử dụng với pin M18&trade; REDLITHIUM&trade;-ION HIGH DEMAND&trade; 9.0 Ah</li>\n	<li>M&aacute;y n&acirc;ng thủy lực 81 cm</li>\n	<li>Cổng thổi t&iacute;ch hợp</li>\n	<li>Đường k&iacute;nh ống: 32 mm</li>\n	<li>Phụ kiện đi k&egrave;m: Ống mềm d&agrave;i 183 cm, Đầu h&uacute;t bụi dạng ống, V&ograve;i đa năng v&agrave; Bộ lọc HEPA</li>\n	<li>Hộp đựng t&iacute;ch hợp gọn g&agrave;ng: Ống, V&ograve;i đa năng, Đầu h&uacute;t bụi dạng ống</li>\n	<li>1246 l/ph&uacute;t</li>\n	<li>Thiết kế hộp đựng c&oacute; thể xếp chồng</li>\n	<li>Đi k&egrave;m bộ lọc HEPA</li>\n	<li>Dung t&iacute;ch 7,5L</li>\n</ul>\n', '1_20230704053155.webp', 'resize_1_20230704053155.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 10, NULL),
(294, 1, 103, NULL, 0, 0, 'may-khoan-bua-m18-chx-0x0-2712', 'Máy khoan búa M18 CHX-0X0 (2712*)', '', '', NULL, 8400000, 7000000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 CHX-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan b&uacute;a v&agrave; đục M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>C&ocirc;ng nghệ FUEL&trade;: Mang lại tốc độ nhanh hơn m&aacute;y d&ugrave;ng điện, bền bỉ như m&aacute;y d&ugrave;ng điện v&agrave; d&ugrave;ng cả ng&agrave;y với một lần sạc.</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Cung cấp 2,5 J năng lượng t&aacute;c động, 0-1.400 v&ograve;ng/ph&uacute;t v&agrave; 0-4.900 v&ograve;ng/ph&uacute;t.</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION: D&ugrave;ng cả ng&agrave;y với một lần sạc, c&ocirc;ng suất tối đa v&agrave; sạc lại được nhiều lần hơn.</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade;: T&iacute;ch hợp khả năng kết nối to&agrave;n diện giữa c&ocirc;ng cụ, pin v&agrave; bộ sạc để chống qu&aacute; tải, qu&aacute; nhiệt v&agrave; xả điện qu&aacute; mức.</li>\n	<li>Hệ thống chống rung AVS: Giảm thiểu độ rung để mang lại sự thoải m&aacute;i tối đa</li>\n</ul>\n', '1_20230704053319.webp', 'resize_1_20230704053319.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 6, NULL),
(295, 1, 103, NULL, 0, 0, 'may-khoan-dong-luc-m18-fpd2-0x-2804', 'Máy khoan động lực M18 FPD2-0X (2804)', '', '', NULL, 5760000, 5040000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FPD2-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Được chế tạo cho M&aacute;y khoan động lực M18 FUEL&trade;, mạnh mẽ hơn tới 60% so với m&aacute;y khoan kh&aacute;c tr&ecirc;n thị trường</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION: tăng thời gian vận h&agrave;nh sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin so với pin của đối thủ cạnh tranh</li>\n	<li>Chiều d&agrave;i chỉ 17,5 cm cho ph&eacute;p tiếp cận dễ d&agrave;ng hơn trong những kh&ocirc;ng gian chật hẹp v&agrave; giảm mệt mỏi</li>\n	<li>Tương th&iacute;ch với tất cả c&aacute;c pin M18&trade;</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade;: Đảm bảo hiệu suất tối ưu v&agrave; chống qu&aacute; tải để ngăn ngừa hỏng h&oacute;c giữa m&aacute;y v&agrave; pin khi thực hiện c&aacute;c ứng dụng nặng trong khi vẫn duy tr&igrave; được khả năng tương th&iacute;ch tr&ecirc;n to&agrave;n hệ thống M18&trade;</li>\n	<li>Mạnh mẽ hơn tới 60% khi ở tốc độ cao: 135 Nm</li>\n	<li>Đ&egrave;n LED ở đế c&ocirc;ng cụ gi&uacute;p chiếu s&aacute;ng r&otilde; hơn ở những kh&ocirc;ng gian tối</li>\n</ul>\n', '1_20230704053433.webp', 'resize_1_20230704053433.webp', 0, '', NULL, 1, 1, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 5, NULL);
INSERT INTO `toandanh_tproducts` (`nid`, `nid_material_products`, `nid_cat_products`, `nid_brand_products`, `nid_weight`, `ctype`, `ccode`, `cproducts`, `eng_cproducts`, `ctag`, `nview`, `fprice`, `fprice_sale`, `nquantity`, `cdescription`, `eng_cdescription`, `cmodel`, `cpower`, `eng_cdetail`, `cdetail`, `cimage`, `cimage_resize`, `nspecial_products`, `cnote`, `eng_cnote`, `nstatus`, `ncheck`, `nnew`, `nkm`, `npb`, `cindex`, `niduser01`, `niduser02`, `ddate01`, `ddate02`, `clink`, `cproduct_fb`, `nid_sub_menu`, `clink_shoppe`) VALUES
(296, 1, 103, NULL, 0, 0, 'may-khoan-tu-m18-fmdp-0c0-2787', 'Máy khoan từ M18 FMDP-0C0 (2787)', '', '', NULL, 36000000, 31800000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FMDP-0C0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Mang lại c&ocirc;ng suất tối đa v&agrave; tuổi thọ d&agrave;i hơn.</li>\n	<li>Hệ thống quản l&yacute; bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; ngăn ngừa hỏng h&oacute;c c&ocirc;ng cụ cũng như pin do qu&aacute; tải hoặc qu&aacute; nhiệt</li>\n	<li>Pin REDLITHIUM&trade;-ION c&oacute; thể l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của pin</li>\n	<li>Đế từ tự cấp nguồn hoạt động độc lập với nguồn điện v&agrave; cung cấp lực giữ l&ecirc;n tới 8890 N</li>\n	<li>Khả năng của mũi kho&eacute;t lỗ kim loại 38 mm</li>\n	<li>Khả năng của mũi khoan xoắn 13 mm</li>\n	<li>Hộp số 2 tốc độ: 400 / 690 v&ograve;ng/ph&uacute;t</li>\n	<li>Độ sọc: 146 mm</li>\n	<li>Điều chỉnh đầu của m&ocirc; tơ: 130 mm</li>\n</ul>\n', '1_20230704053539.webp', 'resize_1_20230704053539.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 5, NULL),
(297, 1, 103, NULL, 0, 0, 'may-mai-goc-m18-cag100x-0x-2781', 'Máy mài góc M18 CAG100X-0X (2781)', '', '', NULL, 5160000, 4300000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 CAG100X-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Mang lại c&ocirc;ng suất tối đa v&agrave; tuổi thọ d&agrave;i hơn</li>\n	<li>Hệ thống bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; cung cấp hiệu suất tối ưu, ly hợp điện tử v&agrave; chống qu&aacute; tải bằng việc kết nối đồng bộ giữa m&aacute;y, pin v&agrave; sạc</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION c&oacute; kết cấu chắc chắn, c&oacute; linh kiện điện tử v&agrave; hiệu suất bền bỉ gi&uacute;p k&eacute;o d&agrave;i thời gian vận h&agrave;nh để l&agrave;m việc hiệu quả hơn trong suốt v&ograve;ng đời của bộ pin</li>\n	<li>C&Ocirc;NG SUẤT M&Agrave;I: Như m&aacute;y d&ugrave;ng điện.</li>\n	<li>ĐỘ BỀN: Hệ thống truyền động &amp; vỏ kim loại giống m&aacute;y m&agrave;i d&ugrave;ng điện hiệu suất cao huyền thoại trước đ&acirc;y</li>\n</ul>\n', '1_20230704053644.jpg.webp', 'resize_1_20230704053644.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 7, NULL),
(298, 1, 103, NULL, 0, 0, 'may-mai-goc-m18-cag100xpdb-0x-2780', 'Máy mài góc M18 CAG100XPDB-0X (2780)', '', '', NULL, 5760000, 4800000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 CAG100XPDB-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>T&iacute;nh năng phanh Dừng nhanh dừng đĩa cắt trong 0,9 gi&acirc;y, đĩa nh&aacute;m trong 1,3 gi&acirc;y v&agrave; đĩa m&agrave;i trong 1,5 gi&acirc;y</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Mang lại c&ocirc;ng suất tối đa v&agrave; tuổi thọ m&ocirc; tơ d&agrave;i hơn</li>\n	<li>Hệ thống quản l&yacute; th&ocirc;ng minh REDLINK PLUS&trade; cung cấp hiệu suất tối ưu, ly hợp điện tử v&agrave; chống qu&aacute; tải bằng c&aacute;ch sử dụng to&agrave;n bộ kết nối hệ thống giữa c&ocirc;ng cụ, pin v&agrave; sạc</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION được thiết kế chắc chắn, c&oacute; linh kiện điện tử v&agrave; hiệu suất bền bỉ gi&uacute;p k&eacute;o d&agrave;i thời gian vận h&agrave;nh v&agrave; l&agrave;m được nhiều việc hơn trong suốt v&ograve;ng đời của pin</li>\n	<li>C&Ocirc;NG SUẤT M&Agrave;I: Như m&aacute;y d&ugrave;ng điện.</li>\n	<li>ĐỘ BỀN: Hệ thống truyền động &amp; vỏ kim loại giống như c&aacute;c m&aacute;y m&agrave;i d&ugrave;ng điện hiệu suất cao nổi tiếng</li>\n</ul>\n', '1_20230704053754.webp', 'resize_1_20230704053754.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(299, 1, 103, NULL, 0, 0, 'may-mai-goc-m18-cag125xpdb-0-2783', 'Máy mài góc M18 CAG125XPDB-0 (2783)', '', '', NULL, 6000000, 5000000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 CAG125XPDB-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Được thiết kế v&agrave; x&acirc;y dựng bởi MILWAUKEE&trade; với m&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả c&aacute;c pin M18&trade; MILWAUKEE&trade;</li>\n	<li>Hệ thống bo mạch điện tử REDLINK PLUS&trade; mang đến khả năng chống qu&aacute; tải kỹ thuật số ti&ecirc;n tiến nhất cho m&aacute;y v&agrave; pin, đồng thời n&acirc;ng cao hiệu suất của m&aacute;y khi c&oacute; tải</li>\n	<li>với pin 4REDLITHIUM&trade;-ION c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn, mạnh mẽ hơn v&agrave; tuổi thọ pin k&eacute;o d&agrave;i hơn</li>\n	<li>RAPIDSTOP&trade; với tốc độ phanh đĩa nhanh nhất chỉ trong v&ograve;ng chưa đầy 2 gi&acirc;y v&agrave; bảo vệ người d&ugrave;ng tốt nhất</li>\n	<li>Thanh bảo vệ kh&ocirc;ng cần kh&oacute;a 125 mm - khả năng cắt tuyệt vời v&agrave; điều chỉnh thanh bảo vệ nhanh m&agrave; kh&ocirc;ng cần d&ugrave;ng ch&igrave;a vặn</li>\n	<li>thay b&aacute;nh cắt ho&agrave;n to&agrave;n kh&ocirc;ng cần c&ocirc;ng cụ hỗ trợ</li>\n	<li>Thiết kế tay cầm mảnh</li>\n	<li>M&agrave;n chống bụi c&oacute; thể th&aacute;o rời để ngăn bụi bẩn x&acirc;m nhập, k&eacute;o d&agrave;i tuổi thọ của m&ocirc; tơ</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả c&aacute;c pin M18&trade; MILWAUKEE&trade;</li>\n	<li>Đai ốc FIXTEC để thay đĩa cắt m&agrave; kh&ocirc;ng cần c&ocirc;ng cụ hỗ trợ</li>\n</ul>\n', '1_20230704053927.webp', 'resize_1_20230704053927.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 7, NULL),
(300, 1, 103, NULL, 0, 0, 'may-mai-khuon-m18-fdg-0c-2784', 'Máy mài khuôn M18 FDG-0C (2784)', '', '', NULL, 5520000, 5120000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FDG-0C</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; của MILWAUKEE&trade; mạnh mẽ hơn, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn v&agrave; tuổi thọ d&agrave;i hơn.</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION của MILWAUKEE&trade; l&agrave; bộ pin bền nhất tr&ecirc;n thị trường, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn, mạnh mẽ hơn v&agrave; tuổi thọ pin cao hơn.</li>\n	<li>Hệ thống th&ocirc;ng minh điện tử REDLINK PLUS&trade; hỗ trợ kết nối n&acirc;ng cao giữa pin v&agrave; c&ocirc;ng cụ, mang lại hiệu suất, sự bảo vệ v&agrave; hiệu năng chưa từng c&oacute;.</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than c&oacute; tốc độ quay 20.000 v&ograve;ng/ph&uacute;t được thiết kế để mang lại hiệu suất như m&aacute;y d&ugrave;ng điện trong khi sử dụng c&aacute;c mũi m&agrave;i hợp kim, b&aacute;nh nh&aacute;m l&ecirc;n tới 3&quot;.</li>\n	<li>Bộ pin M18&trade; REDLITHIUM&trade;-ION 5.0Ah gi&uacute;p m&agrave;i trong hơn 20 ph&uacute;t</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than kh&ocirc;ng c&oacute; bộ phận đeo gi&uacute;p k&eacute;o d&agrave;i tuổi thọ cho c&ocirc;ng cụ.</li>\n</ul>\n', '1_20230704054138.jpg.webp', 'resize_1_20230704054138.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 7, NULL),
(301, 1, 103, NULL, 0, 0, 'may-phay-m18-ftr-0x0-2723', 'Máy phay M18 FTR-0X0 (2723)', '', '', NULL, 6600000, 6130000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FTR-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;M&agrave;i, cưa, cắt v&agrave; đ&aacute;nh b&oacute;ng M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade;: Sức mạnh của m&aacute;y phay d&ugrave;ng pin nhỏ gọn c&ugrave;ng tốc độ quay lớn hơn để ho&agrave;n th&agrave;nh c&aacute;c thao t&aacute;c cắt tr&ecirc;n gỗ cứng</li>\n	<li>Hệ thống th&ocirc;ng minh REDLINK PLUS&trade; đảm bảo hiệu suất tối đa cũng như chống qu&aacute; tải, qu&aacute; nhiệt v&agrave; xả pin qu&aacute; mức</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION: Gi&uacute;p l&agrave;m được nhiều việc hơn sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của bộ pin so với pin của đối thủ cạnh tranh</li>\n	<li>Điều chỉnh tốc độ t&ugrave;y &yacute; c&oacute; phạm vi từ 10.000 đến 31.000 v&ograve;ng ph&uacute;t, mang lại sự điều khiển ch&iacute;nh x&aacute;c để cho kết quả cạnh v&agrave; chi tiết đẹp, c&acirc;n đối</li>\n	<li>N&uacute;t điều chỉnh lớn cho ph&eacute;p thực hiện ch&iacute;nh x&aacute;c c&aacute;c điều chỉnh lớn</li>\n	<li>V&iacute;t điều chỉnh nhỏ cho ph&eacute;p thực hiện c&aacute;c điều chỉnh ch&iacute;nh x&aacute;c vượt qua lượng tăng 1/64&quot;</li>\n	<li>Kh&oacute;a trục quay kh&ocirc;ng cần c&ocirc;ng cụ hỗ trợ cho ph&eacute;p thay mũi khoan bằng một cờ l&ecirc; kẹp</li>\n	<li>Tương th&iacute;ch với mũi khoan soi c&oacute; chu&ocirc;i 6mm hay 1/4&quot;</li>\n	<li>Đ&egrave;n LED chiếu s&aacute;ng bề mặt cắt</li>\n	<li>Tương th&iacute;ch với phụ kiện Bệ phay ch&igrave;m v&agrave; Bệ lệch của Milwaukee (b&aacute;n ri&ecirc;ng)</li>\n	<li>Một phần của Hệ thống M18, gồm hơn 200 c&ocirc;ng cụ</li>\n</ul>\n', '1_20230704054244.webp', 'resize_1_20230704054244.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 10, NULL),
(302, 1, 103, NULL, 0, 0, 'may-siet-bu-long-m18-fhiwf12-0x-2767', 'Máy siết bu lông M18 FHIWF12-0X (2767)', '', '', NULL, 8160000, 7570000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FHIWF12-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Mang lại hiệu năng tối đa nhờ khả năng th&aacute;o c&aacute;c ốc chặt v&agrave; c&oacute; lực siết cao nhanh hơn so với m&aacute;y của đối thủ cạnh tranh</li>\n	<li>M&aacute;y siết bu l&ocirc;ng cường độ cao d&ugrave;ng pin, nhỏ gọn nhất tr&ecirc;n thị trường c&oacute; chiều d&agrave;i 213 mm</li>\n	<li>Khả năng vặn 4 chế độ dẫn đầu tr&ecirc;n thị trường c&ugrave;ng với chế độ th&aacute;o bu l&ocirc;ng cho ph&eacute;p kiểm so&aacute;t tối đa.</li>\n	<li>Chế độ th&aacute;o bu l&ocirc;ng 4 c&oacute; khả năng cung cấp lực mở tối đa để mở ốc dễ d&agrave;ng, sau đ&oacute; giảm tốc độ xuống 750 v&ograve;ng/ph&uacute;t để c&oacute; thể kiểm so&aacute;t dễ d&agrave;ng hơn khi th&aacute;o ốc</li>\n	<li>Hệ thống bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; gi&uacute;p bảo vệ m&aacute;y v&agrave; pin khỏi qu&aacute; tải hoặc qu&aacute; nhiệt</li>\n	<li>Pin REDLITHIUM&trade;-ION gi&uacute;p tăng khả năng l&agrave;m việc sau mỗi lần sạc v&agrave; trong suốt v&ograve;ng đời của pin</li>\n	<li>Thiết kế đầu cốt c&oacute; v&ograve;ng ma s&aacute;t đảm bảo việc th&aacute;o lắp đầu khẩu nhanh ch&oacute;ng v&agrave; dễ d&agrave;ng</li>\n	<li>Vỏ cao su đ&uacute;c chắc chắn cao cấp chống chịu được c&aacute;c vật liệu ăn m&ograve;n v&agrave; mang lại sự thoải m&aacute;i hơn khi sử dụng</li>\n	<li>Thoải m&aacute;i khi sử dụng với trọng lượng chỉ 3,3 kg k&egrave;m theo pin 5.0Ah</li>\n	<li>Đ&egrave;n LED chiếu s&aacute;ng khu vực l&agrave;m việc</li>\n</ul>\n', '1_20230704054347.webp', 'resize_1_20230704054347.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 5, NULL),
(303, 1, 103, NULL, 0, 0, 'may-siet-bu-long-m18-fiw12-0-2755', 'Máy siết bu lông M18 FIW12-0 (2755)', '', '', NULL, 5400000, 4500000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FIW12-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Thiết kế nhỏ gọn nhưng c&oacute; khả năng cung cấp lực siết 300 Nm</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; của MILWAUKEE&trade; mang lại hiệu suất cao hơn, tuổi thọ l&acirc;u hơn v&agrave; khả năng l&agrave;m việc tối ưu</li>\n	<li>Hệ thống bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; cho ph&eacute;p người d&ugrave;ng kiểm so&aacute;t qu&aacute; tải, qu&aacute; nhiệt với 4 chế độ DRIVE CONTROL&trade; độc quyền của MILWAUKEE</li>\n</ul>\n', '1_20230704054447.webp', 'resize_1_20230704054447.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 5, NULL),
(304, 1, 103, NULL, 0, 0, 'may-siet-bu-long-m18-fiw212-0x0', 'Máy siết bu lông M18 FIW212-0X0', '', '', NULL, 5400000, 5020000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FIW212-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc;-men th&aacute;o l&ecirc;n đến 339Nm</li>\n	<li>M&ocirc;-men xoắn cực đại l&ecirc;n đến 339Nm</li>\n	<li>Chỉ 1,8 kg với Pin 5,0 Ah</li>\n	<li>Ba đ&egrave;n LED mới mang lại &aacute;nh s&aacute;ng độ n&eacute;t cao</li>\n	<li>Nhỏ gọn hơn để tăng khả năng tiếp cận v&agrave; kiểm so&aacute;t &ndash; Chiều d&agrave;i chỉ 127mm</li>\n	<li>C&agrave;i đặt 4 chế độ điều khiển - 4 tốc độ gi&uacute;p điều khiển tốt hơn</li>\n	<li>Bao gồm Chế độ dừng tự động; Ngăn siết chặt qu&aacute; mức</li>\n	<li>Bao gồm chế độ th&aacute;o bu l&ocirc;ng; Gi&uacute;p điều khiển tốt hơn sau khi th&aacute;o bu l&ocirc;ng</li>\n</ul>\n', '1_20230705085131.jpg.webp', 'resize_1_20230705085131.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 5, NULL),
(305, 1, 103, NULL, 0, 0, 'may-siet-bu-long-m18-fmtiw12-0x-2860', 'Máy siết bu lông M18 FMTIW12-0X (2860)', '', '', NULL, 6600000, 5500000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FMTIW12-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; của MILWAUKEE&trade; gi&uacute;p m&aacute;y mạnh mẽ hơn, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn v&agrave; tuổi thọ d&agrave;i hơn.</li>\n	<li>Pin REDLITHIUM&trade;-ION của MILWAUKEE&trade; l&agrave; d&ograve;ng pin bền bỉ nhất tr&ecirc;n thị trường, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn, mạnh mẽ hơn v&agrave; tuổi thọ pin cao hơn.</li>\n	<li>Hệ thống bo mạch điện tử th&ocirc;ng minh REDLINK PLUS&trade; hỗ trợ kết nối n&acirc;ng cao giữa pin v&agrave; m&aacute;y, mang lại hiệu suất v&agrave; an to&agrave;n tối ưu trong qu&aacute; tr&igrave;nh sử dụng</li>\n	<li>Cung cấp m&ocirc; men xoắn tối đa 610 Nm</li>\n	<li>Cung cấp m&ocirc; men th&aacute;o l&ecirc;n tới 813 Nm</li>\n	<li>3 chế độ DRIVE CONTROL&trade; mang lại nhiều khả năng kiểm so&aacute;t tốc độ v&agrave; c&ocirc;ng suất đầu ra hơn với tốc độ kh&ocirc;ng tải tối đa l&agrave; 2.400 v&ograve;ng/ph&uacute;t</li>\n	<li>Chiều d&agrave;i nhỏ gọn 175 mm cho ph&eacute;p tiếp cận dễ d&agrave;ng hơn trong những kh&ocirc;ng gian chật hẹp</li>\n	<li>Trọng lượng k&egrave;m pin 5.0Ah chỉ 2,5 kg gi&uacute;p người d&ugrave;ng thoải m&aacute;i khi thao t&aacute;c, lớp cao su bảo vệ th&acirc;n m&aacute;y chắc chắn</li>\n	<li>Đ&egrave;n LED tr&ecirc;n th&acirc;n m&aacute;y</li>\n</ul>\n', '1_20230705085251.webp', 'resize_1_20230705085251.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 5, NULL),
(306, 1, 103, NULL, 0, 0, 'may-siet-bu-long-m18-fmtiw2f12-0x0-2962', 'Máy siết bu lông M18 FMTIW2F12-0X0 (2962)', '', '', NULL, 6600000, 6130000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;Li&ecirc;n hệ đặt h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FMTIW2F12-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc;-men th&aacute;o l&ecirc;n đến 881Nm</li>\n	<li>M&ocirc;-men xoắn cực đại l&ecirc;n đến 745Nm</li>\n	<li>Chỉ 2,3kg với pin 5.0Ah</li>\n	<li>Nhỏ gọn hơn để tăng khả năng tiếp cận &amp; kiểm so&aacute;t - Chiều d&agrave;i chỉ 152mm</li>\n	<li>Tốc độ th&aacute;o bu l&ocirc;ng M22 trong 1,8 gi&acirc;y</li>\n	<li>Ba đ&egrave;n LED mới mang lại &aacute;nh s&aacute;ng độ n&eacute;t cao</li>\n	<li>C&agrave;i đặt 4 chế độ điều khiển - 4 tốc độ gi&uacute;p điều khiển tốt hơn</li>\n	<li>Bao gồm Chế độ dừng tự động; Ngăn siết chặt qu&aacute; mức</li>\n	<li>Bao gồm chế độ th&aacute;o bu l&ocirc;ng; Gi&uacute;p điều khiển tốt hơn sau khi th&aacute;o bu l&ocirc;ng</li>\n</ul>\n', '1_20230705085400.jpg.webp', 'resize_1_20230705085400.jpg.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 5, NULL),
(307, 1, 103, NULL, 0, 0, 'may-siet-bu-long-m18-onefhiwf1-0x0-2867', 'Máy siết bu lông M18 ONEFHIWF1-0X0 (2867)', '', '', NULL, 14400000, 13360000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 ONEFHIWF1-0X0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&aacute;y siết bu l&ocirc;ng M18 ONEFHIWF1 kh&ocirc;ng d&acirc;y đầu ti&ecirc;n tr&ecirc;n thế giới nhằm thay thế m&aacute;y siết bu l&ocirc;ng chạy bằng AC, xăng v&agrave; kh&iacute; n&eacute;n</li>\n	<li>M&aacute;y siết bu l&ocirc;ng M18 ONEFHIWF1 c&oacute; lực siết l&agrave; 2033 Nm, với k&iacute;ch cỡ nhỏ hơn v&agrave; nhẹ hơn c&aacute;c m&aacute;y siết chạy bằng AC hoặc kh&iacute; n&eacute;n</li>\n	<li>Cung cấp lực siết l&ecirc;n đến 2400 Nm để mở bu l&ocirc;ng l&ecirc;n đến M42</li>\n	<li>DRIVE CONTROL&trade; 4 chế độ cho ph&eacute;p người d&ugrave;ng chuyển sang 4 chế độ c&agrave;i đặt tốc độ v&agrave; lực siết kh&aacute;c nhau để tăng tối đa sự linh hoạt</li>\n	<li>Cảm biến đếm số lần thổi t&iacute;ch hợp nhằm tăng cường khả năng lặp lại nhất qu&aacute;n của thiết lập lực siết đ&atilde; chọn</li>\n	<li>Hệ thống pin linh hoạt: hoạt động với tất cả c&aacute;c pin Milwaukee&trade; M18&trade;</li>\n</ul>\n', '1_20230705085721.png.webp', 'resize_1_20230705085721.png.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 5, NULL),
(308, 1, 103, NULL, 0, 0, 'may-siet-bu-long-m18-onefhiwf34-0x-2864', 'Máy siết bu lông M18 ONEFHIWF34-0X (2864)', '', '', NULL, 8640000, 8020000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 ONEFHIWF34-0X</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>Lực th&aacute;o mở l&ecirc;n đến 2032 Nm</li>\n	<li>Nhỏ gọn nhất</li>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; cung cấp lực siết l&ecirc;n đến 1627 v&agrave; lực th&aacute;o mở ốc 2032 Nm</li>\n	<li>M&aacute;y siết bu l&ocirc;ng d&ugrave;ng pin mạnh mẽ nhất, nhỏ gọn nhất so với c&aacute;c sản phẩm c&ugrave;ng loại c&oacute; chiều d&agrave;i 218 mm</li>\n	<li>C&oacute; thiết kế v&ograve;ng ma s&aacute;t với lỗ xuy&ecirc;n đảm bảo thay đổi đầu khẩu nhanh ch&oacute;ng v&agrave; dễ d&agrave;ng</li>\n	<li>Lớp cao su bọc chắc chắn cao cấp chống chịu được c&aacute;c vật liệu ăn m&ograve;n v&agrave; mang lại sự thoải m&aacute;i hơn khi sử dụng</li>\n	<li>Đ&egrave;n LED rọi s&aacute;ng khu vực l&agrave;m việc</li>\n	<li>Một phần của Hệ thống M18&trade;, bao gồm hơn 150 c&ocirc;ng cụ</li>\n</ul>\n', '1_20230705085829.png.webp', 'resize_1_20230705085829.png.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 5, NULL),
