(312, 1, 103, NULL, 0, 0, 'may-tron-da-nang-m18-fpmc-0-2810', 'Máy trộn đa năng M18 FPMC-0 (2810)', '', '', NULL, 6600000, 5830000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FPMC-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Dụng cụ chuy&ecirc;n d&ugrave;ng M18</p>\n', '', NULL, NULL, '', '', '1_20230705090603.png.webp', 'resize_1_20230705090603.png.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 10, NULL),
(313, 1, 103, NULL, 0, 0, 'may-van-vit-thuy-luc-m18-fqid-0-2760', 'Máy vặn vít thủy lực M18 FQID-0 (2760)', '', '', NULL, 6000000, 5570000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;M18 FQID-0</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;MILWAUKEE</p>\n\n<p><strong>Loại</strong>:&nbsp;Khoan, siết v&agrave; vặn M18</p>\n', '', NULL, NULL, '', '<ul>\n	<li>M&ocirc; tơ kh&ocirc;ng chổi than POWERSTATE&trade; của MILWAUKEE&trade; mạnh mẽ hơn, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn v&agrave; tuổi thọ d&agrave;i hơn.</li>\n	<li>Hệ thống th&ocirc;ng minh điện tử REDLINK PLUS&trade; hỗ trợ kết nối n&acirc;ng cao giữa pin v&agrave; c&ocirc;ng cụ, mang lại hiệu suất, sự bảo vệ v&agrave; hiệu năng chưa từng c&oacute;.</li>\n	<li>Bộ pin REDLITHIUM&trade;-ION của MILWAUKEE&trade; l&agrave; bộ pin bền nhất tr&ecirc;n thị trường, c&oacute; thời gian vận h&agrave;nh l&acirc;u hơn, mạnh mẽ hơn v&agrave; tuổi thọ pin cao hơn.</li>\n	<li>Hệ thống truyền động thủy lực FLUID-DRIVE&trade; l&agrave;m giảm sự tiếp x&uacute;c giữa kim loại với kim loại trong c&ocirc;ng cụ, gi&uacute;p vận h&agrave;nh &ecirc;m &aacute;i hơn, hoạt động trơn tru hơn v&agrave; tăng độ bền so với m&aacute;y vặn v&iacute;t ti&ecirc;u chuẩn</li>\n	<li>Điều khiển 4 chế độ mang lại nhiều khả năng kiểm so&aacute;t tốc độ v&agrave; c&ocirc;ng suất đầu ra hơn</li>\n</ul>\n', '1_20230705090726.png.webp', 'resize_1_20230705090726.png.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', '.webp', 5, NULL),
