(394, 1, 106, NULL, 0, 0, 'dau-van-dung-cho-tay-can-luc-tone', 'Đầu vặn dùng cho tay cân lực TONE', '', '', NULL, 792000, 710000, NULL, '<p><strong>T&igrave;nh trạng:</strong>&nbsp;C&ograve;n h&agrave;ng</p>\n\n<p><strong>M&atilde; sản phẩm</strong>:&nbsp;10DRM-08</p>\n\n<p><strong>H&atilde;ng sản xuất</strong>:&nbsp;TONE</p>\n\n<p><strong>Loại</strong>:&nbsp;Phụ kiện cho dụng cụ đo lực</p>\n', '', NULL, NULL, '', '<p><img src=\"https://toandanhco.com.vn/fileman/Uploads/thocokhi/noi_dung_san_pham_47cb25ad0bed4764aa30b44be014e53f_master.webp\" /></p>\n', '1_20230705115748.webp', 'resize_1_20230705115748.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 1, 1, '2023-07-06', '2023-07-06', '', NULL, 19, NULL),
(395, 1, 111, NULL, 0, 0, 'cam-bien-do-buc-xa-mat-troi-sr05-hukseflux', 'CẢM BIẾN ĐO BỨC XẠ MẶT TRỜI SR05 HUKSEFLUX', '', '', NULL, 0, 0, NULL, '<p>-&nbsp;&nbsp; &nbsp;SR05 l&agrave; một thiết bị đo bức xạ mặt trời kinh tế, đ&aacute;p ứng được ti&ecirc;u chuẩn ISO 9060:2018.<br />\n-&nbsp;&nbsp; &nbsp;C&oacute; sẵn c&aacute;c cấu h&igrave;nh kh&aacute;c nhau tuỳ thuộc v&agrave;o c&aacute;ch gắn v&agrave; đầu ra cần thiết.&nbsp;<br />\n-&nbsp;&nbsp; &nbsp;Với chi ph&iacute; phải chăng c&ugrave;ng với lắp đặt dễ d&agrave;ng, thiết bị SR05 trở n&ecirc;n l&yacute; tưởng đối với c&aacute;c mạng lưới quan trắc thời tiết cũng như gi&aacute;m s&aacute;t hệ thống pin năng lượng mặt trời.</p>\n\n<ul>\n	<li>Đầu ra analog hoặc digital theo ti&ecirc;u chuẩn c&ocirc;ng nghiệp, dễ d&agrave;ng t&iacute;ch hợp v&agrave;o Datalogger</li>\n	<li>Dễ d&agrave;ng gắn v&agrave; c&acirc;n bằng</li>\n	<li>L&agrave; pyranometer second class n&ecirc;n gi&aacute; cả rất phải chăng</li>\n</ul>\n', '', NULL, NULL, NULL, '<p>- Thiết bị đo bức xạ mặt trời l&agrave; dụng cụ cần thiết cho c&aacute;c chuy&ecirc;n gia về lĩnh vực năng lượng mặt trời, thiết bị gi&uacute;p theo d&otilde;i hoạt động v&agrave; đ&aacute;nh gi&aacute; hiệu suất của pin mặt trời để c&oacute; thể đưa ra phương &aacute;n ph&ugrave; hợp cho pin.</p>\n\n<p>- Thiết bị đo bức xạ mặt trời c&oacute; vai tr&ograve; quan trọng trong ứng dụng v&agrave; ph&aacute;t triển của pin mặt trời. Dưới đ&acirc;y l&agrave; một số c&ocirc;ng d&ugrave;ng của thiết bị đo bức xạ mặt trời:</p>\n\n<ul>\n	<li><strong>Đ&aacute;nh gi&aacute; hiệu suất pin mặt trời:</strong>&nbsp;Thiết bị đo bức xạ mặt trời được sử dụng để đo lường lượng bức xạ mặt trời đến bề mặt pin mặt trời. Th&ocirc;ng qua việc đo lường n&agrave;y, ta c&oacute; thể đ&aacute;nh gi&aacute; hiệu suất hoạt động của pin mặt trời trong c&aacute;c điều kiện &aacute;nh s&aacute;ng kh&aacute;c nhau. Kết quả n&agrave;y cung cấp th&ocirc;ng tin quan trọng cho nh&agrave; sản xuất pin mặt trời để cải tiến c&ocirc;ng nghệ v&agrave; tăng cường hiệu suất năng lượng chuyển đổi.</li>\n	<li><strong>X&aacute;c định vị tr&iacute; v&agrave; hướng lắp đặt pin mặt trời:</strong>&nbsp;Dựa tr&ecirc;n dữ liệu bức xạ mặt trời thu thập từ thiết bị đo, ch&uacute;ng ta c&oacute; thể x&aacute;c định vị tr&iacute; v&agrave; hướng lắp đặt tối ưu cho pin mặt trời. Điều n&agrave;y gi&uacute;p đảm bảo pin nhận được lượng &aacute;nh s&aacute;ng tối đa trong suốt ng&agrave;y v&agrave; tối ưu h&oacute;a hiệu suất hoạt động của hệ thống năng lượng mặt trời.</li>\n	<li><strong>Thiết kế hệ thống pin mặt trời:</strong>&nbsp;Dự liệu bức xạ mặt trời thu thập từ thiết bị đo cung cấp th&ocirc;ng tin quan trọng cho việc thiết kế hệ thống pin mặt trời. C&aacute;c kỹ sư v&agrave; nh&agrave; thiết kế c&oacute; thể sử dụng th&ocirc;ng tin n&agrave;y để t&iacute;nh to&aacute;n số lượng pin cần thiết, k&iacute;ch thước của c&aacute;c th&agrave;nh phần v&agrave; x&aacute;c định c&aacute;c yếu tố ảnh hưởng đến hiệu suất của hệ thống.</li>\n	<li><strong>Theo d&otilde;i hoạt động v&agrave; hiệu suất pin mặt trời:</strong>&nbsp;Thiết bị đo bức xạ mặt trời cũng c&oacute; thể được sử dụng trong việc theo d&otilde;i hoạt động v&agrave; hiệu suất của pin mặt trời trong thời gian thực. Dữ liệu thu thập được gi&uacute;p ph&aacute;t hiện sự cố, đ&aacute;nh gi&aacute; t&igrave;nh trạng hoạt động của pin v&agrave; thực hiện c&aacute;c biện ph&aacute;p bảo tr&igrave; để duy tr&igrave; hiệu suất tối đa của hệ thống.</li>\n</ul>\n\n<h6><strong>Th&ocirc;ng số kỹ thuật:</strong></h6>\n\n<ul>\n	<li>Đo bức xạ mặt trời b&aacute;n cầu</li>\n	<li>Ph&acirc;n loại ISO Class C (second class) ISO 9060:2018</li>\n	<li>Hiệu chuẩn kh&ocirc;ng chắc chắn: &lt; 2.4% (k=2)</li>\n	<li>Hiệu chuẩn truy xuất nguồn gốc: WRR</li>\n	<li>Dải quang phổ đo: 285 &ndash; 3000 x 109&nbsp;m</li>\n	<li>Nhiệt độ hoạt động: 40 đến 80&nbsp;oC</li>\n	<li>Chiều d&agrave;i c&aacute;p ti&ecirc;u chuẩn 3 m</li>\n	<li>Dải điện &aacute;p hoạt động: 530VDC</li>\n	<li>Giao thức truyền th&ocirc;ng Modbus th&ocirc;ng qua 2 d&acirc;y RS485</li>\n	<li>Đầu ra kỹ thuật số bức xạ t&iacute;nh bằng W/m2, nhiệt độ t&iacute;nh bằng oC</li>\n	<li>Ng&otilde; ra tương tự 01V hoặc 4-20mA</li>\n	<li>Ti&ecirc;u chuẩn ISO 9060:2008: Quang phổ phẳng loại C</li>\n	<li>Dải quang phổ đo: 285 &ndash; 3000 x 10-9&nbsp;m</li>\n	<li>Nhiệt độ hoạt động: -40 đến +80 &deg;C.</li>\n	<li>Điện &aacute;p định mức: 5-30VDC</li>\n	<li>Chiều d&agrave;i c&aacute;p kết nối: 3m</li>\n</ul>\n\n<p><span lang=\"EN-US\" style=\"font-size:11.0pt\"><span style=\"background:yellow\"><span style=\"line-height:107%\"><span calibri=\"\" style=\"font-family:\">T&ugrave;y chọn ng&otilde; ra: Modbus RTU hoặc Analog (4-20mA, 0-1V).</span></span></span></span></p>\n\n<div class=\"row\">\n<div class=\"col-md-4\">\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SRO5_1.png\" /></div>\n</div>\n\n<div class=\"col-md-4\">\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SRO5_2.png\" /></div>\n</div>\n\n<div class=\"col-md-4\">\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SRO5_3.png\" /></div>\n</div>\n</div>\n\n<div class=\"row\">\n<div class=\"col-md-4\">\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SRO5_4.png\" /></div>\n</div>\n\n<div class=\"col-md-4\">\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SRO5_5.png\" /></div>\n</div>\n\n<div class=\"col-md-4\">\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SRO5_6.png\" /></div>\n</div>\n</div>\n', 'qt2_20231117104744.jpg.webp', 'resize_qt2_20231117104744.jpg.webp', 0, 'Thiết bị đo bức xạ mặt trời là dụng cụ cần thiết cho các chuyên gia về lĩnh vực năng lượng mặt trời, thiết bị giúp theo dõi hoạt động và đánh giá hiệu suất của pin mặt trời để có thể đưa ra phương án phù hợp cho pin.', NULL, 0, 0, 0, 0, 0, 1, 1, 1, '2024-05-29', '2024-05-29', '', '.webp', 0, ''),
(396, 1, 107, NULL, 0, 0, 'tu-loc-song-hai-chu-dong-ahf', 'TỦ LỌC SÓNG HÀI CHỦ ĐỘNG AHF', '', '', NULL, 0, 0, NULL, '\r\n<p>Tủ lọc sóng hài tích cực là giải pháp mới giúp cải thiện chất lượng điện của nhà máy...</p>\r\n<script src=\"//cdn.public.flmngr.com/FLMNFLMN/widgets.js\"></script>\r\n', '', NULL, NULL, NULL, '\r\n<p>Tủ lọc sóng hài tích cực là giải pháp mới giúp cải thiện chất lượng điện của nhà máy, khu công nghiệp. Tủ lọc sóng hài tích cực được ứng dụng công nghệ mới nhất, sử dụng bộ đo tín hiệu để thu thập tín hiệu sóng hài trên hệ thống qua bộ vi xử lý DSP, sau đó đưa tín hiệu ra bộ nghịch lưu IGBT để phát lại lượng sóng hài có giá trị bằng bộ sóng hài trên hệ thống nhưng ngược pha và triệt tiêu sóng hài trên hệ thống.</p>\r\n\r\n<div style=\"text-align: center;\"><img src=\"/fileman/Uploads/product/tlsh.png\" style=\"height: 526px; width: 800px;\"></div>\r\n\r\n<p><strong>Nhiều chức năng hơn, nhiều chế độ hơn</strong></p>\r\n\r\n<ul>\r\n	<li>Bù sóng hài, bù công suất phản kháng, cân bằng điện áp được tích hợp trong 1 tủ lọc sóng hài</li>\r\n	<li>Với chức năng bù phân chia sóng hài, có thể đặt tỷ lệ bù phản kháng</li>\r\n	<li>Màn hình cảm ứng màu HD 7 (10) inch, màn hình có thể hiển thị các thông số hoạt động của hệ thống và thiết bị trong thời gian thực</li>\r\n</ul>\r\n\r\n<p><strong>Bảo vệ toàn diện để hoạt động ổn định</strong></p>\r\n\r\n<ul>\r\n	<li>Do thuật toán giới hạn dòng điện tự động được thiết lập cả RMS và giá trị đỉnh, khi dòng điện hài tải lớn hơn đầu ra của thiết bị, dòng đầu ra của thiết bị có thể được giới hạn tự động ở mức 100% mà không có nguy cơ quá tải</li>\r\n	<li>Bảo vệ hoàn toàn với các chức năng bảo vệ quá dòng, quá áp, dưới điện áp, quá nhiệt và các chức năng bảo vệ khác để đảm bảo an toàn và độ tin cậy khi vận hành</li>\r\n</ul>\r\n\r\n<p><strong>Chiến lược điều khiển nâng cao và thiết kế cấu trúc liên kết</strong></p>\r\n\r\n<ul>\r\n	<li>Cải tiến công nghệ phát hiện dựa trên lý thuyết công suất phản kháng tức thời, có thể phát hiện dòng sóng hài trong thời gian thực và tự động theo dõi các thay đổi sóng hài tải, với khả năng kiểm soát cao và phản hồi nhanh</li>\r\n	<li>Thuật toán khai thác sóng hài tách biệt theo pha duy nhất có thể đạt được điều khiển độc lập của từng pha khi tải không cân bằng trong ba pha. Khi đủ công suất, có thể chọn chức năng loại bỏ sự mất cân bằng</li>\r\n	<li>Bằng cách lọc cấu trúc liên kết LCL khi dòng điện hài được xuất ra, nhiễu sóng hài chuyển mạch IGBT tần số cao sẽ không được đưa vào và không có cộng hưởng đối với bất kỳ trở kháng nào của hệ thống lưới</li>\r\n</ul>\r\n\r\n<p><strong>Tích hợp cao, mô-đun, tuần tự hóa</strong></p>\r\n\r\n<ul>\r\n	<li>Thiết kế mô-đun, kích thước nhỏ, trọng lượng nhẹ, mật độ năng lượng cao, dễ dàng lắp đặt và bảo trì</li>\r\n	<li>Kết hợp các máy song song để đáp ứng các yêu cầu công suất khác nhau, nâng cao độ tin cậy và khả năng bảo trì của thiết bị trong khi vẫn đạt được sản xuất tiêu chuẩn hóa, tạo điều kiện thuận lợi đáng kể cho việc lắp đặt và bảo trì hệ thống</li>\r\n	<li>Thiết kế ống dẫn khí độc lập mô-đun đơn có thể cách ly bụi môi trường hiệu quả và nâng cao hiệu quả tản nhiệt</li>\r\n</ul>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/product/tlsh1.webp\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/product/tlsh2.webp\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/product/tlsh3.jpg\"></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/product/tlsh4.webp\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/product/tlsh5.jpg\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/product/tlsh6.webp\"></div>\r\n</div>\r\n</div>\r\n<script src=\"//cdn.public.flmngr.com/FLMNFLMN/widgets.js\"></script>\r\n', 'tlsh1_20231117114038.webp', 'resize_16353863349602t72oa_20240819092609.webp.webp', 0, 'Tủ lọc sóng hài tích cực là giải pháp mới giúp cải thiện chất lượng điện của nhà máy...', NULL, 1, 1, 0, 0, 1, 2, 1, 0, '2024-08-19', '2024-08-19', '', '', 0, ''),
(397, 1, 108, NULL, 0, 0, 'nham-xep-fd1001-ingco', 'Nhám xếp FD1001 INGCO', '', '', NULL, 11600, 11600, NULL, '<p>Th&ocirc;ng tin sản phẩm:</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>K&iacute;ch thước: 100mm*16mm - P40</p>\n\n<p>Ph&ugrave; hợp đ&aacute;nh b&oacute;ng th&eacute;p, gang v&agrave; tấm th&eacute;p.</p>\n\n<p>Đ&oacute;ng g&oacute;i bằng thẻ giấy</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', NULL, NULL, NULL, NULL, '<p>Th&ocirc;ng tin sản phẩm:</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>K&iacute;ch thước: 100mm*16mm - P40</p>\n\n<p>Ph&ugrave; hợp đ&aacute;nh b&oacute;ng th&eacute;p, gang v&agrave; tấm th&eacute;p.</p>\n\n<p>Đ&oacute;ng g&oacute;i bằng thẻ giấy</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', 'Nhám xếp FD1001 INGCO_20231229031415.jpg.webp', 'resize_Nhám xếp FD1001 INGCO_20231229031415.jpg.webp', 0, 'Thông tin sản phẩm:\nThương hiệu: INGCO\nXuất xứ: Trung Quốc\nKích thước: 100mm*16mm - P40\nPhù hợp đánh bóng thép, gang và tấm thép. \nĐóng gói bằng thẻ giấy\nTự hào là nơi phân phối sản phẩm chính hãng đến tay người tiêu dùng.', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-29', '2023-12-29', '', 'Nhám xếp FD1001 INGCO_20231229031415.jpg.webp', 0, 'https://shopee.vn/Nh%C3%A1m-x%E1%BA%BFp-FD1001-INGCO-i.319087615.5656374045?sp_atk=51cd1a72-c6db-430d-a51c-43a4f32510a1&xptdk=51cd1a72-c6db-430d-a51c-43a4f32510a1'),
(398, 1, 108, NULL, 0, 0, 'but-thu-dien-ingco-hsdt1408', 'Bút thử điện INGCO HSDT1408', '', '', NULL, 13000, 13000, NULL, '<p>Th&ocirc;ng tin sản phẩm</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>- Điện &aacute;p AC: 100-500V</p>\n\n<p>- K&iacute;ch thước: 3 x 140mm- 360/T</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', NULL, NULL, NULL, NULL, '<p>Th&ocirc;ng tin sản phẩm</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>- Điện &aacute;p AC: 100-500V</p>\n\n<p>- K&iacute;ch thước: 3 x 140mm- 360/T</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', '5a7dd24fb84441662f466828b2312972_20231229032144.webp', 'resize_5a7dd24fb84441662f466828b2312972_20231229032144.webp', 0, 'Thông tin sản phẩm\n\nThương hiệu: INGCO\n\nXuất xứ: Trung Quốc\n\n- Điện áp AC: 100-500V\n\n- Kích thước: 3 x 140mm- 360/T\n\nTự hào là nơi phân phối sản phẩm chính hãng đến tay người tiêu dùng.', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-29', '2023-12-29', '', '5a7dd24fb84441662f466828b2312972_20231229032144.webp', 0, 'https://shopee.vn/B%C3%BAt-th%E1%BB%AD-%C4%91i%E1%BB%87n-INGCO-HSDT1408-i.319087615.17682896425'),
(399, 1, 108, NULL, 0, 0, 'gang-tay-cao-su-hgvl04-xl', 'Găng tay cao su HGVL04-XL', '', '', NULL, 46700, 46700, NULL, '<p>Size: XL, d&ugrave;ng cho c&ocirc;ng nh&acirc;n l&agrave;m việc khu&acirc;ng v&aacute;c nặng, những vật mang sắc nhọn v&agrave; nhẹ.- 120/T</p>\n', NULL, NULL, NULL, NULL, '<p>Size: XL, d&ugrave;ng cho c&ocirc;ng nh&acirc;n l&agrave;m việc khu&acirc;ng v&aacute;c nặng, những vật mang sắc nhọn v&agrave; nhẹ.- 120/T</p>\n', 'Găng tay cao su HGVL04-XL_20231229032926.jpg.webp', 'resize_Găng tay cao su HGVL04-XL_20231229032926.jpg.webp', 0, 'Size: XL, dùng cho công nhân làm việc khuâng vác nặng, những vật mang sắc nhọn và nhẹ.- 120/T', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-29', '2023-12-29', '', 'Găng tay cao su HGVL04-XL_20231229032926.jpg.webp', 0, ''),
(400, 1, 108, NULL, 0, 0, 'sung-thoi-khi-80mm-ingco-abg081-3', 'Súng thổi khí 80mm INGCO ABG081-3', '', '', NULL, 74000, 74000, NULL, '<p>S&uacute;ng thổi kh&iacute; INGCO ABG031-3 l&agrave; dụng cụ kh&ocirc;ng thể thiếu trong qu&aacute; tr&igrave;nh l&agrave;m vi&ecirc;c của m&aacute;y n&eacute;n kh&iacute;, m&aacute;y thổi...... l&agrave; sản phẩm ti&ecirc;n tiến c&oacute; chất liệu cao cấp chống rỉ s&eacute;t sau mỗi lần l&agrave;m việc, chịu được lực tốt, chịu được va đập, sản phẩm thường được d&ugrave;ng ở những tiệm bảo h&agrave;nh xe hay được d&ugrave;ng để vệ sinh thổi bụi nh&agrave; cửa, l&agrave;m sạch c&aacute;c chỗ bị bụi b&aacute;m m&agrave; kh&oacute; c&oacute; thể sử dụng bằng phương thủ c&ocirc;ng, kh&aacute; bền bỉ v&agrave; c&oacute; tuổi thọ l&acirc;u d&agrave;i sau mỗi lần sử dụng.</p>\n', NULL, NULL, NULL, NULL, '<p>S&uacute;ng thổi kh&iacute; INGCO ABG031-3 l&agrave; dụng cụ kh&ocirc;ng thể thiếu trong qu&aacute; tr&igrave;nh l&agrave;m vi&ecirc;c của m&aacute;y n&eacute;n kh&iacute;, m&aacute;y thổi...... l&agrave; sản phẩm ti&ecirc;n tiến c&oacute; chất liệu cao cấp chống rỉ s&eacute;t sau mỗi lần l&agrave;m việc, chịu được lực tốt, chịu được va đập, sản phẩm thường được d&ugrave;ng ở những tiệm bảo h&agrave;nh xe hay được d&ugrave;ng để vệ sinh thổi bụi nh&agrave; cửa, l&agrave;m sạch c&aacute;c chỗ bị bụi b&aacute;m m&agrave; kh&oacute; c&oacute; thể sử dụng bằng phương thủ c&ocirc;ng, kh&aacute; bền bỉ v&agrave; c&oacute; tuổi thọ l&acirc;u d&agrave;i sau mỗi lần sử dụng.</p>\n\n<p>Th&ocirc;ng tin sản phẩm</p>\n\n<p>- Thương hiệu: INGCO</p>\n\n<p>- Xuất xứ: Trung Quốc</p>\n\n<p>- S&uacute;ng thổi kh&iacute; ABG081-3</p>\n\n<p>- K&iacute;ch thước v&ograve;i phun: 80mm</p>\n\n<p>- Khớp nối kiểu Nhật Bản</p>\n\n<p>- Đ&oacute;ng g&oacute;i trong vĩ nhựa</p>\n\n<p>- TL: 0.4 kg</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n\n<p>&nbsp;</p>\n', 'ABG081-3_20231229033404.jpg.webp', 'resize_ABG081-3_20231229033404.jpg.webp', 0, 'Súng thổi khí INGCO ABG031-3 là dụng cụ không thể thiếu trong quá trình làm viêc của máy nén khí, máy thổi...... là sản phẩm tiên tiến có chất liệu cao cấp chống rỉ sét sau mỗi lần làm việc, chịu được lực tốt, chịu được va đập, sản phẩm thường được dùng ở những tiệm bảo hành xe hay được dùng để vệ sinh thổi bụi nhà cửa, làm sạch các chỗ bị bụi bám mà khó có thể sử dụng bằng phương thủ công, khá bền bỉ và có tuổi thọ lâu dài sau mỗi lần sử dụng.', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-29', '2023-12-29', '', 'ABG081-3_20231229033404.jpg.webp', 0, 'https://shopee.vn/-CH%C3%8DNH-H%C3%83NG-S%C3%BAng-th%E1%BB%95i-kh%C3%AD-80mm-INGCO-ABG081-3-i.319087615.21078905026'),
(401, 1, 109, NULL, 0, 0, 'pin-lithium-ion-20v-fbli20011', 'PIN LITHIUM-ION 20V FBLI20011', '', '', NULL, 380000, 380000, NULL, '<p>Điện thế: 20V, Dung lượng pin Lithium -ion: 2.0Ah, pin c&oacute; đ&egrave;n LED hiển thị dung lượng của pin, Ph&ugrave; hợp cho nhiều loại m&aacute;y Ingco 20V, đ&oacute;ng g&oacute;i trong hộp giấy. TL: 0.4 kg</p>\n', NULL, NULL, NULL, NULL, '<p>Điện thế: 20V</p>\n\n<p>Dung lượng pin Lithium -ion: 2.0Ah, pin c&oacute; đ&egrave;n LED hiển thị dung lượng của pin</p>\n\n<p>Ph&ugrave; hợp cho nhiều loại m&aacute;y Ingco 20V, đ&oacute;ng g&oacute;i trong hộp giấy. TL: 0.4 kg</p>\n', 'p_68649_INGCO-FBLI20011_20231230065507.jpg.webp', 'resize_p_68649_INGCO-FBLI20011_20231230065507.jpg.webp', 0, 'Điện thế: 20V, Dung lượng pin Lithium -ion: 2.0Ah, pin có đèn LED hiển thị dung lượng của pin, Phù hợp cho nhiều loại máy Ingco 20V, đóng gói trong hộp giấy. TL: 0.4 kg', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-30', '2023-12-30', '', 'p_68649_INGCO-FBLI20011_20231230065507.jpg.webp', 0, ''),
(402, 1, 109, NULL, 0, 0, 'mui-khoan-gach-va-kieng-dbg1111001-ingco', 'Mũi khoan gạch và kiếng DBG1111001 INGCO', '', '', NULL, 51600, 51600, NULL, '<p>Th&ocirc;ng số kĩ thuật</p>\n\n<p>M&atilde; sản phẩm: DBG111100</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>Size: 10X90mm</p>\n\n<p>Đ&oacute;ng g&oacute;i trong ống nhựa</p>\n', NULL, NULL, NULL, NULL, '<p>Th&ocirc;ng số kĩ thuật</p>\n\n<p>M&atilde; sản phẩm: DBG111100</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>Size: 10X90mm</p>\n\n<p>Đ&oacute;ng g&oacute;i trong ống nhựa</p>\n', 'ingco_dbg1111001_1_20231230070536.webp', 'resize_ingco_dbg1111001_1_20231230070536.webp', 0, 'Thông số kĩ thuật\nMã sản phẩm: DBG111100\nThương hiệu: INGCO\nXuất xứ: Trung Quốc\nSize: 10X90mm\nĐóng gói trong ống nhựa', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-30', '2023-12-30', '', 'ingco_dbg1111001_1_20231230070536.webp', 0, 'https://shopee.vn/M%C5%A9i-khoan-g%E1%BA%A1ch-v%C3%A0-ki%E1%BA%BFng-DBG1111001-INGCO-i.319087615.7457898795?sp_atk=4b2bf9ba-7261-46b4-8c4c-4b46f93410c3&xptdk=4b2bf9ba-7261-46b4-8c4c-4b46f93410c3'),
(403, 1, 109, NULL, 0, 0, 'bo-12-mui-khoan-kim-loai-hss-ingco-akdb1125', 'Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125', '', '', NULL, 63200, 63200, NULL, '<p>2-8mm Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125</p>\n\n<p>Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125 được thiết kế với đầu mũi nhọn t&iacute;nh tế gi&uacute;p cho việc khoan được thuận tiện v&agrave; trơn trư hơn m&agrave; kh&ocirc;ng bị chạy khi đặt v&agrave;o vị tr&iacute; khoan v&agrave; giảm độ rung khi khoan, được thiết kế k&egrave;m theo với m&aacute;y khoan tay, được ứng dụng nhiều trong c&aacute;c c&ocirc;ng tr&igrave;nh x&acirc;y dựng, c&aacute;c nh&agrave; m&aacute;y, cơ kh&iacute;...d&ugrave;ng để khoan qua c&aacute;c sản phẩm được l&agrave;m bằng sắt th&eacute;p một c&aacute;ch dễ d&agrave;ng v&agrave; thuận tiện cho người sử dụng, với chất liệu được l&agrave;m bằng hợp kim cao cấp c&oacute; khả năng chịu được nhiệt, chịu được lực t&aacute;c động lớn, chống rỉ s&eacute;t, c&oacute; thể l&agrave;m việc ở c&aacute;c m&ocirc;i trường khắc nhiệt một c&aacute;ch hiệu quả</p>\n', NULL, NULL, NULL, NULL, '<p>2-8mm Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125</p>\n\n<p>Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125 được thiết kế với đầu mũi nhọn t&iacute;nh tế gi&uacute;p cho việc khoan được thuận tiện v&agrave; trơn trư hơn m&agrave; kh&ocirc;ng bị chạy khi đặt v&agrave;o vị tr&iacute; khoan v&agrave; giảm độ rung khi khoan, được thiết kế k&egrave;m theo với m&aacute;y khoan tay, được ứng dụng nhiều trong c&aacute;c c&ocirc;ng tr&igrave;nh x&acirc;y dựng, c&aacute;c nh&agrave; m&aacute;y, cơ kh&iacute;...d&ugrave;ng để khoan qua c&aacute;c sản phẩm được l&agrave;m bằng sắt th&eacute;p một c&aacute;ch dễ d&agrave;ng v&agrave; thuận tiện cho người sử dụng, với chất liệu được l&agrave;m bằng hợp kim cao cấp c&oacute; khả năng chịu được nhiệt, chịu được lực t&aacute;c động lớn, chống rỉ s&eacute;t, c&oacute; thể l&agrave;m việc ở c&aacute;c m&ocirc;i trường khắc nhiệt một c&aacute;ch hiệu quả</p>\n\n<p>&nbsp;</p>\n\n<p>Th&ocirc;ng số kĩ thuật</p>\n\n<p>- M&atilde; sản phẩm: KDB1125</p>\n\n<p>- Thương hiệu: INGCO</p>\n\n<p>- Xuất xứ: Trung Quốc</p>\n\n<p>- Gồm c&aacute;c Size: 2, 2.5, 3, 3.5, 4, 4.5, 5, 5.5, 6, 6.5, 7, 8mm</p>\n\n<p>- Đ&oacute;ng g&oacute;i trong vỈ nhựa</p>\n\n<p>- Bảo h&agrave;nh: 6 th&aacute;ng</p>\n', 'Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125_20231230092513.webp', 'resize_Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125_20231230092513.webp', 0, 'Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125 được thiết kế với đầu mũi nhọn tính tế giúp cho việc khoan được thuận tiện và trơn trư hơn mà không bị chạy khi đặt vào vị trí khoan và giảm độ rung khi khoan, được thiết kế kèm theo với máy khoan tay, được ứng dụng nhiều trong các công trình xây dựng, các nhà máy, cơ khí...dùng để khoan qua các sản phẩm được làm bằng sắt thép một cách dễ dàng và thuận tiện cho người sử dụng, với chất liệu được làm bằng hợp kim cao cấp có khả năng chịu được nhiệt, chịu được lực tác động lớn, chống rỉ sét, có thể làm việc ở các môi trường khắc nhiệt một cách hiệu quả', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-30', '2023-12-30', '', 'Bộ 12 mũi khoan kim loại HSS INGCO AKDB1125_20231230092513.webp', 0, 'https://shopee.vn/B%E1%BB%99-12-m%C5%A9i-khoan-kim-lo%E1%BA%A1i-HSS-INGCO-AKDB1125-CHI%CC%81NH-HA%CC%83NG-i.319087615.23528497313'),
(404, 1, 109, NULL, 0, 0, 'mui-khoan-kim-loai-m2-hss-4-dbt1110401', 'Mũi khoan kim loại M2 HSS 4 - DBT1110401', '', '', NULL, 11600, 11600, NULL, '<p>Đường k&iacute;nh mũi: 4.0mm, 10 mũi/ hộp nhựa, tổng chiều d&agrave;i mũi: 75mm, chiều d&agrave;i sử dụng: 43mm</p>\n', NULL, NULL, NULL, NULL, '<p>Đường k&iacute;nh mũi: 4.0mm, 10 mũi/ hộp nhựa, tổng chiều d&agrave;i mũi: 75mm, chiều d&agrave;i sử dụng: 43mm</p>\n', 'DBT1110401_20231230100009.webp', 'resize_DBT1110401_20231230100009.webp', 0, 'Đường kính mũi: 4.0mm, 10 mũi/ hộp nhựa, tổng chiều dài mũi: 75mm, chiều dài sử dụng: 43mm', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-30', '2023-12-30', '', 'DBT1110401_20231230100009.webp', 0, ''),
(405, 1, 109, NULL, 0, 0, 'cua-canh-cam-tay-luoi-thang-hps3008', 'Cưa cành cầm tay lưỡi thẳng HPS3008', '', '', NULL, 159800, 159800, NULL, '<p>Chất lượng tốt như h&agrave;ng STANLEY, Size:12&quot;/300mm, Chất liệu: SK5 Taiwan, 7 răng cưa/1 inch, răng cưa xử l&yacute; qua nhiệt, cắt nhanh v&agrave; thời gian sử dụng l&acirc;u d&agrave;i.- 60/T</p>\n', NULL, NULL, NULL, NULL, '<p>Chất lượng tốt như h&agrave;ng STANLEY, Size:12&quot;/300mm, Chất liệu: SK5 Taiwan, 7 răng cưa/1 inch, răng cưa xử l&yacute; qua nhiệt, cắt nhanh v&agrave; thời gian sử dụng l&acirc;u d&agrave;i.- 60/T</p>\n', 'HPS3008_20231230100413.webp', 'resize_HPS3008_20231230100413.webp', 0, 'Chất lượng tốt như hàng STANLEY, Size:12\"/300mm, Chất liệu: SK5 Taiwan, 7 răng cưa/1 inch, răng cưa xử lý qua nhiệt, cắt nhanh và thời gian sử dụng lâu dài.- 60/T', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-30', '2023-12-30', '', 'HPS3008_20231230100413.webp', 0, ''),
(406, 1, 108, NULL, 0, 0, 'tuoc-no-vit-2-dau-135mm-ingco-akisd0203', 'Tuốc nơ vít 2 đầu 135mm INGCO AKISD0203', '', '', NULL, 27200, 27200, NULL, '<p>Tuốc nơ v&iacute;t 2 đầu INGCO AKISD0203 gồm 2 đầu v&iacute;t: 1 đầu bake v&agrave; 1 đầu dẹp, đồ nghề cầm tay n&agrave;y hay được sử dụng để vặn mở đai ốc v&iacute;t, c&oacute; t&iacute;nh ứng dụng cao trong ng&agrave;nh x&acirc;y dựng, cơ kh&iacute;, sửa chữa lắp đặt... Cũng như c&aacute;c loại mũi v&iacute;t kh&aacute;c th&igrave; phần mũi v&iacute;t được l&agrave;m từ th&eacute;p CR-V n&ecirc;n kh&ocirc;ng bị to&eacute;t đầu khi vặn/mở mạnh, phần tay cầm th&igrave; nằm gọn trong l&ograve;ng b&agrave;n tay được bọc th&ecirc;m 1 lớp nhựa, tạo cảm gi&aacute;c &ecirc;m &aacute;i khi cầm nắm v&agrave; hạn chế rủi ro trơn trượt khi chẳng may tay bị ướt.</p>\n', NULL, NULL, NULL, NULL, '<p>Tuốc nơ v&iacute;t 2 đầu INGCO AKISD0203 gồm 2 đầu v&iacute;t: 1 đầu bake v&agrave; 1 đầu dẹp, đồ nghề cầm tay n&agrave;y hay được sử dụng để vặn mở đai ốc v&iacute;t, c&oacute; t&iacute;nh ứng dụng cao trong ng&agrave;nh x&acirc;y dựng, cơ kh&iacute;, sửa chữa lắp đặt... Cũng như c&aacute;c loại mũi v&iacute;t kh&aacute;c th&igrave; phần mũi v&iacute;t được l&agrave;m từ th&eacute;p CR-V n&ecirc;n kh&ocirc;ng bị to&eacute;t đầu khi vặn/mở mạnh, phần tay cầm th&igrave; nằm gọn trong l&ograve;ng b&agrave;n tay được bọc th&ecirc;m 1 lớp nhựa, tạo cảm gi&aacute;c &ecirc;m &aacute;i khi cầm nắm v&agrave; hạn chế rủi ro trơn trượt khi chẳng may tay bị ướt.</p>\n\n<p>&nbsp;</p>\n\n<p>Th&ocirc;ng số kĩ thuật</p>\n\n<p>- M&atilde; sản phẩm: AKISD0203</p>\n\n<p>- Thương hiệu: Ingco</p>\n\n<p>- Xuất xứ: Trung Quốc</p>\n\n<p>- K&iacute;ch thước: 6.3X75MM, PH2+SL6</p>\n\n<p>- Chất liệu: th&eacute;p CR-V</p>\n\n<p>- Với 1 tay cầm ho&aacute;n đổi dễ d&agrave;ng</p>\n\n<p>- Trọng lượng: 200g</p>\n', 'AKISD0203_20231230101807.webp', 'resize_AKISD0203_20231230101807.webp', 0, 'Tuốc nơ vít 2 đầu INGCO AKISD0203 gồm 2 đầu vít: 1 đầu bake và 1 đầu dẹp, đồ nghề cầm tay này hay được sử dụng để vặn mở đai ốc vít, có tính ứng dụng cao trong ngành xây dựng, cơ khí, sửa chữa lắp đặt... Cũng như các loại mũi vít khác thì phần mũi vít được làm từ thép CR-V nên không bị toét đầu khi vặn/mở mạnh, phần tay cầm thì nằm gọn trong lòng bàn tay được bọc thêm 1 lớp nhựa, tạo cảm giác êm ái khi cầm nắm và hạn chế rủi ro trơn trượt khi chẳng may tay bị ướt.', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-30', '2023-12-30', '', 'AKISD0203_20231230101807.webp', 0, 'https://shopee.vn/-CH%C3%8DNH-H%C3%83NG-Tu%E1%BB%91c-n%C6%A1-v%C3%ADt-2-%C4%91%E1%BA%A7u-135mm-INGCO-AKISD0203-i.319087615.22083097782'),
