(409, 1, 109, NULL, 0, 0, 'mui-khoan-kim-loai-m2-hss-dbt1110601', 'Mũi khoan kim loại M2 HSS DBT1110601', '', '', NULL, 24200, 24200, NULL, '<p>Th&ocirc;ng tin sản phẩm:<br />\nThương hiệu: INGCO<br />\nXuất xứ: Trung Quốc<br />\nMũi khoan kim loại M2 HSS DBT1110601&nbsp;<br />\nĐường k&iacute;nh mũi: 6.0mm<br />\nTổng chiều d&agrave;i mũi: 93mm<br />\nChiều d&agrave;i sử dụng: 57mm<br />\nĐ&oacute;ng g&oacute;i trong ống nhựa</p>\n', NULL, NULL, NULL, NULL, '<p>Th&ocirc;ng tin sản phẩm:<br />\nThương hiệu: INGCO<br />\nXuất xứ: Trung Quốc<br />\nMũi khoan kim loại M2 HSS DBT1110601&nbsp;<br />\nĐường k&iacute;nh mũi: 6.0mm<br />\nTổng chiều d&agrave;i mũi: 93mm<br />\nChiều d&agrave;i sử dụng: 57mm<br />\nĐ&oacute;ng g&oacute;i trong ống nhựa</p>\n', 'DBT1110601_20231230104055.webp', 'resize_DBT1110601_20231230104055.webp', 0, 'Thông tin sản phẩm:\nThương hiệu: INGCO\nXuất xứ: Trung Quốc\nMũi khoan kim loại M2 HSS DBT1110601 \nĐường kính mũi: 6.0mm\nTổng chiều dài mũi: 93mm\nChiều dài sử dụng: 57mm\nĐóng gói trong ống nhựa', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2023-12-30', '2023-12-30', '', 'DBT1110601_20231230104055.webp', 0, 'https://shopee.vn/M%C5%A9i-khoan-kim-lo%E1%BA%A1i-M2-HSS-DBT1110601-INGCO-i.319087615.7256487413'),
(410, 1, 109, NULL, 0, 0, 'mui-khoan-kim-loai-m2-hss-4-5-dbt1110451', 'Mũi khoan kim loại M2 HSS 4.5 - DBT1110451', '', '', NULL, 13700, 13700, NULL, '<p>Đường k&iacute;nh mũi: 4.5mm, 10 mũi/ hộp nhựa, tổng chiều d&agrave;i mũi: 80mm, chiều d&agrave;i sử dụng: 47mm</p>\n', NULL, NULL, NULL, NULL, '<p>Đường k&iacute;nh mũi: 4.5mm, 10 mũi/ hộp nhựa, tổng chiều d&agrave;i mũi: 80mm, chiều d&agrave;i sử dụng: 47mm</p>\n', 'DBT1110451_20240104021130.webp', 'resize_DBT1110451_20240104021130.webp', 0, 'Đường kính mũi: 4.5mm, 10 mũi/ hộp nhựa, tổng chiều dài mũi: 80mm, chiều dài sử dụng: 47mm', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'DBT1110451_20240104021130.webp', 0, ''),
(411, 1, 108, NULL, 0, 0, 'bo-la-ong-dong-hpft71', 'Bộ lã ống đồng HPFT71', '', '', NULL, 191300, 191300, NULL, '<p>Đường k&iacute;nh ống: 5mm/6mm/8mm/10mm/12mm/14mm/16mm, cảo xoay được mạ Cr, khung th&eacute;p c&oacute; độ cứng cao, chịu lực tốt- 24/T</p>\n', NULL, NULL, NULL, NULL, '<p>Đường k&iacute;nh ống: 5mm/6mm/8mm/10mm/12mm/14mm/16mm, cảo xoay được mạ Cr, khung th&eacute;p c&oacute; độ cứng cao, chịu lực tốt- 24/T</p>\n', '5-16mm-bo-la-ong-dong-ingco-hpft71_20240104022456.webp', 'resize_5-16mm-bo-la-ong-dong-ingco-hpft71_20240104022456.webp', 0, 'Đường kính ống: 5mm/6mm/8mm/10mm/12mm/14mm/16mm, cảo xoay được mạ Cr, khung thép có độ cứng cao, chịu lực tốt- 24/T', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', '5-16mm-bo-la-ong-dong-ingco-hpft71_20240104022456.webp', 0, ''),
(412, 1, 108, NULL, 0, 0, 'kem-bam-cos-day-dien-0-25-10mm3-hrcpg05210', 'Kềm bấm cos dây điện 0.25-10mm3 HRCPG05210', '', '', NULL, 313000, 313000, NULL, '<p>Phạm vi bấm: 0,25-10mm&sup2;<br />\nĐối với thiết bị đầu cuối dạng ống v&agrave; c&aacute;ch điện AWG: 23-7, Chiều d&agrave;i: 6 &quot;. Tay cầm thiết kế độc đ&aacute;o.</p>\n\n<p>Lực bấm c&oacute; thể được điều chỉnh, ph&ugrave; hợp với c&aacute;c thiết bị đầu cuối kh&aacute;c nhau</p>\n', NULL, NULL, NULL, NULL, '<p>Phạm vi bấm: 0,25-10mm&sup2;<br />\nĐối với thiết bị đầu cuối dạng ống v&agrave; c&aacute;ch điện AWG: 23-7, Chiều d&agrave;i: 6 &quot;. Tay cầm thiết kế độc đ&aacute;o.</p>\n\n<p>Lực bấm c&oacute; thể được điều chỉnh, ph&ugrave; hợp với c&aacute;c thiết bị đầu cuối kh&aacute;c nhau</p>\n', 'INGCO-HRCPG05210_20240104022800.webp', 'resize_INGCO-HRCPG05210_20240104022800.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'INGCO-HRCPG05210_20240104022800.webp', 0, '');
