(413, 1, 108, NULL, 0, 0, 'thuoc-thuy-co-nam-cham-hut-hsl38060m-ingco', 'Thước thủy có nam châm hút HSL38060M INGCO', '', '', NULL, 276100, 276100, NULL, '<p>Th&ocirc;ng tin sản phẩm</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>Chiều d&agrave;i: 60 cm</p>\n\n<p>Độ d&agrave;y thanh nh&ocirc;m: 1.5mm, 3 nam ch&acirc;m h&uacute;t cực mạnh- 20/T</p>\n\n<p>Thước thủy(k&egrave;m theo nam ch&acirc;m h&uacute;t) INGCO HSL38060M được thiết kế với mục đ&iacute;ch đo bằng phẳng c&aacute;c kề mặt d&ugrave; cong hay m&eacute;o một c&aacute;ch ch&iacute;nh x&aacute;c, thường được d&ugrave;ng ở trong c&aacute;c c&ocirc;ng tr&igrave;nh x&acirc;y dựng, c&aacute;c nh&agrave; m&aacute;y...</p>\n\n<p>===============================================</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', NULL, NULL, NULL, NULL, '<p>Th&ocirc;ng tin sản phẩm</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>Chiều d&agrave;i: 60 cm</p>\n\n<p>Độ d&agrave;y thanh nh&ocirc;m: 1.5mm, 3 nam ch&acirc;m h&uacute;t cực mạnh- 20/T</p>\n\n<p>Thước thủy(k&egrave;m theo nam ch&acirc;m h&uacute;t) INGCO HSL38060M được thiết kế với mục đ&iacute;ch đo bằng phẳng c&aacute;c kề mặt d&ugrave; cong hay m&eacute;o một c&aacute;ch ch&iacute;nh x&aacute;c, thường được d&ugrave;ng ở trong c&aacute;c c&ocirc;ng tr&igrave;nh x&acirc;y dựng, c&aacute;c nh&agrave; m&aacute;y...</p>\n\n<p>===============================================</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', 'ingco-hsl38-3_20240104023234.webp', 'resize_ingco-hsl38-3_20240104023234.webp', 0, 'Thông tin sản phẩm\nThương hiệu: INGCO\nXuất xứ: Trung Quốc\nChiều dài: 60 cm\nĐộ dày thanh nhôm: 1.5mm, 3 nam châm hút cực mạnh- 20/T\nThước thủy(kèm theo nam châm hút) INGCO HSL38060M được thiết kế với mục đích đo bằng phẳng các kề mặt dù cong hay méo một cách chính xác, thường được dùng ở trong các  công trình xây dựng, các nhà máy...\n===============================================\nTự hào là nơi phân phối sản phẩm chính hãng đến tay người tiêu dùng.', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'ingco-hsl38-3_20240104023234.webp', 0, ''),
(414, 1, 108, NULL, 0, 0, 'bo-mo-let-da-nang-hbws110808-ingco', 'Bộ mỏ lết đa năng HBWS110808 INGCO', '', '', NULL, 163000, 163000, NULL, '<p>Th&ocirc;ng tin sản phẩm</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>Gồm 1 mỏ lết hai miệng Size: 9-14mm &amp; 15-22mm</p>\n\n<p>1 mỏ lết 1 đầu miệng size: 23-32mm.</p>\n\n<p>Mạ crom. Tay cầm hai m&agrave;u- 20/T</p>\n\n<p>Phần đầu của mỏ lết được thiết kế với c&aacute;c chi tiết ch&iacute;nh x&aacute;c, đảm bảo cho người sử dụng thao t&aacute;c dễ d&agrave;ng v&agrave; kh&ocirc;ng l&agrave;m biến dạng c&aacute;c bu l&ocirc;ng cần xiết.</p>\n\n<p>===============================================</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', NULL, NULL, NULL, NULL, '<p>Th&ocirc;ng tin sản phẩm</p>\n\n<p>Thương hiệu: INGCO</p>\n\n<p>Xuất xứ: Trung Quốc</p>\n\n<p>Gồm 1 mỏ lết hai miệng Size: 9-14mm &amp; 15-22mm</p>\n\n<p>1 mỏ lết 1 đầu miệng size: 23-32mm.</p>\n\n<p>Mạ crom. Tay cầm hai m&agrave;u- 20/T</p>\n\n<p>Phần đầu của mỏ lết được thiết kế với c&aacute;c chi tiết ch&iacute;nh x&aacute;c, đảm bảo cho người sử dụng thao t&aacute;c dễ d&agrave;ng v&agrave; kh&ocirc;ng l&agrave;m biến dạng c&aacute;c bu l&ocirc;ng cần xiết.</p>\n\n<p>===============================================</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', 'vn-11134207-7r98o-lmsajkqhot7j48_tn_20240104023727.webp', 'resize_vn-11134207-7r98o-lmsajkqhot7j48_tn_20240104023727.webp', 0, 'Thông tin sản phẩm\nThương hiệu: INGCO\nXuất xứ: Trung Quốc\nGồm 1 mỏ lết hai miệng Size: 9-14mm & 15-22mm\n1 mỏ lết 1 đầu miệng size: 23-32mm. \nMạ crom. Tay cầm hai màu- 20/T\nPhần đầu của mỏ lết được thiết kế với các chi tiết chính xác, đảm bảo cho người sử dụng thao tác dễ dàng và không làm biến dạng các bu lông cần xiết.\n===============================================\nTự hào là nơi phân phối sản phẩm chính hãng đến tay người tiêu dùng.', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'vn-11134207-7r98o-lmsajkqhot7j48_tn_20240104023727.webp', 0, 'https://shopee.vn/B%E1%BB%99-m%E1%BB%8F-l%E1%BA%BFt-%C4%91a-n%C4%83ng-HBWS110808-INGCO-i.319087615.7857304880'),
(415, 1, 108, NULL, 0, 0, 'co-le-mieng-vong-2-chieu-15-hcspar151', 'Cờ lê miệng vòng 2 chiều 15 HCSPAR151', '', '', NULL, 85900, 85900, NULL, '<p>Size: 15mm, chiều d&agrave;i: 200 mm, chất liệu: Cr-V, mạ th&eacute;p Chrome, sơn b&oacute;ng mờ.- 60/T</p>\n', NULL, NULL, NULL, NULL, '<p>Size: 15mm, chiều d&agrave;i: 200 mm, chất liệu: Cr-V, mạ th&eacute;p Chrome, sơn b&oacute;ng mờ.- 60/T</p>\n', 'hcspar151-1_20240104024340.webp', 'resize_hcspar151-1_20240104024340.webp', 0, 'Size: 15mm, chiều dài: 200 mm, chất liệu: Cr-V, mạ thép Chrome, sơn bóng mờ.- 60/T', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'hcspar151-1_20240104024340.webp', 0, ''),
(416, 1, 108, NULL, 0, 0, 'tua-vit-dep-dong-xuyen-hgts288150', 'Tua vít dẹp đóng xuyên HGTS288150', '', '', NULL, 72800, 72800, NULL, '<p>Chất liệu th&eacute;p c&ocirc;ng nghiệp S2. đu&ocirc;i lục gi&aacute;c : 8mm, bề rộng đầu v&iacute;t: 8.0 mm, Chiều d&agrave;i: 150mm- 72/T</p>\n', NULL, NULL, NULL, NULL, '<p>Chất liệu th&eacute;p c&ocirc;ng nghiệp S2. đu&ocirc;i lục gi&aacute;c : 8mm, bề rộng đầu v&iacute;t: 8.0 mm, Chiều d&agrave;i: 150mm- 72/T</p>\n', 'tournevis-a-tete-fendue-hgts288200_20240104024630.webp', 'resize_tournevis-a-tete-fendue-hgts288200_20240104024630.webp', 0, 'Chất liệu thép công nghiệp S2. đuôi lục giác : 8mm, bề rộng đầu vít: 8.0 mm, Chiều dài: 150mm- 72/T', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'tournevis-a-tete-fendue-hgts288200_20240104024630.webp', 0, ''),
(417, 1, 108, NULL, 0, 0, 'tua-vit-dep-hs285075', 'Tua vít dẹp HS285075', '', '', NULL, 18500, 18500, NULL, '<p>Chất liệu th&eacute;p Cr-V, đu&ocirc;i tr&ograve;n, bề rộng đầu tua v&iacute;t: 5.5 mm, Đường k&iacute;nh trục tua v&iacute;t: 5.0 mm, Chiều d&agrave;i: 75mm.- 144/T</p>\n', NULL, NULL, NULL, NULL, '<p>Chất liệu th&eacute;p Cr-V, đu&ocirc;i tr&ograve;n, bề rộng đầu tua v&iacute;t: 5.5 mm, Đường k&iacute;nh trục tua v&iacute;t: 5.0 mm, Chiều d&agrave;i: 75mm.- 144/T</p>\n', 'HS285075_20240104030855.webp', 'resize_HS285075_20240104030855.webp', 0, '', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'HS285075_20240104030855.webp', 0, ''),
(418, 1, 108, NULL, 0, 0, 'mui-khoan-kim-loai-m2-hss-5-dbt1110501', 'Mũi khoan kim loại M2 HSS 5 - DBT1110501', '', '', NULL, 15800, 15800, NULL, '<p>Đường k&iacute;nh mũi: 5.0mm, 10 mũi/ hộp nhựa, tổng chiều d&agrave;i mũi: 86mm, chiều d&agrave;i sử dụng: 52mm</p>\n', NULL, NULL, NULL, NULL, '<p>Đường k&iacute;nh mũi: 5.0mm, 10 mũi/ hộp nhựa, tổng chiều d&agrave;i mũi: 86mm, chiều d&agrave;i sử dụng: 52mm</p>\n', 'muikhoankimloaiM2HSS-2(3)_20240104031322.webp', 'resize_muikhoankimloaiM2HSS-2(3)_20240104031322.webp', 0, 'Đường kính mũi: 5.0mm, 10 mũi/ hộp nhựa, tổng chiều dài mũi: 86mm, chiều dài sử dụng: 52mm', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'muikhoankimloaiM2HSS-2(3)_20240104031322.webp', 0, ''),
(419, 1, 109, NULL, 0, 0, 'pin-s12v-fbli12152', 'Pin S12V - FBLI12152', '', '', NULL, 266300, 266300, NULL, '<p><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dung lượng pin:12V<br />\n. Pin Lithium-Ion 1.5Ah<br />\nMột pin sử dụng cho tất cả c&aacute;c d&ograve;ng sản phẩm S12.</span></p>\n', NULL, NULL, NULL, NULL, '<p>Dung lượng pin:12V<br />\n. Pin Lithium-Ion 1.5Ah<br />\nMột pin sử dụng cho tất cả c&aacute;c d&ograve;ng sản phẩm S12.</p>\n', 'FBLI12152_20240104032706.webp', 'resize_FBLI12152_20240104032706.webp', 0, 'Dung lượng pin:12V\n. Pin Lithium-Ion 1.5Ah\nMột pin sử dụng cho tất cả các dòng sản phẩm S12.', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'FBLI12152_20240104032706.webp', 0, ''),
(420, 1, 108, NULL, 0, 0, 'tua-vit-dep-dong-xuyen-hgts286150', 'Tua vít dẹp đóng xuyên HGTS286150', '', '', NULL, 54300, 54300, NULL, '<p>Chất liệu th&eacute;p c&ocirc;ng nghiệp S2. đu&ocirc;i lục gi&aacute;c : 6mm, bề rộng đầu v&iacute;t: 6.5 mm, Chiều d&agrave;i: 150mm- 144/T</p>\n', NULL, NULL, NULL, NULL, '<p>Chất liệu th&eacute;p c&ocirc;ng nghiệp S2. đu&ocirc;i lục gi&aacute;c : 6mm, bề rộng đầu v&iacute;t: 6.5 mm, Chiều d&agrave;i: 150mm- 144/T</p>\n', 'tua-vit-dep-dong-xuyen-ingco-hgts286150-1611905894_20240104033247.webp', 'resize_tua-vit-dep-dong-xuyen-ingco-hgts286150-1611905894_20240104033247.webp', 0, 'Chất liệu thép công nghiệp S2. đuôi lục giác : 6mm, bề rộng đầu vít: 6.5 mm, Chiều dài: 150mm- 144/T', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'tua-vit-dep-dong-xuyen-ingco-hgts286150-1611905894_20240104033247.webp', 0, ''),
(421, 1, 110, NULL, 0, 0, 'may-mai-hai-dau-bg61502', 'Máy mài hai đầu BG61502', '', '', NULL, 655800, 655800, NULL, '<p>M&aacute;y m&agrave;i để b&agrave;n 2 đ&aacute; INGCO BG61502 sử dụng đ&aacute; c&oacute; đường k&iacute;nh 150mm (6 inch), kết hợp với c&ocirc;ng suất 150w gi&uacute;p qu&aacute; tr&igrave;nh l&agrave;m việc nhanh v&agrave; hiệu quả hơn. M&aacute;y m&agrave;i hai đ&aacute; để b&agrave;n INGCO BG61502 l&agrave; sản phẩm chất lượng được nhiều kh&aacute;ch h&agrave;ng đ&aacute;nh gi&aacute; cao về mẫu m&atilde;, thiết kế cũng như gi&aacute; th&agrave;nh hợp l&yacute;.</p>\n\n<p>&nbsp;</p>\n\n<p>Th&ocirc;ng số kỹ thuật:</p>\n\n<p>- Điện thế: 220-240V~50-60Hz;</p>\n\n<p>- C&ocirc;ng suất: 150 W,</p>\n\n<p>- Tốc độ kh&ocirc;ng tải: 2950 v/p;</p>\n\n<p>- K&iacute;ch thước đ&aacute; m&agrave;i: 150mm;</p>\n\n<p>- K&egrave;m theo 1 bộ nắp che chắn v&agrave; 1 hộp dụng cụ.</p>\n\n<p>===============================================</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', NULL, NULL, NULL, NULL, '<p>M&aacute;y m&agrave;i để b&agrave;n 2 đ&aacute; INGCO BG61502 sử dụng đ&aacute; c&oacute; đường k&iacute;nh 150mm (6 inch), kết hợp với c&ocirc;ng suất 150w gi&uacute;p qu&aacute; tr&igrave;nh l&agrave;m việc nhanh v&agrave; hiệu quả hơn. M&aacute;y m&agrave;i hai đ&aacute; để b&agrave;n INGCO BG61502 l&agrave; sản phẩm chất lượng được nhiều kh&aacute;ch h&agrave;ng đ&aacute;nh gi&aacute; cao về mẫu m&atilde;, thiết kế cũng như gi&aacute; th&agrave;nh hợp l&yacute;.</p>\n\n<p>&nbsp;</p>\n\n<p>Th&ocirc;ng số kỹ thuật:</p>\n\n<p>- Điện thế: 220-240V~50-60Hz;</p>\n\n<p>- C&ocirc;ng suất: 150 W,</p>\n\n<p>- Tốc độ kh&ocirc;ng tải: 2950 v/p;</p>\n\n<p>- K&iacute;ch thước đ&aacute; m&agrave;i: 150mm;</p>\n\n<p>- K&egrave;m theo 1 bộ nắp che chắn v&agrave; 1 hộp dụng cụ.</p>\n\n<p>===============================================</p>\n\n<p>Tự h&agrave;o l&agrave; nơi ph&acirc;n phối sản phẩm ch&iacute;nh h&atilde;ng đến tay người ti&ecirc;u d&ugrave;ng.</p>\n', 'hcspar151-1_20240104040445.webp', 'resize_hcspar151-1_20240104040445.webp', 0, 'Máy mài để bàn 2 đá INGCO BG61502 sử dụng đá có đường kính 150mm (6 inch), kết hợp với công suất 150w giúp quá trình làm việc nhanh và hiệu quả hơn. Máy mài hai đá để bàn INGCO BG61502 là sản phẩm chất lượng được nhiều khách hàng đánh giá cao về mẫu mã, thiết kế cũng như giá thành hợp lý.\n\nThông số kỹ thuật:\n  - Điện thế: 220-240V~50-60Hz; \n  - Công suất: 150 W, \n  - Tốc độ không tải: 2950 v/p; \n  - Kích thước đá mài: 150mm;\n  - Kèm theo 1 bộ nắp che chắn và 1 hộp dụng cụ.\n===============================================\nTự hào là nơi phân phối sản phẩm chính hãng đến tay người tiêu dùng.', NULL, 1, 0, 0, 0, 0, 0, 748, 748, '2024-01-04', '2024-01-04', '', 'hcspar151-1_20240104040445.webp', 0, 'https://shopee.vn/M%C3%A1y-m%C3%A0i-2-%C4%91%E1%BA%A7u-INGCO-BG61502-c%C3%B4ng-su%E1%BA%A5t-150W-%C4%91%C3%A1-m%C3%A0i-150mm-CHI%CC%81NH-HA%CC%83NG-i.319087615.23437624493'),
(424, 1, 111, NULL, 0, 0, 'cam-bien-nhiet-do-moi-truong-mencke-tegtmeyer-ta-ext-rs485-mb', 'CẢM BIẾN NHIỆT ĐỘ MÔI TRƯỜNG MENCKE & TEGTMEYER Ta-ext-RS485-MB', '', '', NULL, 0, 0, NULL, '\r\n<p>Cảm biến nhiệt độ môi trường <strong>Ta-ext-RS485-MB</strong> được trang bị vỏ nhôm ổn định và cáp chịu thời tiết mạnh mẽ. Nhờ sử dụng các thành phần chất lượng hàng đầu, các cảm biến đạt được độ chính xác rất cao và lý tưởng để sử dụng trong môi trường công nghiệp, hệ thống điện mặt trời hoặc phòng kỹ thuật giám sát).</p>\r\n\r\n<p>Tất cả các cảm biến đều được cung cấp cùng với giao thức hiệu chuẩn cho bộ khuếch đại đo lường.</p>\r\n\r\n<p>Ngoài ra, độ chính xác của phép đo có thể được cải thiện với tùy chọn bảo vệ thời tiết (Shield Tamb-Si).</p>\r\n<script src=\"//cdn.public.flmngr.com/FLMNFLMN/widgets.js\"></script>\r\n', NULL, NULL, NULL, NULL, '\r\n<p>Cảm biến nhiệt độ môi trường Ta-ext-RS485-MB được trang bị vỏ nhôm ổn định và cáp chịu thời tiết mạnh mẽ. Nhờ sử dụng các thành phần chất lượng hàng đầu, các cảm biến đạt được độ chính xác rất cao và lý tưởng để sử dụng trong môi trường công nghiệp, hệ thống điện mặt trời hoặc phòng kỹ thuật giám sát).</p>\r\n\r\n<p>Tất cả các cảm biến đều được cung cấp cùng với giao thức hiệu chuẩn cho bộ khuếch đại đo lường.</p>\r\n\r\n<p>Ngoài ra, độ chính xác của phép đo có thể được cải thiện với tùy chọn bảo vệ thời tiết (Shield Tamb-Si).</p>\r\n\r\n<p><span style=\"font-size:20px;\"><strong>Thông số kỹ thuật:</strong></span></p>\r\n\r\n<ul>\r\n	<li>Truyền thông: Modbus RS485</li>\r\n	<li>Phạm vi đo: -40 đến +90°C</li>\r\n	<li>Điện áp hoạt động: 24VDC (10-28VDC)</li>\r\n	<li>Dòng diện 25mA ở 24VDC</li>\r\n	<li>Cách ly điện áp 1000VDC giữa RS485 và điện áp cấp nguồn.</li>\r\n	<li>Đầu dò cảm biến: PT1000 1/3 Loại B theo tiêu chuẩn EN 60751</li>\r\n	<li>Vỏ cảm biến được làm bằng INOX với đường kính 6mm và dài 50mm</li>\r\n	<li>Chiều dài cáp cảm biến: 3 m, được phủ PUR, được che chắn (LiYC11Y, 4 x 0,14 mm²)</li>\r\n	<li>Vật liệu vỏ nhôm sơn tĩnh điện</li>\r\n	<li>Cấp bảo vệ: IP67</li>\r\n	<li>Nhiệt độ hoạt động: đầu dò cảm biến: -40 to +90°C, Vỏ -40 to +80°C</li>\r\n	<li>Chiều dài cáp cảm biến: 6 m, được phủ PUR, được che chắn (LiYC11Y, 4 x 0,14 mm²)</li>\r\n	<li>Truyền thông: MT RS485</li>\r\n	<li>Phạm vi đo: -40 đến +90°C</li>\r\n	<li>Điện áp hoạt động: 10-28VDC</li>\r\n	<li>Đầu dò cảm biến: PT1000 1/3 Loại B theo tiêu chuẩn EN 60751</li>\r\n	<li>Vỏ cảm biến được làm bằng INOX, chiều dài cáp cảm biến 3M.</li>\r\n	<li>Vật liệu vỏ nhôm sơn tĩnh điện, cáp 6M</li>\r\n	<li>Cấp bảo vệ: IP67</li>\r\n	<li>Nhiệt độ hoạt động: đầu dò cảm biến: -40 to +90°C, Vỏ -40 to +80°C</li>\r\n</ul>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/RS485_1.png\" style=\"height: 350px;\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/RS485_2.png\" style=\"height: 350px;\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/RS485_3.png\" style=\"height: 350px;\"></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/RS485_4.png\" style=\"height: 350px;\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-4\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/RS485_5.jpg\" style=\"height: 350px;\"></div>\r\n</div>\r\n</div>\r\n<script src=\"//cdn.public.flmngr.com/FLMNFLMN/widgets.js\"></script>\r\n', 'RS485_1_20240529023715.png.webp', 'resize_RS485_1_20240529023715.png.webp', 0, 'Cảm biến nhiệt độ môi trường Ta-ext-RS485-MB được trang bị vỏ nhôm ổn định và cáp chịu thời tiết mạnh mẽ. Nhờ sử dụng các thành phần chất lượng hàng đầu, các cảm biến đạt được độ chính xác rất cao và lý tưởng để sử dụng trong môi trường công nghiệp, hệ thống điện mặt trời hoặc phòng kỹ thuật giám sát).', NULL, 1, 1, 0, 0, 1, 4, 1, 0, '2024-08-27', '2024-08-27', '', '.webp', 0, ''),
(422, 1, 111, NULL, 0, 0, 'cam-bien-do-buc-xa-mat-troi-sr20-d2-hukseflux', 'CẢM BIẾN ĐO BỨC XẠ MẶT TRỜI SR20-D2 HUKSEFLUX', '', '', NULL, 0, 0, NULL, '\r\n<ul>\r\n	<li>SR20D2 sử dụng cảm biến nhiệt điện hiện đại với bề mặt được phủ màu đen, hai vòm và thân bằng nhôm anod hóa. Đầu nối, bộ giữ chất hút ẩm và tấm chắn nắng rất chắc chắn và được thiết kế để sử dụng lâu dài trong công nghiệp.</li>\r\n	<li>SR20D2 đo bức xạ mặt trời mà một bề mặt phẳng nhận được, tính bằng W/m2, từ góc nhìn 180°. Nó được sử dụng khi cần độ chính xác đo cao nhất.</li>\r\n	<li>SR20D2 cung cấp hai loại đầu ra thường được sử dụng trong ngành quang điện mặt trời: kỹ thuật số qua Modbus RTU qua RS-485 và analog 4-20 mA (vòng lặp dòng điện). Các tiêu chuẩn công nghiệp này cho phép thu thập dữ liệu dễ dàng, dễ đọc và trao đổi thiết bị không có lỗi khi sử dụng SR20-D2.</li>\r\n	<li>Hukseflux cung cấp phần mềm quản lý cho phép người dùng theo dõi giám sát và thay đổi địa chỉ Modbus của thiết bị.</li>\r\n</ul>\r\n<script src=\"//cdn.public.flmngr.com/FLMNFLMN/widgets.js\"></script>\r\n', NULL, NULL, NULL, NULL, '\r\n<p style=\"margin-top:0in; margin-right:0in; margin-bottom:.0001pt\"><span style=\"font-size:12pt\"><span style=\"background:white\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\"> </span></span></span></p>\r\n\r\n<h6><strong>Thông số kỹ thuật:</strong></h6>\r\n\r\n<ul>\r\n	<li>Phân loại ISO 9060:2018: Pyranometer loại A phổ phẳng.</li>\r\n	<li>Phân loại ISO 9060:1990: tiêu chuẩn thứ cấp.</li>\r\n	<li>Tuân thủ IEC 61724-1:2021, giám sát PV loại A.</li>\r\n	<li>Đầu ra: 4-20mA, Modbus RS-485.</li>\r\n	<li>Độ chính xác hiệu chuẩn: &lt;1.2% (k = 2).</li>\r\n	<li>Phạm vi bước sóng: 285 đến 3000 x 10⁻⁹ m.</li>\r\n	<li>Nhiệt độ hoạt động: -40 đến +80 °C.</li>\r\n	<li>Chiều dài cáp chuẩn: 5 m.</li>\r\n	<li>Điện áp hoạt động định mức: 5-30VDC.</li>\r\n	<li>Giao thức truyền thông: Modbus.</li>\r\n	<li>Giao diện phần cứng: 2 dây (half duplex) RS 485.</li>\r\n	<li>Đầu ra số: Bức xạ trong W/m² và nhiệt độ °C.</li>\r\n	<li>Đầu ra tương tự: 4-20mA</li>\r\n	<li>Phạm vi truyền tải: 0-1600 W/m².</li>\r\n	<li>Tiêu chuẩn ISO 9060:2008: Quang phổ phẳng loại A.</li>\r\n	<li>Dãi quang phổ đo: 285 đến 3000 x 10⁻⁹ m.</li>\r\n	<li>Nhiệt độ hoạt động: -40 đến +80 °C.</li>\r\n	<li>Điện áp định mức: 5-30VDC</li>\r\n	<li>Chiều dài cáp kết nối: 5m</li>\r\n	<li>Tùy chọn ngõ ra: Modbus RTU hoặc Analog (4-20mA)</li>\r\n	<li>Phạm vi truyền tải: 0-1600 W/m².</li>\r\n</ul>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SR20_1.png\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-6\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SR20_2.png\"></div>\r\n</div>\r\n</div>\r\n\r\n<div class=\"row\">\r\n<div class=\"col-md-6\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SR20_3.png\"></div>\r\n</div>\r\n\r\n<div class=\"col-md-6\">\r\n<div class=\"item-obj\"><img src=\"/fileman/Uploads/cambien_bxmt/SR20_4.png\"></div>\r\n</div>\r\n</div>\r\n<script src=\"//cdn.public.flmngr.com/FLMNFLMN/widgets.js\"></script>\r\n', '11_20240819095618.png.webp', 'resize_11_20240819095618.png.webp', 0, 'SR20-D2 sử dụng cảm biến nhiệt điện hiện đại với bề mặt được phủ màu đen, hai vòm và thân bằng nhôm anod hóa.', NULL, 1, 1, 0, 0, 1, 2, 1, 0, '2024-08-19', '2024-08-19', '', '.webp', 0, ''),
(426, 1, 111, NULL, 0, 0, 'cam-bien-do-buc-xa-mat-troi-pyranometer-smp10-kipp-zonen', 'Cảm Biến Đo Bức Xạ Mặt Trời Pyranometer SMP10 – KIPP & ZONEN', '', '', NULL, 0, 0, NULL, '\r\n<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\">SMP10 là máy đo nhiệt độ loại A phẳng và có chất hút ẩm bên trong sẽ tồn tại ít nhất 10 năm nếu vỏ không được mở.&nbsp;Điều này giảm thiểu đáng kể việc bảo trì.</span></span></span></span></p>\r\n<script src=\"//cdn.flmngr.com/widgets.js?apiKey=FLMNFLMN\"></script>\r\n', NULL, NULL, NULL, NULL, '\r\n<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\">SMP10 là máy đo nhiệt độ loại A phẳng và có chất hút ẩm bên trong sẽ tồn tại ít nhất 10 năm nếu vỏ không được mở.&nbsp;Điều này giảm thiểu đáng kể việc bảo trì.</span></span></span></span></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><img alt=\"Cảm Biến Đo Bức Xạ Mặt Trời Pyranometer SMP10 – KIPP &amp; ZONEN\" class=\"img-fluid\" src=\"https://toandanhco.com.vn/fileman/Uploads/product/01_Pyranometers_07a_SMP10_01_SMP10-logo.webp\"></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\">Từ phản ứng nhiệt độ được đo riêng lẻ, hàm hiệu chỉnh đa thức cụ thể được tính toán cho SMP10.&nbsp;Điều này được tải vào bộ nhớ của máy đo nhiệt độ và dẫn đến sự thay đổi độ nhạy rất thấp theo nhiệt độ của thiết bị: Trong khoảng ± 2% trong phạm vi từ -40°C đến +70°C, so với nhiệt độ hiệu chuẩn là +22°C.</span></span></span></span></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\">&nbsp;</p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\">Khoảng thời gian làm sạch vòm có thể được kéo dài và chất lượng của phép đo được tối đa hóa bằng cách lắp SMP10 với bộ thông gió CVF4.</span></span></span></span></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\">SMP10 có giao diện Modbus®, đầu ra analog được khuếch đại, thời gian phản hồi được cải thiện và dữ liệu đo được điều chỉnh nhiệt độ.&nbsp;Phạm vi cung cấp điện rộng và thấp từ 5 đến 30 VDC giúp việc tích hợp vào các trạm năng lượng mặt trời và khí tượng trở nên dễ dàng.&nbsp;SMP10 được bảo vệ chống quá điện áp, đảo cực và đoản mạch.</span></span></span></span></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><img alt=\"Cảm Biến Đo Bức Xạ Mặt Trời Pyranometer SMP10 – KIPP &amp; ZONEN\" class=\"img-fluid\" src=\"https://toandanhco.com.vn/fileman/Uploads/product/01_Pyranometers_07a_SMP10_02_SMP10_without_sunscreen-logo.webp\"></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\">Nhờ đầu ra và kết nối được tiêu chuẩn hóa của mọi SMP10, việc trao đổi thiết bị để hiệu chuẩn lại trở nên dễ dàng.</span></span></span></span></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><img alt=\"Cảm Biến Đo Bức Xạ Mặt Trời Pyranometer SMP10 – KIPP &amp; ZONEN\" class=\"img-fluid\" src=\"https://toandanhco.com.vn/fileman/Uploads/product/01_Pyranometers_07a_SMP10_04_Bubble_level-logo.webp\"></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\">Phần mềm SmartExplorer Windows™ để ghi dữ liệu, hiển thị dữ liệu và cài đặt địa chỉ Modbus® được cung cấp theo tiêu chuẩn.</span></span></span></span></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><img alt=\"Cảm Biến Đo Bức Xạ Mặt Trời Pyranometer SMP10 – KIPP &amp; ZONEN\" class=\"img-fluid\" src=\"https://toandanhco.com.vn/fileman/Uploads/product/01_Pyranometers_07a_SMP10_05_Connector-logo.webp\"></p>\r\n\r\n<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><b><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\">THÔNG SỐ KỸ THUẬT</span></b></span></span></span></p>\r\n\r\n<table class=\"Table\" style=\"width:656.15pt; background:white; border:none\" width=\"875\">\r\n	<tbody>\r\n		<tr style=\"height:17.7pt\">\r\n			<td style=\"border:none; border-bottom:solid #ececec 1.0pt; background:white; width:141.75pt; padding:6.0pt 6.0pt 6.0pt 0in; height:17.7pt\" width=\"189\">\r\n			<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\"><span style=\"color:black\">Cảm biến</span></span><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\"></span></span></span></span></p>\r\n			</td>\r\n			<td style=\"border:none; border-bottom:solid #ececec 1.0pt; background:white; padding:6.0pt 0in 6.0pt 6.0pt; height:17.7pt\">\r\n			<p style=\"margin:0in 0in 8pt\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Aptos,sans-serif\"><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\"><span style=\"color:black\">Thermopile phủ đen chất lượng rất cao được bảo vệ bởi hai mái vòm kính</span></span><span new=\"\" roman=\"\" style=\"font-family:\" times=\"\"></span></span></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr style=\"height:13.05pt\">\r\n			<td style=\"border:none; border-bottom:solid #ececec 1.0pt; background:white; width:141.75pt; padding:6.0p